window.TL=[{"de": 1, "focus_luat": ["L1", "L3", "L5", "L7"], "focus_bai": ["B1", "B7", "B14"], "p1": [{"q": "Câu 1 (0,75đ). Luật Viên chức số 129/2025/QH15: (a) cho biết ngày có hiệu lực và văn bản nào hết hiệu lực khi Luật này có hiệu lực; (b) nêu khái niệm viên chức; (c) viên chức được ký hợp đồng làm việc với tối đa mấy đơn vị sự nghiệp công lập? Nêu căn cứ.", "a": ["(a) **Hiệu lực từ 01/7/2026** (Điều 43 khoản 1); Quốc hội thông qua ngày 10/12/2025. Luật Viên chức 58/2010/QH12 (sửa đổi bởi Luật 52/2019/QH14) hết hiệu lực từ ngày Luật mới có hiệu lực (Điều 43 khoản 2). (0,25đ)", "(b) Viên chức là công dân Việt Nam, được tuyển dụng theo vị trí việc làm, làm việc tại đơn vị sự nghiệp công lập theo chế độ hợp đồng làm việc, hưởng lương từ quỹ tiền lương của đơn vị sự nghiệp công lập và từ các nguồn thu hợp pháp khác (Điều 1). (0,25đ)", "(c) Chỉ được ký hợp đồng làm việc với **01 đơn vị** sự nghiệp công lập và chịu sự quản lý của đơn vị đó (Điều 8 khoản 5). (0,25đ)"]}, {"q": "Câu 2 (0,75đ). Theo Luật Nhà giáo số 73/2025/QH15, nhà giáo không được làm những việc gì đối với người học (Điều 11 khoản 2)? Điều này khác gì với quy định tại Điều 22 Luật Giáo dục về việc ép học thêm?", "a": ["Nhà giáo **không được** (Điều 11 khoản 2), mỗi ý đúng 0,1đ, đủ 5 ý được 0,5đ:", "- Phân biệt đối xử giữa những người học dưới mọi hình thức;", "- Gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học;", "- Ép buộc người học tham gia học thêm **dưới mọi hình thức**;", "- Ép buộc người học nộp tiền hoặc hiện vật ngoài quy định của pháp luật;", "- Lợi dụng chức danh nhà giáo và hoạt động nghề nghiệp để thực hiện hành vi vi phạm pháp luật.", "Phân biệt (0,25đ): Điều 22 Luật Giáo dục (khoản 5) chỉ cấm \"ép buộc học sinh học thêm **để thu tiền**\"; Luật Nhà giáo Điều 11.2.c cấm ép học thêm **dưới mọi hình thức** (rộng hơn, không cần mục đích thu tiền).", "Lưu ý: quyền của nhà giáo là Điều 8, nghĩa vụ là Điều 9 (không nhầm với Điều 9-10)."]}, {"q": "Câu 3 (0,75đ). Theo Nghị định 259/2026/NĐ-CP, thi tuyển viên chức gồm mấy vòng? Nêu nội dung, thời gian vòng 1 và điều kiện để được dự thi vòng 2. Thi tuyển giáo viên có điểm gì khác (nêu hình thức vòng 2 theo Nghị định 93/2026/NĐ-CP)?", "a": ["**Hai vòng** (Điều 11 NĐ 259). (0,1đ)", "Vòng 1 (thi trắc nghiệm trên máy tính): (a) kiến thức chung **60 câu, 60 phút**; (b) ngoại ngữ theo thông báo tuyển dụng, tối đa 60 phút (số câu do Hội đồng quyết định; có văn bằng/chứng chỉ phù hợp thì miễn). (0,25đ)", "Điều kiện dự vòng 2: trả lời đúng **từ 50% số câu trở lên của từng phần**. (0,15đ)", "Vòng 2 viên chức nói chung: thi nghiệp vụ chuyên ngành, chọn 1 trong 2 hình thức: thực hành, hoặc kết hợp viết và phỏng vấn (thang 100; viết 70%, phỏng vấn 30%).", "Giáo viên (NĐ 93 Điều 7): vòng 1 gồm kiến thức chung 60 câu/60 phút và ngoại ngữ 30 câu/30 phút (nếu vị trí yêu cầu); **vòng 2 là thực hành sư phạm**, người đứng đầu chọn 1 trong 3 hình thức: vấn đáp, thực hành giảng dạy hoặc thi viết; thang 100 điểm. (0,25đ)", "Ghi chú: ưu tiên áp dụng NĐ 93 cho vị trí giáo viên; cần đối chiếu thông báo tuyển dụng của địa phương (đối chiếu văn bản gốc)."]}, {"q": "Câu 4 (0,75đ). Thông tư 03/2026/TT-BGDĐT về quy tắc ứng xử của nhà giáo: (a) ban hành ngày nào, thay thế văn bản nào; (b) quy tắc ứng xử chia thành mấy nhóm quan hệ? Kể tên; (c) khi phát hiện học sinh bị bạo lực, xâm hại, nhà giáo phải làm gì?", "a": ["(a) Ban hành và có hiệu lực **30/01/2026**; gồm 03 chương, 15 điều; thay thế Quyết định 16/2008/QĐ-BGDĐT (đạo đức nhà giáo) và Điều 6 Thông tư 06/2019/TT-BGDĐT. (0,25đ)", "(b) **6 nhóm** (Điều 4-9): ứng xử chung; với người học; với đồng nghiệp; với cán bộ quản lý cơ sở giáo dục; với cha mẹ hoặc người giám hộ của người học; với cộng đồng. (0,25đ)", "(c) **Phải báo cáo kịp thời** với lãnh đạo, cơ quan có thẩm quyền (Điều 5 khoản 4); không thờ ơ, né tránh hoặc che giấu hành vi vi phạm (Điều 4 khoản 6). (0,25đ)", "Ghi chú: số điều của phần phạm vi, mục đích, nguyên tắc và tổ chức thực hiện của TT03 cần đối chiếu văn bản gốc."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 2: Phần mềm máy tính]. (a) Nêu khái niệm hệ điều hành và các chức năng chính. (b) Phân biệt phần mềm hệ thống và phần mềm ứng dụng, mỗi loại cho 2 ví dụ. (c) Vì sao nói Windows Explorer, Microsoft Word không phải là hệ điều hành?", "a": ["(a) **Hệ điều hành** là phần mềm hệ thống, chạy đầu tiên khi bật máy, quản lí và điều khiển phần cứng, tạo môi trường để các phần mềm khác hoạt động. Chức năng (0,25đ): điều khiển phần cứng, quản lí thiết bị và dữ liệu; cung cấp giao diện người dùng; tổ chức, cho phép chạy các phần mềm ứng dụng (đối chiếu SGK tr.11 về cách gộp thành 3 chức năng).", "(b) (0,25đ) **Phần mềm hệ thống**: điều khiển, quản lí máy tính, làm nền cho phần mềm khác (Windows, macOS, Linux; iOS, Android). **Phần mềm ứng dụng**: giúp người dùng làm công việc cụ thể (soạn thảo Word, trình duyệt, Scratch, trò chơi).", "(c) (0,25đ) Windows Explorer chỉ là ứng dụng quản lí tệp, thư mục chạy **trên** hệ điều hành; Word là phần mềm ứng dụng soạn thảo: chúng không điều khiển phần cứng, không quản lí toàn bộ tài nguyên máy.", "Bổ sung (0,25đ): phần mở rộng tên tệp cho biết loại tệp và phần mềm mở nó (ví dụ .docx - Word, .xlsx - Excel, .pptx - PowerPoint, .sb3 - Scratch)."]}, {"q": "Câu 2 (1,5đ) [Tin 7 – Bài 11: Tạo bài trình chiếu]. Một nhóm làm bài trình chiếu \"Trường học xanh\" gồm 1 trang tiêu đề (có 1 tiêu đề và 1 phụ đề) và 4 trang nội dung. Mỗi trang nội dung có 1 tiêu đề trang, 3 ý chính (cấp 1) và mỗi ý chính có đúng 2 ý phụ (cấp 2). Nhóm gõ nội dung liên tục bằng bàn phím, ý phụ dùng Tab để hạ cấp, quay lại ý chính dùng Shift+Tab. (a) Bài có bao nhiêu trang? Tổng số dòng văn bản phải nhập là bao nhiêu? (b) Mỗi trang nội dung phải bấm Tab và Shift+Tab bao nhiêu lần? Cả bài? (c) Phân biệt trang tiêu đề với tiêu đề trang và nêu bố cục (layout) nên chọn cho từng loại trang.", "a": ["(a) Số trang = 1 + 4 = **5 trang**. (0,5đ)", "Dòng văn bản: trang tiêu đề 2 dòng (tiêu đề + phụ đề); mỗi trang nội dung 1 + 3 + 3x2 = 10 dòng => 4 x 10 = 40. Tổng = 2 + 40 = **42 dòng**.", "(b) (0,5đ) Mỗi trang: gõ ý chính 1, Enter, Tab (1) rồi gõ 2 ý phụ; Enter, Shift+Tab (1) gõ ý chính 2; tương tự ý chính 3 => **3 lần Tab và 2 lần Shift+Tab** mỗi trang (ý phụ thứ 2 nằm cùng cấp với ý phụ thứ nhất nên không cần Tab).", "Cả bài: Tab = 3 x 4 = **12 lần**; Shift+Tab = 2 x 4 = **8 lần** (ghi chú: chuyển sang trang mới dùng lệnh New Slide, không tính vào Tab).", "(c) (0,5đ) **Trang tiêu đề**: trang đầu tiên, nêu tên bài trình bày, tác giả; layout Title Slide. **Tiêu đề trang**: dòng tên chủ đề ở đầu mỗi trang nội dung; layout Title and Content (hoặc Title Only). Hạ cấp giúp thể hiện cấu trúc phân cấp, ý chính - ý phụ rõ ràng, dễ theo dõi."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 8a: Danh sách liệt kê và hình ảnh trong văn bản]. Hãy xây dựng mục tiêu bài học (theo chương trình GDPT 2018: năng lực tin học, năng lực chung, phẩm chất) và thiết kế **hoạt động khám phá kiến thức về danh sách dạng liệt kê** theo 4 bước chuyển giao - thực hiện - báo cáo - kết luận. Cho biết sản phẩm học tập của hoạt động.", "a": ["Mục tiêu (0,5đ):", "- Kiến thức: nêu được hai kiểu danh sách (dấu đầu dòng, có thứ tự) và tác dụng; biết chèn, co dãn ảnh, vẽ hình đồ họa trong Word.", "- Năng lực tin học: **NLa** (sử dụng phần mềm soạn thảo để tạo danh sách, chèn ảnh); **NLd** (ứng dụng tin học trong học tập: trình bày tờ rơi, danh sách); **NLb** (ghi nguồn ảnh, tôn trọng bản quyền; khai báo khi dùng AI).", "- Năng lực chung: tự chủ - tự học, giao tiếp - hợp tác (làm việc nhóm). Phẩm chất: chăm chỉ, trung thực (không sao chép, ghi nguồn).", "Hoạt động khám phá (1đ):", "- **Chuyển giao**: GV chiếu Hình 8a.1 (danh sách 500 mục), hỏi: có phải gõ từng số không? Phát phiếu học tập: so sánh danh sách dấu đầu dòng và có thứ tự qua 2 ví dụ (bước nấu ăn, đồ dùng học tập); nêu cách tạo (Bullets/Numbering).", "- **Thực hiện**: nhóm 4 HS thảo luận Think-Pair-Share, thử trên máy: gõ Enter tạo mục mới, xóa mục giữa xem số tự cập nhật, dùng Tab xuống cấp. GV quan sát, hỗ trợ nhóm yếu.", "- **Báo cáo**: đại diện 2 nhóm trình bày kết quả; nhóm khác nhận xét, đặt câu hỏi; GV ghi nhận chênh lệch.", "- **Kết luận**: GV chốt: dấu đầu dòng khi các mục ngang hàng; có thứ tự khi có trình tự; số tự động cập nhật khi thêm bớt; Tab để tạo danh sách nhiều cấp; lưu ý lỗi gõ số tay.", "Sản phẩm: phiếu học tập hoàn thành và tệp Word có hai danh sách (một kiểu mỗi loại)."]}, {"q": "Câu 4 (1đ) [Tin 8 – Bài 8a, tích hợp AI]. Trong tiết dạy, GV hỏi chatbot \"Nêu hai kiểu danh sách trong Word và cách tạo\", chiếu nguyên văn kết quả lên bảng rồi yêu cầu cả lớp chép vào vở \"vì AI trả lời rất nhanh và đúng\". Hãy nhận xét đoạn dạy trên (ưu điểm, hạn chế) và đề xuất cách điều chỉnh để phát triển năng lực số/AI của học sinh (nêu ít nhất 2 mã yêu cầu cần đạt trong tài liệu năng lực AI).", "a": ["Nhận xét (0,4đ): Ưu điểm - dùng công nghệ tạo tình huống, tiết kiệm thời gian, gợi hứng thú. Hạn chế - **tuyệt đối hóa AI**, HS thụ động chép, không kiểm chứng; AI có thể sai hoặc thiếu; chưa khai báo nguồn; chưa phát triển năng lực tự học, tư duy phản biện.", "Điều chỉnh (0,6đ): cho HS **đối chiếu kết quả chatbot với SGK** (Bài 8a, tr.36 trở đi), tìm chỗ thiếu/sai; thực hành thao tác trên Word để kiểm chứng; thảo luận độ tin cậy; HS ghi nguồn và **khai báo khi dùng AI**.", "Mã/yêu cầu liên quan: **8.A1.2** (kiểm chứng kết quả AI), **8.A3.3**, **8.B2.1** (theo tài liệu KHDH/kw của bài; đối chiếu mã năng lực AI trong tài liệu gốc).", "Có thể liên hệ NLS 3.1.TC2.a (tạo, chỉnh sửa nội dung số) của bài."]}], "p3": [{"q": "Tình huống (2đ): Em Hùng (lớp 8A, lớp thầy/cô dạy Tin học và là giáo viên chủ nhiệm) gần đây hay ngủ gật, bỏ tiết cuối, điểm sa sút. Qua bạn bè thầy/cô biết Hùng chơi game liên tục đến khuya, thậm chí trốn tiết ra quán internet. Cha mẹ Hùng đi làm xa, ở với ông bà. Hãy nêu cách xử lí và căn cứ.", "a": ["**Bước 1 - Tìm hiểu, không vội kết luận (0,4đ)**: nói chuyện riêng, lắng nghe, tìm nguyên nhân (áp lực, cô đơn, bạn bè rủ rê); xác minh qua bạn, giáo viên bộ môn, sổ theo dõi; **không công khai** thông tin của em trước lớp (TT03/2026 Điều 5 khoản 4).", "**Bước 2 - Tư vấn, hỗ trợ (0,4đ)**: động viên, đưa ra mục tiêu nhỏ, hướng dẫn quản lí thời gian, hoạt động thay thế (CLB, thể thao); phối hợp tư vấn tâm lí học đường (HS có quyền được tư vấn tâm lí - TT15/2026 Điều 33 khoản 6); lồng ghép bài học Tin 7 Bài 5 về nghiện Internet (chia sẻ - rời xa - giới hạn - theo đuổi).", "**Bước 3 - Phối hợp gia đình (0,4đ)**: mời ông bà, liên hệ cha mẹ qua điện thoại; trao đổi thông tin trung thực về học sinh; thỏa thuận quy tắc dùng thiết bị ở nhà (TT03/2026 Điều 8 khoản 1, 2: hợp tác vì sự tiến bộ của người học, thông tin trung thực khi được cấp quản lí đồng ý theo thẩm quyền). Gia đình có trách nhiệm giáo dục con (Luật Giáo dục Điều 16 khoản 3 - phối hợp nhà trường, gia đình, xã hội).", "**Bước 4 - Báo cáo, phối hợp nhà trường và địa phương (0,4đ)**: báo cáo hiệu trưởng/ban giám hiệu; nhờ Đoàn - Đội, giáo viên bộ môn cùng theo dõi; phối hợp chính quyền, công an xã nếu tiệm internet cho HS vào trong giờ học (xã hội có trách nhiệm - Luật Giáo dục Điều 16 khoản 3). Giáo viên chủ nhiệm được quyền cho phép HS nghỉ học có lý do chính đáng không quá 03 ngày liên tục (TT15/2026 Điều 26 khoản 3), không tự ý vượt quyền.", "**Bước 5 - Theo dõi, đánh giá (0,2đ)**: ghi nhận tiến bộ, đánh giá đúng thực chất, không phân biệt đối xử, không trù dập (TT03/2026 Điều 5 khoản 3, 4; Luật Nhà giáo Điều 9 khoản 2 điểm d; Điều 11 khoản 2 điểm a).", "Lưu ý khi chấm: thái độ thấu hiểu, giáo dục là chính; **không** đánh mắng, công khai danh tính, không ép buộc; nếu nghi có dấu hiệu bị rủ rê vào tệ nạn (cờ bạc, cá độ) phải báo cáo cấp có thẩm quyền (đối chiếu quy định hiện hành)."]}]}, {"de": 2, "focus_luat": ["L2", "L4", "L6", "L8"], "focus_bai": ["B2", "B8", "B15"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Giáo dục 43/2019/QH14 (đã sửa đổi bởi Luật 123/2025/QH15): (a) giáo dục THCS học trong mấy năm, tuổi vào lớp sáu là bao nhiêu; (b) giáo dục bắt buộc gồm những cấp học nào, áp dụng từ khi nào; (c) học sinh học hết chương trình THCS nhận được gì?", "a": ["(a) THCS **04 năm học**, từ lớp sáu đến hết lớp chín; tuổi vào lớp sáu là **11 tuổi** (tính theo năm) (Điều 28 khoản 1 điểm b). (0,25đ)", "(b) **Giáo dục tiểu học và giáo dục THCS là giáo dục bắt buộc** (Điều 14 khoản 1 mới, do Luật 123/2025 sửa); nội dung này có hiệu lực từ **01/7/2026**; đồng thời Nhà nước phổ cập giáo dục mầm non cho trẻ từ 03 đến 06 tuổi. (0,25đ)", "(c) Đủ điều kiện thì được **hiệu trưởng xác nhận vào học bạ** việc hoàn thành chương trình THCS (Điều 34 khoản 1 mới); từ 01/01/2026 không còn cấp bằng tốt nghiệp THCS (bằng đã cấp trước đó vẫn có giá trị). (0,25đ)"]}, {"q": "Câu 2 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) giáo viên THCS có chia hạng I, II, III không? (b) Những ai được cộng 5 điểm ưu tiên khi tuyển dụng nhà giáo, cộng vào điểm vòng nào, và nếu thuộc nhiều diện thì xử lí ra sao? (c) Vòng 2 thi tuyển nhà giáo có những hình thức nào?", "a": ["(a) **Không chia hạng**: \"giáo viên trung học cơ sở\" là một chức danh (Điều 3 khoản 1); chỉ giảng viên mới phân cấp. (0,15đ)", "(b) Cộng **05 điểm** vào kết quả điểm **vòng 2** (Điều 6): (1) người có thời gian giảng dạy, giáo dục đúng vị trí cần tuyển (hoặc cấp học/trình độ khác nhưng môn học phù hợp) từ **đủ 03 năm (36 tháng)** trở lên, có đóng BHXH bắt buộc (không liên tục thì cộng dồn, chưa nhận BHXH một lần); (2) người có chứng chỉ kỹ năng nghề quốc gia bậc 4 trở lên hoặc kinh nghiệm thực tế sản xuất, kinh doanh, dịch vụ phù hợp từ đủ 03 năm có đóng BHXH. Thuộc nhiều diện chỉ cộng **điểm cao nhất** (khoản 4). (0,4đ)", "(c) Vòng 2 là thực hành sư phạm; người đứng đầu chọn 1 trong 3: vấn đáp (30 phút, chuẩn bị ≤ 15 phút), thực hành giảng dạy, hoặc thi viết (180 phút); thang 100 điểm (Điều 7 khoản 2). (0,2đ)"]}, {"q": "Câu 3 (0,75đ). Theo Nghị quyết 248/2025/QH15 của Quốc hội: (a) ai có thẩm quyền tuyển dụng, tiếp nhận nhà giáo cơ sở giáo dục công lập phổ thông; (b) mức phụ cấp ưu đãi nghề tối thiểu của giáo viên, nhân viên và giáo viên vùng đặc biệt khó khăn; (c) thời điểm thực hiện một bộ sách giáo khoa dùng thống nhất toàn quốc và mốc hoàn thành cấp miễn phí; (d) tỷ lệ chi ngân sách cho giáo dục.", "a": ["(a) **Giám đốc Sở GDĐT** (Điều 2 khoản 1 điểm a). (0,15đ)", "(b) Theo lộ trình Chính phủ quy định: tối thiểu **70%** đối với giáo viên; **30%** đối với nhân viên; **100%** đối với giáo viên công tác ở biên giới, hải đảo, vùng đồng bào dân tộc thiểu số và miền núi, vùng đặc biệt khó khăn (Điều 2 khoản 2 điểm a). (0,25đ)", "(c) Bộ trưởng Bộ GDĐT quyết định **một bộ SGK**, thực hiện từ **năm học 2026-2027**; đến **năm 2030** hoàn thành cung cấp miễn phí SGK cho học sinh (Điều 3 khoản 1). (0,2đ)", "(d) Tối thiểu **20% tổng chi ngân sách nhà nước** cho giáo dục và đào tạo (Điều 6 khoản 4). (0,15đ)", "Lưu ý: NQ 248 không quy định miễn học phí phổ thông; nội dung này ở Luật Giáo dục Điều 99 khoản 3 (mới)."]}, {"q": "Câu 4 (0,75đ). Theo Nghị quyết 71-NQ/TW ngày 22/8/2025 của Bộ Chính trị về đột phá phát triển giáo dục và đào tạo: (a) có mấy quan điểm chỉ đạo, mấy nhóm nhiệm vụ giải pháp; (b) nêu 3 mục tiêu đến năm 2030; (c) nêu chủ trương về công nghệ, AI trong giáo dục phổ thông.", "a": ["(a) **6 quan điểm** chỉ đạo; **8 nhóm** nhiệm vụ, giải pháp. Phương châm \"thầy ra thầy, trò ra trò\". (0,2đ)", "(b) Đến 2030 (chọn 3, mỗi ý 0,1đ): ít nhất **80%** trường phổ thông đạt chuẩn quốc gia; hoàn thành phổ cập giáo dục mầm non cho trẻ **3 đến 5 tuổi** và giáo dục bắt buộc hết THCS; ít nhất **85%** người trong độ tuổi hoàn thành THPT và tương đương (không tỉnh nào dưới 60%); bước đầu nâng năng lực công nghệ, AI và tiếng Anh ở phổ thông; 100% cơ sở đại học đạt chuẩn quốc gia. (0,3đ)", "(c) Ứng dụng AI **có kiểm soát** (nền tảng giáo dục quốc gia); nâng chuẩn năng lực số và AI cho người học và nhà giáo; nghiên cứu đưa năng lực số, AI vào chương trình phổ thông; tăng thời lượng khoa học, công nghệ, tin học; sách giáo khoa, giáo trình thông minh. (0,25đ)"]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 3: Quản lí dữ liệu trong máy tính]. (a) Vì sao nói \"chương trình cũng là dữ liệu\"? Nêu ít nhất 2 phần mở rộng của tệp chương trình. (b) Nêu nguyên tắc đặt tên tệp, thư mục dễ nhớ và lợi ích của cây thư mục. (c) Nêu các biện pháp bảo vệ dữ liệu: sao lưu (cục bộ, từ xa), mật khẩu mạnh, phần mềm chống virus.", "a": ["(a) (0,25đ) Chương trình được lưu thành tệp, máy tính xử lí như mọi dữ liệu khác (sao chép, di chuyển, xóa được). Phần mở rộng của tệp chương trình: **.exe, .com, .bat, .msi**.", "(b) (0,25đ) Tên tệp, thư mục ngắn gọn, gợi nhớ nội dung, phân biệt được; tổ chức thành **cây thư mục** (thư mục cha - con) để dễ tìm, dễ quản lí, tránh trùng lặp.", "(c) (0,5đ) **Sao lưu**: tạo bản sao dữ liệu; sao lưu cục bộ (ổ cứng ngoài, USB, thẻ nhớ) và sao lưu từ xa (đám mây) - chọn theo dung lượng, độ tiện, độ an toàn (Bảng 3.1). **Mật khẩu mạnh**: từ 8 kí tự trở lên, có chữ hoa, chữ thường, số, kí hiệu; không dùng tên, ngày sinh. **Chống virus**: cài phần mềm chống virus, luôn bật và cập nhật thường xuyên; thận trọng với tệp lạ."]}, {"q": "Câu 2 (1,5đ) [Tin 7 – Bài 14: Thuật toán tìm kiếm tuần tự]. Cho danh sách số điện thoại rút gọn gồm 8 số theo thứ tự: 12, 7, 25, 3, 18, 9, 30, 14 (vị trí 1 đến 8). (a) Mô phỏng thuật toán tìm kiếm tuần tự để tìm số 9, ghi bảng theo dõi từng lần so sánh và cho biết số lần so sánh. (b) Tìm số 20: kết quả và số lần so sánh. (c) Với danh sách n phần tử, số lần so sánh nhiều nhất là bao nhiêu? Nếu số cần tìm có thể ở 8 vị trí với khả năng như nhau thì số lần so sánh trung bình là bao nhiêu? (d) Nêu hai điều kiện dừng của thuật toán.", "a": ["(a) (0,5đ) Bảng: lần 1: 12 ≠ 9; lần 2: 7 ≠ 9; lần 3: 25 ≠ 9; lần 4: 3 ≠ 9; lần 5: 18 ≠ 9; lần 6: 9 = 9 => dừng, **tìm thấy ở vị trí 6, sau 6 lần so sánh**.", "(b) (0,3đ) So sánh lần lượt cả 8 số đều khác 20, hết danh sách => kết quả **không tìm thấy**, **8 lần so sánh**.", "(c) (0,4đ) Nhiều nhất **n lần** (số cần tìm ở cuối danh sách hoặc không có). Trung bình khi 8 vị trí khả năng như nhau: (1+2+...+8)/8 = 36/8 = **4,5 lần**.", "(d) (0,3đ) Điều kiện dừng 1: gặp đối tượng cần tìm (đưa ra vị trí). Điều kiện dừng 2: đã xét hết danh sách mà không thấy (đưa ra \"không tìm thấy\"). Thuật toán luôn dừng sau hữu hạn bước.", "Lưu ý chấm: HS hay quên điều kiện dừng thứ hai hoặc xét tiếp dù đã tìm thấy."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 8b: Phần mềm chỉnh sửa ảnh]. Hãy đề xuất **phương pháp, kĩ thuật dạy học** cho nội dung \"lớp ảnh\" (GIMP) và xây dựng **tiêu chí đánh giá** sản phẩm thực hành \"cắt bỏ vật che khuất trong ảnh phong cảnh trường\". Nêu năng lực, phẩm chất cần hình thành và trình bày hoạt động dạy học theo 4 bước chuyển giao - thực hiện - báo cáo - kết luận.", "a": ["Phương pháp, kĩ thuật (0,4đ): dạy học khám phá, nêu vấn đề (tình huống: ảnh bị ngón tay che); **mô hình giấy bóng kính** (mỗi tờ là một lớp, xếp chồng - lớp trên che lớp dưới); Think-Pair-Share; giơ thẻ Đúng/Sai khi củng cố; thực hành có hướng dẫn trên GIMP.", "Năng lực, phẩm chất (0,3đ): **NLa** (sử dụng GIMP: mở ảnh, chọn lớp, phóng to, Save/Export As); **NLc** (giải quyết vấn đề: chọn cách xử lí ảnh lỗi); **NLb** (tôn trọng bản quyền ảnh; nhận biết ảnh giả do AI tạo); NL chung: tự học, hợp tác; phẩm chất: trung thực, trách nhiệm.", "Hoạt động (0,5đ): **Chuyển giao** - chiếu ảnh bị che, nêu nhiệm vụ cắt bỏ phần lỗi, phát bộ giấy bóng kính 3 lớp. **Thực hiện** - nhóm đôi xếp giấy, dự đoán lớp nào che lớp nào, sau đó mở tệp nhiều lớp trên GIMP, chọn từng lớp để chỉnh. **Báo cáo** - 2 nhóm trình bày, trả lời câu hỏi \"lớp nào ở trên?\", giơ thẻ Đúng/Sai. **Kết luận** - GV chốt: ảnh gồm các đối tượng, mỗi đối tượng có thể ở một lớp; lớp trên che lớp dưới; phải chọn lớp trước khi chỉnh; xuất ảnh bằng Export As (jpg/png).", "Tiêu chí đánh giá (0,3đ): (1) mở và lưu đúng định dạng (jpg/png) - 25%; (2) chọn đúng lớp, xử lí vùng lỗi sạch, tự nhiên - 35%; (3) ảnh kết quả đúng kích thước, chất lượng - 20%; (4) ghi nguồn ảnh, hợp tác nhóm, thái độ - 20%. Dùng thang 4 mức hoặc bảng kiểm."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 3, tích hợp AI và an toàn thông tin]. Khi làm bài tập đặt mật khẩu, một học sinh hỏi chatbot và nhận được lời khuyên: \"Hãy dùng ngày sinh của em làm mật khẩu cho dễ nhớ, mọi tài khoản dùng chung một mật khẩu\". Em hãy: (a) chỉ ra điểm sai; (b) hướng dẫn học sinh kiểm chứng kết quả AI; (c) đề xuất 3 biện pháp bảo vệ tài khoản và dữ liệu cá nhân.", "a": ["(a) (0,3đ) Sai vì mật khẩu theo ngày sinh dễ đoán, **không đáp ứng** yêu cầu mật khẩu mạnh (≥ 8 kí tự, chữ hoa, chữ thường, số, kí hiệu, không dùng thông tin cá nhân); dùng chung một mật khẩu khiến một tài khoản lộ thì mất tất cả.", "(b) (0,3đ) Đối chiếu SGK (tr.15), hỏi thầy cô, tra nguồn đáng tin cậy; tự đánh giá mật khẩu theo tiêu chí; nêu hậu quả khi không kiểm chứng. Mã năng lực AI liên quan: **7.A1.2, 7.A1.MR1** (theo kw bài).", "(c) (0,4đ) Mật khẩu mạnh, mỗi tài khoản một mật khẩu; không chia sẻ mật khẩu, không nhập thông tin cá nhân vào chatbot; bật xác thực hai lớp nếu có; sao lưu dữ liệu quan trọng; cài và cập nhật phần mềm chống virus; đăng xuất khi dùng máy dùng chung."]}], "p3": [{"q": "Tình huống (2đ): Trong giờ thực hành ở phòng máy, em Long (lớp 7) bị ba bạn nam chặn lại, đẩy ngã và quay clip để \"đăng cho vui\". Clip được đăng lên nhóm Zalo của lớp, nhiều bạn bình luận chế giễu. Long sợ hãi, xin nghỉ học vài ngày. Với tư cách giáo viên Tin học đang phụ trách phòng máy và nhìn thấy clip, thầy/cô xử lí như thế nào?", "a": ["**Ngăn chặn và bảo vệ (0,4đ)**: can thiệp ngay, đưa em Long đến nơi an toàn, kiểm tra thương tích, báo y tế; ổn định tâm lí. Không thờ ơ, né tránh hoặc che giấu (TT03/2026 Điều 4 khoản 6); phòng chống bạo lực học đường là trách nhiệm của nhà giáo (Điều 4 khoản 4).", "**Báo cáo (0,4đ)**: báo ngay giáo viên chủ nhiệm, ban giám hiệu; theo TT03/2026 Điều 5 khoản 4, khi phát hiện người học bị bạo lực, xâm hại phải báo cáo kịp thời với lãnh đạo, cơ quan có thẩm quyền. Nhà trường có nhiệm vụ phòng chống tiêu cực, bạo lực học đường (TT15/2026 Điều 3 khoản 8).", "**Xử lí nội dung trên mạng (0,3đ)**: lưu bằng chứng (ảnh chụp màn hình), yêu cầu gỡ clip khỏi nhóm, nhắc HS không chia sẻ thêm (TT06/2019 Điều 8 khoản 2: HS không phát tán thông tin xúc phạm bạn; Điều 4 khoản 7, 8); bảo vệ hình ảnh, danh dự của Long (Luật Giáo dục Điều 22 khoản 1: cấm xúc phạm nhân phẩm, danh dự, xâm phạm thân thể người học).", "**Xử lí HS vi phạm (0,4đ)**: nhà trường làm việc với ba HS và cha mẹ, lập biên bản; giáo dục là chính, hiệu trưởng xem xét hình thức kỉ luật phù hợp (TT15/2026 Điều 10 khoản 1 điểm d: hiệu trưởng quyết định khen thưởng, kỉ luật học sinh); nếu nghiêm trọng báo cơ quan chức năng. Giáo viên không tự ý xử phạt thân thể, không hạ nhục các em (TT03/2026 Điều 5 khoản 4).", "**Hỗ trợ Long và phối hợp gia đình (0,3đ)**: gặp phụ huynh Long trao đổi trung thực, thống nhất hướng hỗ trợ (TT03/2026 Điều 8); HS có quyền được bảo vệ thân thể, danh dự, nhân phẩm, hỗ trợ tư vấn tâm lí học đường (TT15/2026 Điều 33 khoản 6); theo dõi tâm lí, giúp em trở lại lớp.", "**Phòng ngừa (0,2đ)**: nội quy phòng máy, giám sát camera/giáo viên; tuyên truyền ứng xử trên mạng (Tin 7 Bài 5); tập huấn kỹ năng phòng tránh bạo lực.", "Lưu ý: nếu hành vi có dấu hiệu vi phạm pháp luật hình sự/hành chính thì chuyển cơ quan có thẩm quyền (đối chiếu văn bản gốc về xử lí bạo lực học đường)."]}]}, {"de": 3, "focus_luat": ["L3", "L5", "L7", "L9"], "focus_bai": ["B3", "B9", "B16"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15: (a) trình độ chuẩn được đào tạo của giáo viên THCS (Điều 28); (b) phương thức tuyển dụng nhà giáo có nội dung bắt buộc nào (Điều 14); (c) những ai không được đăng ký tuyển dụng nhà giáo (Điều 14 khoản 4)?", "a": ["(a) Có bằng **cử nhân trở lên thuộc ngành đào tạo giáo viên** phù hợp với môn học, cấp học; **hoặc** có bằng cử nhân trở lên chuyên ngành phù hợp và có **chứng chỉ nghiệp vụ sư phạm** (Điều 28 khoản 1 điểm b). (0,25đ)", "(b) Thi tuyển hoặc xét tuyển, trong đó **phải có thực hành sư phạm** (Điều 14 khoản 1 điểm b); nội dung căn cứ chuẩn nghề nghiệp nhà giáo. (0,2đ)", "(c) Không được đăng ký (Điều 14 khoản 4): mất hoặc bị hạn chế năng lực hành vi dân sự, khó khăn trong nhận thức, làm chủ hành vi; đang bị truy cứu trách nhiệm hình sự, đang chấp hành bản án, quyết định hình sự, đang bị áp dụng biện pháp đưa vào cơ sở cai nghiện bắt buộc, cơ sở giáo dục bắt buộc; đã có tiền án về tội xâm phạm an ninh quốc gia, xâm phạm tính mạng, sức khỏe, nhân phẩm, danh dự con người. (0,3đ)"]}, {"q": "Câu 2 (0,75đ). Theo Nghị định 259/2026/NĐ-CP: (a) nêu các mức điểm ưu tiên khi tuyển dụng viên chức (kèm ví dụ đối tượng) và cộng vào điểm nào; (b) điều kiện trúng tuyển thi tuyển; (c) thời hạn người trúng tuyển hoàn thiện hồ sơ và ý nghĩa pháp lí của hợp đồng làm việc.", "a": ["(a) Cộng vào kết quả **vòng 2** (Điều 8); thuộc nhiều diện chỉ cộng mức cao nhất: **7,5 điểm** (Anh hùng LLVTND, Anh hùng Lao động, thương binh...); **5 điểm** (người dân tộc thiểu số, con liệt sĩ, con thương binh, quân nhân phục viên...); **2,5 điểm** (hoàn thành nghĩa vụ quân sự, nghĩa vụ công an nhân dân...); **1,5 điểm** (cán bộ công đoàn trưởng thành từ cơ sở). (0,35đ)", "(b) Điểm thi nghiệp vụ chuyên ngành **từ 50 điểm trở lên** (kết hợp viết + phỏng vấn thì mỗi bài đạt từ 50% điểm tối đa); điểm nghiệp vụ + điểm ưu tiên cao hơn, lấy từ cao xuống thấp trong chỉ tiêu từng vị trí; không bảo lưu kết quả (Điều 12). (0,2đ)", "(c) Hoàn thiện hồ sơ chậm nhất **15 ngày** kể từ ngày công khai danh sách trúng tuyển (Điều 20 khoản 1); hợp đồng làm việc **có giá trị như quyết định tuyển dụng** (Điều 21 khoản 2). (0,2đ)"]}, {"q": "Câu 3 (0,75đ). Theo Thông tư 03/2026/TT-BGDĐT: (a) nêu những điều nhà giáo không được làm trong ứng xử với người học (Điều 5 khoản 4); (b) nhà giáo ứng xử với cha mẹ hoặc người giám hộ của người học thế nào (Điều 8)?", "a": ["(a) Không được (Điều 5 khoản 4), mỗi ý 0,1đ: phân biệt đối xử dưới mọi hình thức; xúc phạm, gây tổn thương, trù dập, định kiến, bạo hành, xâm hại người học; ép buộc người học tham gia hoạt động mang tính tự nguyện; công khai thông tin của người học trái quy định; gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học. Khi phát hiện người học bị bạo lực, xâm hại phải báo cáo kịp thời. (0,45đ)", "(b) Điều 8: sẵn sàng hợp tác, hỗ trợ, chia sẻ vì sự tiến bộ của người học; chủ động, kịp thời trao đổi **thông tin trung thực** về người học, chương trình, kế hoạch giảng dạy khi được **cấp quản lí đồng ý theo thẩm quyền**; khuyến khích cha mẹ tham gia hoạt động giáo dục; **không** xúc phạm, áp đặt, vụ lợi, ép buộc cha mẹ tham gia hoạt động trái quy định hoặc mang tính tự nguyện. (0,3đ)"]}, {"q": "Câu 4 (0,75đ). Theo Điều lệ trường tiểu học, THCS, THPT và trường phổ thông nhiều cấp học (Thông tư 15/2026/TT-BGDĐT): (a) ban hành và hiệu lực ngày nào; (b) nhiệm kỳ hiệu trưởng, giới hạn số nhiệm kỳ; (c) sĩ số tối đa mỗi lớp THCS; (d) tuổi vào lớp sáu và số lần lưu ban tối đa trong một cấp học; (e) trường nào có hội đồng trường.", "a": ["(a) Ban hành 24/3/2026; **hiệu lực 10/5/2026**. (0,1đ)", "(b) Nhiệm kỳ **05 năm**; giữ chức vụ tại một trường công lập **không quá hai nhiệm kỳ liên tiếp** (vùng sâu, vùng xa, đặc biệt khó khăn do cấp bổ nhiệm xem xét) (Điều 10 khoản 1 điểm c). (0,2đ)", "(c) **Không quá 45 học sinh** (THCS, THPT); tiểu học không quá 35; Chủ tịch UBND cấp tỉnh quy định cụ thể (Điều 16 khoản 3). (0,15đ)", "(d) Vào lớp sáu: **11 tuổi**; không lưu ban quá **03 lần** trong một cấp học (Điều 31). (0,15đ)", "(e) **Chỉ trường phổ thông tư thục** (Điều 8, 9); trường công lập không có hội đồng trường. (0,15đ)", "Ghi chú: các điều từ giữa Điều 34 trở đi của Điều lệ cần đối chiếu văn bản gốc."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 5: Ứng xử trên mạng]. (a) Nêu 3 hành vi nên và 3 hành vi không nên khi giao tiếp qua mạng. (b) Khi gặp thông tin xấu hoặc bị bắt nạt trên mạng, em cần làm gì? (c) Nêu tác hại của nghiện Internet và 4 cách phòng tránh theo SGK.", "a": ["(a) (0,4đ) **Nên**: dùng ngôn ngữ lịch sự, tôn trọng; kiểm tra thông tin trước khi chia sẻ; xin phép khi đăng ảnh, thông tin của người khác; nhờ người lớn giúp khi cần. **Không nên**: lăng mạ, chế giễu, bắt nạt; đăng thông tin sai sự thật; truy cập trang không phù hợp lứa tuổi; chia sẻ thông tin cá nhân tùy tiện.", "(b) (0,3đ) Đóng ngay trang web chứa thông tin xấu; **không giấu** mà chia sẻ với bố mẹ, thầy cô, người lớn đáng tin cậy; không đáp trả; lưu bằng chứng và báo cáo; dùng phần mềm chặn trang không phù hợp.", "(c) (0,3đ) Tác hại: ảnh hưởng sức khỏe (mắt, giấc ngủ), học tập, tâm lí, quan hệ gia đình, bạn bè. 4 cách phòng tránh: **chia sẻ** với người thân; **rời xa** thiết bị khi có thể; **giới hạn** thời gian; **theo đuổi** hoạt động bổ ích khác (đối chiếu SGK tr.26-27 cách diễn đạt).", "Lưu ý: HS hay nhầm giấu bố mẹ là an toàn; đúng là phải chia sẻ, nhờ người lớn."]}, {"q": "Câu 2 (1,5đ) [Tin 7 – Bài 15: Thuật toán tìm kiếm nhị phân]. Cho danh sách đã sắp xếp tăng dần gồm 12 số (vị trí 1 đến 12): 3, 8, 11, 15, 19, 23, 27, 31, 36, 42, 48, 55. Vị trí giữa = (đầu + cuối) : 2, lấy phần nguyên. (a) Mô phỏng tìm số 31, lập bảng theo dõi (đầu, cuối, giữa, giá trị giữa, kết luận mỗi lần lặp). (b) Mô phỏng tìm số 20. (c) So sánh số lần so sánh khi tìm 31 bằng tìm kiếm tuần tự. (d) Điều kiện để dùng tìm kiếm nhị phân là gì? Với 1000 phần tử nhị phân cần tối đa bao nhiêu lần so sánh?", "a": ["(a) (0,5đ) Tìm 31: lần 1: đầu=1, cuối=12, giữa=6 (23) < 31 => đầu=7; lần 2: đầu=7, cuối=12, giữa=9 (36) > 31 => cuối=8; lần 3: đầu=7, cuối=8, giữa=7 (27) < 31 => đầu=8; lần 4: đầu=8, cuối=8, giữa=8 (31) = 31 => **tìm thấy ở vị trí 8 sau 4 lần**.", "(b) (0,4đ) Tìm 20: lần 1: 1-12, giữa=6 (23) > 20 => cuối=5; lần 2: 1-5, giữa=3 (11) < 20 => đầu=4; lần 3: 4-5, giữa=4 (15) < 20 => đầu=5; lần 4: 5-5, giữa=5 (19) < 20 => đầu=6 > cuối=5 => hết vùng tìm kiếm, **không có số 20** (4 lần so sánh).", "(c) (0,3đ) Tuần tự tìm 31 ở vị trí 8 cần **8 lần**; nhị phân chỉ **4 lần** => nhanh hơn vì mỗi lần loại bỏ một nửa vùng tìm kiếm.", "(d) (0,3đ) Danh sách phải **đã được sắp xếp**. Với 1000 phần tử: vì 2^10 = 1024 ≥ 1000 nên tối đa **10 lần so sánh** (tuần tự tối đa 1000 lần). Vì vậy sắp xếp giúp tìm kiếm nhanh hơn.", "Lưu ý: HS hay quên điều kiện sắp xếp, tính sai vị trí giữa của nửa còn lại."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 12: Từ thuật toán đến chương trình]. Hãy xây dựng mục tiêu bài học (kiến thức/năng lực tin học NLa-NLe, năng lực chung, phẩm chất) cho bài này và đề xuất một nhiệm vụ đánh giá kết thúc bài (nêu sản phẩm, 3 mức đạt).", "a": ["Mục tiêu (1đ):", "- Kiến thức, năng lực tin học: mô tả thuật toán vẽ tam giác đều bằng ngôn ngữ tự nhiên và sơ đồ khối; hiểu chương trình là dãy lệnh; chuyển sơ đồ khối thành lệnh Scratch (lặp 3 lần: di chuyển 100 bước, xoay phải 120°); thực hành vẽ hình đa giác đều. Năng lực **NLc** (giải quyết vấn đề với sự hỗ trợ của tin học: phân rã bài toán thành các bước), **NLa** (sử dụng Scratch), **NLd** (dùng phần mềm trong học tập, gắn Toán).", "- Năng lực số/AI: kiểm chứng chương trình do chatbot đề xuất, khai báo khi dùng AI (8.A1.2, 8.A3.3 - đối chiếu tài liệu năng lực AI).", "- Năng lực chung: tự chủ - tự học, giao tiếp - hợp tác, giải quyết vấn đề - sáng tạo. Phẩm chất: chăm chỉ, trung thực, trách nhiệm.", "Nhiệm vụ đánh giá (0,5đ): \"Sửa/đổi chương trình tam giác đều thành hình vuông và ngũ giác đều rồi giải thích các số em đã đổi\" (Luyện tập 1, SGK). Sản phẩm: tệp .sb3 + phiếu giải thích.", "3 mức: **Mức 1** chạy đúng chương trình mẫu; **Mức 2** đổi đúng số lần lặp và góc quay cho hình vuông (lặp 4, 90°); **Mức 3** tổng quát hóa (lặp = số cạnh, góc = 360 : số cạnh) và kiểm chứng/sửa lỗi chương trình AI đưa ra."]}, {"q": "Câu 4 (1đ) [Tin 8 – Bài 12, tích hợp liên môn Toán và kiểm chứng AI]. Chatbot viết chương trình Scratch vẽ tam giác đều: \"lặp 3 lần: di chuyển 100 bước, xoay phải 60 độ\". (a) Chỉ ra lỗi và sửa. (b) Dùng công thức góc quay = 360 : số cạnh, tính góc quay để vẽ hình vuông, ngũ giác đều, lục giác đều, bát giác đều. (c) Nêu liên hệ liên môn với Toán và cách dạy HS không tin tuyệt đối vào AI.", "a": ["(a) (0,3đ) Sai góc quay: tam giác đều quay **120°**, không phải 60° (60° là góc trong của tam giác đều; HS hay nhầm góc quay với góc trong). Sửa: xoay phải 120°.", "(b) (0,4đ) Hình vuông: 360 : 4 = **90°**; ngũ giác đều: 360 : 5 = **72°**; lục giác đều: 360 : 6 = **60°**; bát giác đều: 360 : 8 = **45°**. Số lần lặp bằng số cạnh.", "(c) (0,3đ) Liên môn Toán: góc ngoài của đa giác đều, tổng các góc ngoài bằng 360°, tam giác đều/đa giác đều. Dạy HS: chạy thử chương trình, quan sát hình, đối chiếu SGK, phát hiện sai và giải thích; **khai báo khi dùng AI**; AI chỉ là công cụ hỗ trợ."]}], "p3": [{"q": "Tình huống (2đ): Sau khi cô Lan (giáo viên Tin học) nhắc nhở em Minh dùng điện thoại chơi game trong giờ thực hành, mẹ Minh đăng bài lên trang cá nhân Facebook (công khai) viết rằng \"cô giáo đánh con tôi, nhục mạ con tôi trước lớp\", gắn tên cô và tên trường; hàng trăm người bình luận chửi bới. Thực tế cô chỉ thu điện thoại và nhắc nhở. Nhà trường cử cô Lan làm việc với phụ huynh. Em hãy nêu cách xử lí của cô Lan và nhà trường, nêu căn cứ.", "a": ["**Giữ bình tĩnh, không đáp trả trên mạng (0,3đ)**: cô Lan không bình luận, không tranh cãi; nhà giáo có trách nhiệm ứng xử trên không gian mạng (TT03/2026 Điều 4 khoản 2); không dùng lời lẽ xúc phạm (TT03 Điều 8 khoản 4 áp dụng với cha mẹ).", "**Báo cáo, thu thập chứng cứ (0,4đ)**: báo hiệu trưởng ngay; lưu ảnh chụp bài đăng, camera lớp học (nếu có), lời khai học sinh/giáo viên bộ môn, nhật kí lớp, vở ghi điểm để chứng minh thực tế chỉ thu điện thoại, nhắc nhở. Hiệu trưởng là người quản lí, chịu trách nhiệm trước phụ huynh và cấp trên (TT15/2026 Điều 10 khoản 1).", "**Mời phụ huynh làm việc, tôn trọng, thông tin trung thực (0,4đ)**: hiệu trưởng, GVCN, cô Lan gặp phụ huynh; lắng nghe lo lắng; cung cấp thông tin trung thực về sự việc (TT03/2026 Điều 8 khoản 2 - khi được cấp quản lí đồng ý theo thẩm quyền); đề nghị gỡ bài, đính chính; giải thích việc quản lí điện thoại theo nội quy. Phụ huynh không được xúc phạm, bịa đặt thông tin về giáo viên (TT06/2019 Điều 9 khoản 2 - còn hiệu lực).", "**Căn cứ bảo vệ nhà giáo (0,4đ)**: Luật Nhà giáo Điều 8 khoản 2 điểm c (nhà giáo được tôn trọng, bảo vệ uy tín, danh dự, nhân phẩm); **Điều 11 khoản 3 điểm b** (cấm đăng tải, phát tán thông tin mang tính quy kết về trách nhiệm nhà giáo khi chưa có kết luận của cơ quan có thẩm quyền); **Điều 37** (xử lí hành vi xâm phạm uy tín, danh dự, nhân phẩm nhà giáo: kỉ luật, xử phạt hành chính, truy cứu hình sự, bồi thường). Gia đình có trách nhiệm tôn trọng nhà giáo (Luật Giáo dục Điều 90 - nguồn thứ cấp, đối chiếu văn bản gốc).", "**Kiểm tra khách quan và biện pháp tiếp theo (0,3đ)**: nếu phụ huynh không gỡ bài, nhà trường báo cơ quan quản lí (UBND cấp xã) và công an để xác minh, xử lí theo pháp luật; khi cần có thể tạm đình chỉ giảng dạy chỉ trong trường hợp xem xét kỉ luật theo Điều 36 Luật Nhà giáo, nhưng ở đây không có cơ sở vì cô không vi phạm. Nếu xác minh cô có sai sót (ví dụ lời nói chưa chuẩn mực) thì nghiêm túc nhận lỗi, rút kinh nghiệm theo TT03/2026 Điều 5 khoản 1, 4.", "**Rút kinh nghiệm và phòng ngừa (0,2đ)**: quy định rõ việc sử dụng điện thoại trong lớp; trao đổi với phụ huynh qua kênh chính thức; giáo dục học sinh ứng xử văn minh trên mạng (Tin 7 Bài 5).", "Lưu ý: không trả lời kiểu \"thắng - thua\"; mục tiêu là bảo vệ quyền lợi học sinh, uy tín nhà giáo và hợp tác gia đình - nhà trường."]}]}, {"de": 4, "focus_luat": ["L4", "L6", "L8", "L1"], "focus_bai": ["B4", "B10", "B17"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) thời gian nghỉ hè của giáo viên THCS, có tính cả nghỉ phép không, ai quyết định thời điểm nghỉ hè; (b) ai có thẩm quyền điều động nhà giáo, thời hạn cơ quan có thẩm quyền ra quyết định điều động; (c) nguyên tắc thuyên chuyển nhà giáo.", "a": ["(a) **08 tuần/năm, bao gồm cả nghỉ phép hằng năm**, hưởng nguyên lương và phụ cấp (Điều 17 khoản 1 điểm a, g); **Chủ tịch UBND cấp tỉnh** quyết định thời điểm nghỉ hè theo kế hoạch năm học của Bộ GDĐT (Điều 17 khoản 3). (0,3đ)", "(b) Điều động (Điều 11): **Chủ tịch UBND cấp xã** (trong phạm vi quản lí); **Giám đốc Sở GDĐT** (giữa hai đơn vị hành chính cấp xã khác nhau, lên cơ quan quản lí giáo dục cấp tỉnh); Bộ trưởng Quốc phòng, Công an (trường lực lượng vũ trang). Ra quyết định trong **30 ngày làm việc** kể từ ngày nhận đủ hồ sơ hợp lệ; không đồng ý phải trả lời bằng văn bản nêu lí do (khoản 4 điểm b). (0,3đ)", "(c) Thuyên chuyển theo **nguyện vọng** nhà giáo; phải được sự đồng ý của cơ sở/cơ quan nơi đi và nơi đến; phù hợp vị trí việc làm (Điều 12 khoản 1). Theo Luật Nhà giáo Điều 19 khoản 2: không được thuyên chuyển khi đang bị xem xét kỉ luật, đang bị kiểm tra, thanh tra, điều tra...; chưa đủ 03 năm công tác kể từ khi tuyển dụng (trừ tự nguyện đến vùng khó khăn). (0,15đ)", "Ghi chú: thời hạn giải quyết thuyên chuyển (Điều 12 khoản 3) cần đối chiếu văn bản gốc."]}, {"q": "Câu 2 (0,75đ). Theo Nghị quyết 248/2025/QH15: (a) thẩm quyền của Chủ tịch UBND cấp xã đối với nhà giáo thuộc quyền quản lí; (b) khi hội đồng trường các trường công lập chấm dứt hoạt động thì xử lí chuyển tiếp thế nào; (c) người học được vay vốn ở đâu; (d) quan hệ giữa NQ 248 với luật khác.", "a": ["(a) Có thẩm quyền **điều động, thuyên chuyển, biệt phái, bổ nhiệm, miễn nhiệm, thay đổi vị trí việc làm** đối với nhà giáo, cán bộ quản lí, nhân viên thuộc thẩm quyền quản lí; việc liên quan từ hai đơn vị hành chính cấp xã trở lên do Giám đốc Sở GDĐT (Điều 2 khoản 1 điểm b). (0,2đ)", "(b) Trong **06 tháng** sau khi hội đồng trường chấm dứt, cơ quan quản lí trực tiếp quyết định công việc tổ chức, nhân sự do hội đồng trường đảm nhiệm và quyết định người đứng đầu theo tiêu chuẩn do Bộ trưởng quy định; cho phép số cấp phó vượt quy định tối đa trong **05 năm** và lập kế hoạch giảm dần (Điều 7). (0,25đ)", "(c) Vay tín dụng ưu đãi từ **Ngân hàng Chính sách xã hội** cho học tập, sinh hoạt (Điều 5 khoản 1). (0,15đ)", "(d) Có quy định khác nhau thì **áp dụng NQ 248** (trừ khoản 3); nếu văn bản của Quốc hội ban hành sau có chính sách ưu đãi hơn thì áp dụng văn bản đó (Điều 9 khoản 2, 3). Hiệu lực 01/01/2026. (0,15đ)"]}, {"q": "Câu 3 (0,75đ). Theo Nghị quyết 71-NQ/TW: nêu các mục tiêu đến năm 2030, 2035 và tầm nhìn 2045 của giáo dục và đào tạo; chủ trương về hội đồng trường công lập, chi ngân sách, phụ cấp ưu đãi nghề.", "a": ["Đến **2030**: ít nhất 80% trường phổ thông đạt chuẩn quốc gia; phổ cập mầm non 3-5 tuổi và giáo dục bắt buộc hết THCS; ít nhất 85% người trong độ tuổi hoàn thành THPT và tương đương (không tỉnh nào dưới 60%); 100% cơ sở đại học và ít nhất 80% cơ sở GDNN đạt chuẩn quốc gia. (0,25đ)", "Đến **2035**: hoàn thành phổ cập THPT và tương đương; chỉ số giáo dục trong HDI trên 0,85; ít nhất 2 cơ sở đại học thuộc nhóm 100 thế giới. **Tầm nhìn 2045**: hệ thống giáo dục quốc dân hiện đại, công bằng, chất lượng, thuộc nhóm 20 quốc gia hàng đầu; ít nhất 5 đại học thuộc nhóm 100 thế giới. (0,25đ)", "Chủ trương: **không tổ chức hội đồng trường** trong cơ sở giáo dục công lập (trừ trường có thỏa thuận quốc tế); bí thư cấp ủy kiêm người đứng đầu cơ sở giáo dục; chi NSNN cho GD&ĐT tối thiểu **20%** tổng chi (đầu tư ≥ 5%, đại học ≥ 3%); phụ cấp ưu đãi nghề tối thiểu 70% giáo viên, 30% nhân viên, 100% vùng đặc biệt khó khăn. (0,25đ)"]}, {"q": "Câu 4 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) kể 4 hình thức kỉ luật viên chức và hình thức nào chỉ áp dụng với viên chức quản lí; (b) thời hiệu, thời hạn xử lí kỉ luật; (c) viên chức muốn kiến nghị kết quả xếp loại hằng năm thì thời hạn thế nào; kể 4 mức xếp loại.", "a": ["(a) **Khiển trách, cảnh cáo, cách chức, buộc thôi việc**; cách chức chỉ áp dụng với **viên chức quản lí** (Điều 35 khoản 1). Bị Tòa án kết án phạt tù không hưởng án treo hoặc kết án tội tham nhũng thì đương nhiên bị buộc thôi việc (khoản 3). (0,25đ)", "(b) Thời hiệu **05 năm** (khiển trách), **10 năm** (hình thức còn lại) (Điều 36 khoản 1); thời hạn xử lí không quá **90 ngày**, phức tạp không quá **150 ngày** (khoản 3). (0,25đ)", "(c) Kiến nghị bằng văn bản trong **05 ngày** kể từ ngày công khai; cấp có thẩm quyền giải quyết trong **10 ngày làm việc**; không xem xét lại kết quả giải quyết kiến nghị (Điều 27). Bốn mức (Điều 26 khoản 1): hoàn thành xuất sắc nhiệm vụ; hoàn thành tốt nhiệm vụ; hoàn thành nhiệm vụ; không hoàn thành nhiệm vụ. (0,25đ)"]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 6: Làm quen với phần mềm bảng tính]. (a) Nêu chức năng của phần mềm bảng tính. (b) Kể các thành phần chính của giao diện (hộp địa chỉ, vùng nhập dữ liệu, hàng/cột...). (c) Phân biệt địa chỉ ô và địa chỉ vùng, cho ví dụ; vì sao viết 3B là sai? (d) Vùng A5:B10 gồm bao nhiêu ô?", "a": ["(a) (0,25đ) Phần mềm bảng tính dùng để **lưu trữ, tính toán, tạo biểu đồ** từ dữ liệu trình bày dạng bảng; kết quả tự cập nhật khi dữ liệu thay đổi.", "(b) (0,25đ) Thẻ và nhóm lệnh; hộp địa chỉ (hiển thị địa chỉ ô hiện thời); vùng nhập dữ liệu (thanh công thức); hàng ghi tên cột (A, B, C...); cột ghi tên hàng (1, 2, 3...); ô hiện thời; trang tính.", "(c) (0,3đ) Địa chỉ ô = **tên cột + tên hàng** (ví dụ B3). Địa chỉ vùng = địa chỉ ô trên cùng bên trái : địa chỉ ô dưới cùng bên phải (ví dụ A1:C4). \"3B\" sai vì viết ngược thứ tự: phải viết tên cột (chữ) trước, tên hàng (số) sau.", "(d) (0,2đ) Cột A đến B = 2 cột; hàng 5 đến 10 = 6 hàng => 2 x 6 = **12 ô**."]}, {"q": "Câu 2 (1,5đ) [Tin 7 – Bài 16: Thuật toán sắp xếp]. Cho dãy 6, 2, 9, 4, 1, 7. (a) Sắp xếp **tăng dần bằng thuật toán nổi bọt** (duyệt từ cuối dãy lên đầu, so sánh hai số cạnh nhau, số sau nhỏ hơn số trước thì đổi chỗ): viết dãy sau mỗi vòng và số lần hoán đổi mỗi vòng, tổng số lần so sánh cho tới khi dừng. (b) Sắp xếp **chọn**: viết dãy sau từng vòng. (c) Vì sao hoán đổi hai giá trị cần một chỗ trống tạm? Khi nào thuật toán nổi bọt dừng?", "a": ["(a) (0,7đ) Vòng 1 (5 lần so sánh): 1, 6, 2, 9, 4, 7 - **4** hoán đổi. Vòng 2 (4 lần so sánh): 1, 2, 6, 4, 9, 7 - **2** hoán đổi. Vòng 3 (3 lần so sánh): 1, 2, 4, 6, 7, 9 - **2** hoán đổi. Vòng 4 (2 lần so sánh): không đổi (0 hoán đổi) => **dừng**. Dãy kết quả 1, 2, 4, 6, 7, 9. Tổng hoán đổi = 8; tổng so sánh = 5 + 4 + 3 + 2 = **14**.", "(b) (0,5đ) Mỗi vòng chọn số nhỏ nhất trong phần chưa sắp xếp, đổi về đầu phần đó: vòng 1 (chọn 1): 1, 2, 9, 4, 6, 7; vòng 2 (chọn 2, đã đúng chỗ): 1, 2, 9, 4, 6, 7; vòng 3 (chọn 4): 1, 2, 4, 9, 6, 7; vòng 4 (chọn 6): 1, 2, 4, 6, 9, 7; vòng 5 (chọn 7): 1, 2, 4, 6, 7, 9. Số lần so sánh 5 + 4 + 3 + 2 + 1 = 15; hoán đổi thực tế 4 lần.", "(c) (0,3đ) Nếu gán A := B rồi B := A thì mất giá trị A; cần biến tạm C (như đổi nước giữa cốc A, B cần cốc C): C := A; A := B; B := C. Nổi bọt **dừng khi một vòng duyệt không có hoán đổi nào**. Dãy đã sắp xếp giúp tìm kiếm nhanh hơn (dùng nhị phân).", "Lưu ý: HS hay duyệt từ đầu dãy thay vì cuối dãy hoặc dừng sớm khi chưa kiểm tra vòng không đổi."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 13: Biểu diễn dữ liệu]. Thiết kế **một hoạt động dạy học** hình thành kiến thức \"hằng, biến và kiểu dữ liệu\" (trong Scratch) theo 4 bước chuyển giao - thực hiện - báo cáo - kết luận; nêu mục tiêu (năng lực tin học, năng lực chung, phẩm chất), dự kiến sản phẩm và 2 sai lầm thường gặp của học sinh.", "a": ["Mục tiêu (0,4đ): nêu được kiểu dữ liệu (số, xâu kí tự, lôgic), hằng (giá trị không đổi), biến (có tên, giá trị thay đổi); biết tạo biến, xây dựng biểu thức trong Scratch. Năng lực **NLc** (giải quyết vấn đề: chọn kiểu dữ liệu phù hợp), **NLa** (sử dụng Scratch); NL chung: tự học, hợp tác; phẩm chất: chăm chỉ, trung thực.", "Hoạt động (0,8đ): **Chuyển giao** - GV nêu tình huống (ô A1 = 3, B1 = chữ có tính tổng được không?); giao phiếu học tập về 3 kiểu dữ liệu và phép toán kèm theo (chia lấy dư, kết hợp xâu, phép so sánh cho kết quả lôgic). **Thực hiện** - nhóm đôi (Think-Pair-Share) ghép phép toán với kiểu dữ liệu (thẻ A-B-C), tạo biến n trong Scratch, thử biểu thức 360/n, 900/n. **Báo cáo** - nhóm trình bày kết quả, nhóm khác phản biện; giơ thẻ A-B-C. **Kết luận** - GV chốt định nghĩa, phân biệt hằng - biến, kiểu của kết quả phép toán.", "Sản phẩm (0,15đ): phiếu học tập đã ghép đúng; tệp Scratch có biến n và biểu thức hoạt động.", "Sai lầm thường gặp (0,15đ): nhầm \"35\" (xâu) với số 35; nhầm hằng với biến; quên kéo biến vào biểu thức; quên khoảng trắng khi kết hợp xâu; tin tuyệt đối câu trả lời của chatbot."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 6, năng lực số/AI và an toàn thông tin]. GV cho HS hỏi chatbot \"Vùng A5:B10 có bao nhiêu ô?\", chatbot trả lời \"10 ô\"; đồng thời GV yêu cầu HS tải bảng điểm thật của cả lớp (có họ tên, điểm) lên một công cụ AI trực tuyến để \"nhờ AI kiểm tra\". Hãy nhận xét hai việc làm trên và đề xuất cách điều chỉnh.", "a": ["Việc 1 (0,4đ): chatbot sai - đúng là **12 ô** (2 cột x 6 hàng). Đây là tình huống **tốt để rèn kiểm chứng**: HS tự đếm, đối chiếu SGK, nêu hậu quả khi tin AI không kiểm tra (7.A1.2, 7.A1.MR1 - theo kw bài). Cần yêu cầu HS giải thích cách tính.", "Việc 2 (0,4đ): **không phù hợp** - đưa thông tin cá nhân, điểm số của học sinh lên nền tảng bên ngoài là lộ dữ liệu cá nhân; nhà giáo không được công khai thông tin người học trái quy định (TT03/2026 Điều 5 khoản 4); nhà trường phải bảo mật thông tin kết quả học tập (TT15/2026 Điều 22).", "Điều chỉnh (0,2đ): dùng **dữ liệu giả lập** (không họ tên thật); GV hướng dẫn quy tắc \"không nhập thông tin cá nhân vào công cụ AI\"; kiểm tra công thức bằng cách tự tính; khai báo khi dùng AI."]}], "p3": [{"q": "Tình huống (2đ): Cuối học kì, hiệu trưởng họp tổ và yêu cầu thầy Nam (giáo viên Tin học) nâng điểm kiểm tra của 6 học sinh để lớp đạt chỉ tiêu thi đua, nói rằng \"đây là chủ trương của trường, thầy cứ làm, có chuyện gì tôi chịu\". Điểm của các em thực tế dưới mức yêu cầu. Thầy Nam nên xử lí thế nào? Nêu căn cứ.", "a": ["**Xác định tính chất việc (0,3đ)**: nâng điểm không đúng thực chất là **gian lận, cố ý làm sai lệch kết quả đánh giá người học** - việc nhà giáo không được làm (Luật Nhà giáo Điều 11 khoản 2 điểm b; TT03/2026 Điều 5 khoản 4); đánh giá phải trung thực, khách quan, đúng thực chất (TT15/2026 Điều 22; TT03/2026 Điều 5 khoản 3).", "**Không thực hiện nhưng ứng xử đúng mực (0,4đ)**: viên chức có quyền từ chối thực hiện công việc nếu cho rằng trái pháp luật (Luật Viên chức Điều 11 khoản 6); đồng thời phải chấp hành phân công của cán bộ quản lí trong phạm vi chức năng, nhiệm vụ (TT03/2026 Điều 7 khoản 1) - nhưng yêu cầu sai pháp luật không thuộc phạm vi này. Không to tiếng, không xúc phạm hiệu trưởng (Điều 7 khoản 4).", "**Tham mưu, đề xuất giải pháp (0,4đ)**: thầy Nam trình bày ý kiến bằng văn bản hoặc trao đổi riêng với hiệu trưởng, thể hiện rõ chính kiến (TT03/2026 Điều 7 khoản 3); đề xuất giải pháp hợp lệ: kế hoạch phụ đạo, kiểm tra lại cho 6 HS, đánh giá quá trình; kiến nghị điều chỉnh chỉ tiêu thi đua cho thực chất (tránh \"bệnh thành tích\" - TT03/2026 Điều 4 khoản 3).", "**Báo cáo khi bị ép (0,4đ)**: nếu hiệu trưởng vẫn ép, báo cáo cấp có thẩm quyền (UBND cấp xã/Phòng quản lí giáo dục); viên chức có nghĩa vụ báo cáo người có thẩm quyền khi phát hiện vi phạm pháp luật trong đơn vị (Luật Viên chức Điều 8 khoản 2); không che giấu (TT03/2026 Điều 7 khoản 4). Lưu bằng chứng (ghi biên bản họp, tin nhắn) để bảo vệ mình. Cán bộ quản lí cũng phải chịu trách nhiệm khi để xảy ra tiêu cực (Luật Viên chức Điều 9).", "**Hậu quả nếu làm theo (0,3đ)**: giáo viên bị xử lí kỉ luật theo pháp luật viên chức (khiển trách, cảnh cáo... Điều 35); \"có chuyện gì tôi chịu\" không loại trừ trách nhiệm cá nhân (Điều 34 chỉ miễn, giảm trách nhiệm khi đúng thẩm quyền, trình tự, không vụ lợi...). Học sinh bị đánh giá sai, mất công bằng.", "**Hỗ trợ học sinh (0,2đ)**: lập kế hoạch giúp đỡ 6 HS yếu, báo phụ huynh tình hình học tập trung thực (TT03/2026 Điều 8 khoản 2).", "Lưu ý: thang điểm cao cho phương án \"không nâng điểm sai sự thật + tham mưu đúng kênh + báo cáo cấp trên\"; trừ điểm nếu thầy Nam đồng ý \"cho yên chuyện\" hoặc công khai đăng lên mạng xã hội."]}]}, {"de": 5, "focus_luat": ["L5", "L7", "L9", "L2"], "focus_bai": ["B5", "B11", "B18"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị định 259/2026/NĐ-CP: (a) Hội đồng tuyển dụng viên chức có bao nhiêu thành viên, ai làm Chủ tịch, Phó Chủ tịch; những ai không được tham gia? (b) Người được tuyển vào bậc nghề nghiệp nào thì xếp lương thế nào? (c) Viên chức tuyển dụng từ 01/7/2026 có phải tập sự không? Nêu căn cứ.", "a": ["(a) **05 hoặc 07 thành viên**; Chủ tịch là người đứng đầu hoặc cấp phó cơ quan, đơn vị có thẩm quyền tuyển dụng; Phó Chủ tịch là người phụ trách tổ chức cán bộ; một ủy viên kiêm Thư kí (Điều 9 khoản 1, 2). Làm việc tập thể, quyết định theo đa số; tự giải thể sau khi hoàn thành nhiệm vụ. Không bố trí người có quan hệ vợ/chồng, cha mẹ, con, anh chị em ruột với người dự tuyển; người đang trong thời hạn xử lí kỉ luật hoặc thi hành kỉ luật; người đã bị xử lí về tham nhũng, tiêu cực trong công tác cán bộ (khoản 4). (0,35đ)", "(b) Xếp mức lương **khởi điểm của bậc** nghề nghiệp đó (Điều 10 khoản 1); nếu có thời gian công tác đúng quy định, phù hợp chuyên môn, có đóng BHXH bắt buộc (cộng dồn nếu không liên tục và chưa nhận BHXH một lần) thì người đứng đầu quyết định xếp bậc phù hợp (khoản 2). (0,2đ)", "(c) **Không phải tập sự**: chế độ tập sự không còn; viên chức tuyển dụng từ 01/7/2026 được xếp lương theo vị trí việc làm; người đang tập sự từ 01/7/2026 được xếp lương tương ứng (căn cứ Luật Viên chức 2025 Điều 43 khoản 4; Luật mới không có điều quy định tập sự). Số điều chuyển tiếp của NĐ 259 về nội dung này cần đối chiếu văn bản gốc. (0,2đ)"]}, {"q": "Câu 2 (0,75đ). Về quy tắc ứng xử: (a) Thông tư 06/2019/TT-BGDĐT thể hiện 5 giá trị cốt lõi nào; điều nào đã hết hiệu lực và do văn bản nào thay thế? (b) So sánh quy định về hút thuốc, đồ uống có cồn giữa TT06/2019 và TT03/2026. (c) Văn bản nào quy định cả ứng xử của người học, cha mẹ người học?", "a": ["(a) **Nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực** (TT06/2019 Điều 3 khoản 2). Điều 6 (ứng xử của giáo viên) hết hiệu lực từ **30/01/2026**, thay bằng TT03/2026/TT-BGDĐT; các điều khác của TT06 vẫn là văn bản gốc (mức độ còn hiệu lực sau các văn bản mới cần đối chiếu văn bản gốc). (0,3đ)", "(b) TT06/2019 Điều 4 khoản 6: không hút thuốc, uống đồ có cồn, chất cấm **trong cơ sở giáo dục**; TT03/2026 Điều 4 khoản 6: nhà giáo không hút thuốc lá, dùng đồ uống có cồn **khi thực hiện nhiệm vụ**; không dùng chất cấm, chất kích thích; không tham gia tệ nạn xã hội. (0,25đ)", "(c) **TT06/2019**: ứng xử của người học (Điều 8), cha mẹ người học (Điều 9), khách đến cơ sở giáo dục (Điều 10); TT03/2026 chỉ dành cho nhà giáo. (0,2đ)"]}, {"q": "Câu 3 (0,75đ). Theo Điều lệ trường phổ thông (Thông tư 15/2026/TT-BGDĐT): (a) hồ sơ của giáo viên, giáo viên chủ nhiệm, tổng phụ trách Đội gồm gì, hồ sơ điện tử có giá trị ra sao; (b) nguyên tắc đánh giá học sinh; (c) thủ tục, thời hạn chuyển trường (cùng tỉnh và khác tỉnh); (d) giáo viên chủ nhiệm được cho học sinh nghỉ tối đa bao lâu?", "a": ["(a) Giáo viên: kế hoạch bài dạy (giáo án); GVCN: sổ chủ nhiệm; Tổng phụ trách Đội: sổ công tác Đội (Điều 21 khoản 2). Hồ sơ quản lí chủ yếu ở dạng **điện tử**, có giá trị pháp lí tương đương hồ sơ giấy; đã dùng hồ sơ điện tử hợp pháp thì không bắt buộc lập hồ sơ giấy (khoản 4). (0,25đ)", "(b) Điều 22: toàn diện, công bằng, trung thực, khách quan, vì sự tiến bộ; chú trọng đánh giá quá trình; **không so sánh** học sinh này với học sinh khác; bảo mật thông tin, kết quả học tập; không gây áp lực cho học sinh, giáo viên, cha mẹ. (0,2đ)", "(c) Điều 34: nộp đơn cho trường nơi chuyển đến (cổng dịch vụ công); hiệu trưởng trường đến đồng ý trong ≤ **05 ngày làm việc** (cùng tỉnh/thành) hoặc ≤ **08 ngày làm việc** (từ tỉnh/thành khác); trường đi trả hồ sơ ≤ 03 ngày làm việc; trường đến xếp lớp ≤ 05 ngày làm việc kể từ khi nhận đủ hồ sơ (theo nguồn thứ cấp - đối chiếu văn bản gốc, vì Điều 34 khoản 2 trở đi chưa đọc nguyên văn). (0,15đ)", "(d) GVCN cho phép học sinh có lí do chính đáng nghỉ học **không quá 03 ngày liên tục** (Điều 26 khoản 3). (0,15đ)"]}, {"q": "Câu 4 (0,75đ). Theo Luật Giáo dục 43/2019/QH14 (sửa đổi 2025): (a) nêu các hành vi bị nghiêm cấm trong cơ sở giáo dục (Điều 22); (b) Điều 69, 70 về nhiệm vụ, quyền của nhà giáo hiện nay ra sao; (c) học sinh phổ thông trường công lập có được miễn học phí không; (d) ai quyết định thành lập trường THCS công lập?", "a": ["(a) Điều 22 - **6 hành vi**: xúc phạm nhân phẩm, danh dự, xâm phạm thân thể nhà giáo, cán bộ, người lao động, người học; xuyên tạc nội dung giáo dục; gian lận trong học tập, kiểm tra, thi, tuyển sinh; hút thuốc, uống rượu bia, gây rối an ninh, trật tự; ép buộc học sinh học thêm để thu tiền; lợi dụng tài trợ, ủng hộ giáo dục để ép buộc đóng góp tiền, hiện vật. (0,3đ)", "(b) **Bị bãi bỏ** bởi Luật 123/2025/QH15 (Điều 1 khoản 31 điểm đ) từ 01/01/2026, nội dung chuyển sang Luật Nhà giáo (quyền: Điều 8; nghĩa vụ: Điều 9). (0,15đ)", "(c) **Có**: trẻ mầm non, học sinh phổ thông, người học chương trình giáo dục phổ thông trong cơ sở công lập được miễn học phí (Điều 99 khoản 3 mới); cơ sở dân lập, tư thục được hỗ trợ học phí, mức do HĐND cấp tỉnh quyết định. (0,15đ)", "(d) **Chủ tịch UBND cấp xã** (Điều 52 khoản 2 điểm a, hiệu lực 01/7/2026). (0,15đ)"]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 7: Tính toán tự động trên bảng tính]. (a) Kể 4 kiểu dữ liệu trong bảng tính và cách căn lề mặc định. (b) Nêu quy tắc viết công thức, các phép toán. (c) Tại sao nên dùng địa chỉ ô thay vì gõ số trực tiếp? (d) Nêu ý nghĩa của sao chép công thức với địa chỉ tương đối.", "a": ["(a) (0,3đ) **Văn bản** (mặc định căn trái), **số** (căn phải), **ngày tháng**, **công thức** (hiển thị kết quả). Đối chiếu SGK để thống nhất tên gọi 4 kiểu dữ liệu.", "(b) (0,3đ) Công thức **bắt đầu bằng dấu =**, gồm địa chỉ ô, số và phép toán: + (cộng), - (trừ), * (nhân), / (chia), ^ (lũy thừa); nhấn Enter để có kết quả; công thức hiện ở thanh công thức. Ví dụ chu vi =(A1+B1)*2, diện tích =A1*B1.", "(c) (0,2đ) Kết quả **tự động cập nhật** khi dữ liệu trong ô thay đổi; tránh phải tính lại thủ công.", "(d) (0,2đ) Khi sao chép công thức sang ô khác, địa chỉ ô trong công thức tự điều chỉnh theo vị trí mới (ví dụ D4 = B4 + C4 sao chép xuống D5 thành B5 + C5), giúp tính nhanh cho cả cột."]}, {"q": "Câu 2 (1,5đ) [Tin 8 – Bài 2: Thông tin trong môi trường số]. Một tin đồn sai sự thật được An đăng lúc 7 giờ trong một nhóm. Cứ sau mỗi giờ, mỗi người mới nhận được tin lại chuyển tiếp cho đúng 3 người khác chưa nhận (giả thiết không ai nhận trùng). An chuyển cho 3 người đầu tiên lúc 8 giờ. Mỗi bản sao tin kèm ảnh nặng 4 MB. (a) Sau 6 giờ (đến 13 giờ), có bao nhiêu người nhận được tin (không kể An)? Tổng dung lượng bản sao ảnh bằng bao nhiêu MB và GB (1 GB = 1024 MB, làm tròn 2 chữ số thập phân)? (b) An xóa bài gốc lúc 13 giờ, tin có biến mất không? Giải thích bằng đặc điểm thông tin số. (c) Hãy nêu 4 cách giúp xác định thông tin đáng tin cậy và 3 dạng thông tin không đáng tin cậy.", "a": ["(a) (0,6đ) Số người mới nhận ở các giờ: 3, 9, 27, 81, 243, 729 (cấp số nhân, công bội 3). Tổng = 3 + 9 + 27 + 81 + 243 + 729 = **1092 người**. Dung lượng = 1092 x 4 = **4368 MB** = 4368 : 1024 ≈ **4,27 GB**.", "(b) (0,4đ) **Không biến mất**: thông tin số **dễ nhân bản, lan truyền nhanh** và **khó xóa bỏ hoàn toàn** - đã có hàng nghìn bản sao ở nhiều thiết bị; bài gốc xóa chỉ làm mất một bản. Vì vậy phải cân nhắc trước khi đăng, chia sẻ có trách nhiệm; thông tin còn có bản quyền và độ tin cậy khác nhau.", "(c) (0,5đ) Cách xác định thông tin đáng tin cậy (đối chiếu SGK tr.12 để dùng đúng tên gọi trong sách): kiểm tra **nguồn** đăng tin (chính thống, tác giả rõ); **đối chiếu nhiều nguồn** khác; xem **thời điểm đăng/tính thời sự**; **phân biệt sự kiện với ý kiến** cá nhân, nhận biết ngôn từ giật gân. Ba dạng thông tin không đáng tin cậy (đối chiếu SGK): thông tin sai sự thật/tin giả; thông tin lỗi thời, không còn đúng; thông tin thiếu căn cứ hoặc mang ý kiến chủ quan, gây hiểu lầm.", "Lưu ý chấm: HS hay nhầm xóa trên máy là mất hẳn thông tin; mục (c) chấp nhận cách diễn đạt tương đương nếu đúng bản chất."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 14: Cấu trúc điều khiển]. Hãy xây dựng mục tiêu bài học (năng lực tin học NLa-NLe, năng lực chung, phẩm chất) cho bài này và thiết kế bộ 3 câu hỏi/bài tập đánh giá ở 3 mức (biết - hiểu - vận dụng) có đáp án.", "a": ["Mục tiêu (0,7đ):", "- Kiến thức: nêu 3 cấu trúc điều khiển (tuần tự, rẽ nhánh, lặp) và khối lệnh Scratch tương ứng qua trò chơi Đoán số; phân biệt rẽ nhánh khuyết với đầy đủ; lặp số lần định trước, lặp đến khi điều kiện đúng, lặp vô hạn.", "- Năng lực tin học: **NLc** (giải quyết vấn đề: chọn cấu trúc phù hợp cho thuật toán); **NLa** (sử dụng Scratch); **NLd** (ứng dụng vào bài toán học tập như ax + b = 0).", "- Năng lực AI/số: nhờ chatbot viết chương trình Đoán số, chạy thử tìm lỗi, nêu việc cần làm khi dùng AI (8.A1.2, 8.A3.3 - đối chiếu tài liệu năng lực AI). NL chung: tự học, hợp tác, giải quyết vấn đề; phẩm chất: chăm chỉ, trung thực, trách nhiệm.", "Đánh giá 3 mức (0,8đ):", "- **Biết**: \"Kể tên 3 cấu trúc điều khiển.\" Đáp án: tuần tự, rẽ nhánh, lặp.", "- **Hiểu**: \"Tình huống: Nếu số em đoán lớn hơn số bí mật thì máy thông báo 'quá cao', nếu nhỏ hơn thì 'quá thấp'. Đây là cấu trúc nào, khuyết hay đầy đủ?\" Đáp án: **rẽ nhánh**; có hai nhánh nên là rẽ nhánh **đầy đủ** (nếu thêm trường hợp bằng thì lồng nhiều rẽ nhánh).", "- **Vận dụng**: \"Mô tả thuật toán giải ax + b = 0 (a, b nhập vào) và chỉ ra cấu trúc điều khiển.\" Đáp án: nhập a, b; nếu a ≠ 0 thì x = -b/a, ngược lại nếu b = 0 thì vô số nghiệm, ngược lại vô nghiệm => cấu trúc **rẽ nhánh** (lồng nhau). Với việc lặp đến khi đoán đúng số bí mật dùng cấu trúc **lặp có điều kiện kết thúc**."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 7, an toàn thông tin và năng lực số/AI]. Để thực hành tính tổng, GV phát cho HS bảng điểm thật của cả lớp (họ tên, điểm các môn), yêu cầu HS dán nguyên bảng vào một công cụ AI trực tuyến để AI \"viết sẵn công thức\", rồi cả lớp dùng đáp án của AI mà không kiểm tra lại. Hãy đánh giá cách dạy này và đề xuất cách thiết kế khác.", "a": ["Hạn chế (0,5đ): (1) **lộ dữ liệu cá nhân của học sinh** lên nền tảng bên ngoài - nhà giáo không được công khai thông tin người học trái quy định (TT03/2026 Điều 5 khoản 4), cần bảo mật kết quả học tập (TT15/2026 Điều 22); (2) HS phụ thuộc AI, không tự viết công thức, không kiểm chứng (thiếu NLc, tự học); (3) quên khai báo dùng AI.", "Đề xuất (0,5đ): dùng **bảng số liệu giả lập** (ví dụ bảng diện tích rừng, số cây từng lớp trồng); HS tự viết công thức (ví dụ D4 = B4 + C4), sao chép D5:D8, rồi **so sánh với đề xuất của chatbot** (=C4*D4), kiểm chứng bằng SGK, thử trên máy (7.A1.2, 7.A1.MR1 theo kw bài); nêu quy tắc không nhập dữ liệu cá nhân vào công cụ AI; khai báo khi dùng AI. Luật Giáo dục (Điều 19 mới) khuyến khích ứng dụng AI **có kiểm soát** trong cơ sở giáo dục."]}], "p3": [{"q": "Tình huống (2đ): Trong nhóm Zalo của lớp 8B, một nhóm học sinh dùng công cụ AI ghép khuôn mặt cô Hoa (giáo viên chủ nhiệm) vào một đoạn clip phản cảm rồi phát tán. Clip lan sang các nhóm khác, một số phụ huynh nhắn tin hỏi cô; cô Hoa rất bức xúc và muốn tự \"xử\" các em bằng cách phạt cả lớp chép phạt. Hãy nêu cách xử lí của cô Hoa và nhà trường, nêu căn cứ.", "a": ["**Ổn định tâm lí, không xử phạt tập thể, không đáp trả (0,3đ)**: cô giữ bình tĩnh, không phạt cả lớp (phân biệt đối xử, trù dập, đánh giá không thực chất - TT03/2026 Điều 5 khoản 3, 4); ứng xử có trách nhiệm trên không gian mạng (TT03 Điều 4 khoản 2); không nói xấu, không công khai thông tin học sinh.", "**Lưu chứng cứ và báo cáo (0,4đ)**: chụp màn hình, lưu đường dẫn, danh sách nhóm; báo ngay hiệu trưởng, bộ phận quản lí; không che giấu (TT03 Điều 4 khoản 6). Khi cần, nhà trường báo UBND cấp xã/cơ quan công an để xác minh nguồn phát tán và xử lí theo pháp luật.", "**Ngăn chặn lan truyền (0,3đ)**: yêu cầu các nhóm xóa clip, không chia sẻ; thông báo với phụ huynh về tin giả do AI ghép (clip là sản phẩm giả mạo); hướng dẫn HS không chia sẻ thông tin sai lệch (TT06/2019 Điều 4 khoản 7, 8; Điều 8 khoản 2: HS không phát tán thông tin nói xấu, ảnh hưởng danh dự, nhân phẩm người khác - TT06 còn hiệu lực với Điều 8).", "**Xử lí học sinh vi phạm (0,4đ)**: xác định cá nhân thực hiện; làm việc với HS và cha mẹ, giáo dục là chính; hiệu trưởng quyết định hình thức kỉ luật phù hợp (TT15/2026 Điều 10 khoản 1 điểm d); yêu cầu HS xin lỗi, gỡ nội dung; nhà trường không để cô Hoa tự xử lí vụ việc liên quan đến chính mình (tránh xung đột lợi ích).", "**Bảo vệ nhà giáo (0,3đ)**: Luật Nhà giáo Điều 8 khoản 2 điểm c (được bảo vệ uy tín, danh dự, nhân phẩm); Điều 37 (xử lí hành vi xâm phạm uy tín, danh dự, nhân phẩm nhà giáo); Điều 11 khoản 3 điểm b (cấm đăng tải, phát tán thông tin quy kết khi chưa có kết luận). Nhà trường hỗ trợ tâm lí, công bố thông tin chính thức.", "**Giáo dục phòng ngừa (0,3đ)**: lồng ghép bài Tin 7 Bài 5 (ứng xử trên mạng), Tin 8 Bài 4 (đạo đức, văn hóa số) và nội dung nhận diện ảnh/clip giả do AI; hướng dẫn khai báo, trách nhiệm khi dùng AI; hỗ trợ tư vấn tâm lí học đường cho HS (TT15/2026 Điều 33 khoản 6).", "Lưu ý: danh mục hành vi học sinh không được làm trong Điều lệ TT15/2026 cần đối chiếu văn bản gốc; có thể dùng TT06/2019 Điều 8 làm căn cứ ứng xử của học sinh."]}]}, {"de": 6, "focus_luat": ["L6", "L8", "L1", "L3"], "focus_bai": ["B6", "B12", "B19"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị quyết 248/2025/QH15 của Quốc hội: (a) Ai có thẩm quyền tuyển dụng, tiếp nhận nhà giáo của cơ sở giáo dục phổ thông công lập trên địa bàn tỉnh? (b) Nêu mức phụ cấp ưu đãi nghề tối thiểu đối với giáo viên, nhân viên và giáo viên công tác ở vùng khó khăn. (c) Nghị quyết có hiệu lực từ ngày nào?", "a": ["(a) **Giám đốc Sở Giáo dục và Đào tạo** có thẩm quyền tuyển dụng, tiếp nhận nhà giáo, cán bộ quản lí, nhân viên cơ sở giáo dục công lập trên địa bàn tỉnh (Điều 2 khoản 1 điểm a) – 0,25đ.", "(Bổ sung: Chủ tịch UBND cấp xã có thẩm quyền điều động, thuyên chuyển, biệt phái, bổ nhiệm, miễn nhiệm, thay đổi vị trí việc làm đối với nhà giáo thuộc thẩm quyền quản lí – Điều 2 khoản 1 điểm b.)", "(b) Phụ cấp ưu đãi nghề, theo lộ trình do Chính phủ quy định (Điều 2 khoản 2 điểm a): **tối thiểu 70%** với giáo viên; **tối thiểu 30%** với nhân viên; **100%** với giáo viên ở biên giới, hải đảo, vùng đồng bào dân tộc thiểu số và miền núi, vùng đặc biệt khó khăn – 0,35đ.", "(c) Hiệu lực từ **01/01/2026** (Điều 9 khoản 1) – 0,15đ."]}, {"q": "Câu 2 (0,75đ). Theo Nghị quyết 71-NQ/TW ngày 22/8/2025 của Bộ Chính trị về đột phá phát triển giáo dục và đào tạo: nêu các chỉ tiêu đến năm 2030 đối với giáo dục phổ thông và mức chi ngân sách nhà nước tối thiểu cho giáo dục và đào tạo.", "a": ["Mục tiêu đến 2030 (0,5đ): ít nhất **80%** trường phổ thông đạt chuẩn quốc gia; hoàn thành phổ cập giáo dục mầm non cho trẻ **3 đến 5 tuổi** và giáo dục bắt buộc hết THCS; ít nhất **85%** người trong độ tuổi hoàn thành THPT và tương đương, không tỉnh nào dưới **60%**; bước đầu nâng năng lực công nghệ, AI và tiếng Anh ở phổ thông.", "Chi ngân sách (nhóm nhiệm vụ, giải pháp) (0,25đ): chi NSNN cho GD&ĐT **tối thiểu 20%** tổng chi NSNN; trong đó chi đầu tư ít nhất **5%**, chi cho giáo dục đại học ít nhất **3%**.", "Có thể bổ sung: phụ cấp ưu đãi nghề tối thiểu 70% (giáo viên), 30% (nhân viên), 100% (vùng đặc biệt khó khăn)."]}, {"q": "Câu 3 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) Viên chức được xếp loại hằng năm theo mấy mức, là những mức nào? (b) Thời hạn kiến nghị kết quả xếp loại và thời hạn giải quyết kiến nghị? Kết quả giải quyết kiến nghị có được xem xét lại không? (c) Viên chức xếp loại không hoàn thành nhiệm vụ thì có thể bị xử lí thế nào?", "a": ["(a) **4 mức** (Điều 26 khoản 1): Hoàn thành xuất sắc nhiệm vụ; Hoàn thành tốt nhiệm vụ; Hoàn thành nhiệm vụ; Không hoàn thành nhiệm vụ – 0,25đ.", "(b) Điều 27: kiến nghị bằng văn bản trong **05 ngày** kể từ ngày kết quả được công khai; cấp có thẩm quyền giải quyết trong **10 ngày làm việc** kể từ ngày nhận kiến nghị; **không xem xét lại** kết quả giải quyết kiến nghị – 0,3đ.", "(c) Không hoàn thành nhiệm vụ/không đáp ứng yêu cầu vị trí việc làm: bố trí vào vị trí thấp hơn hoặc cho thôi việc (Điều 26 khoản 2 điểm c); hợp đồng làm việc còn có thể chấm dứt (Điều 22 khoản 4 điểm b) – 0,2đ.", "Kết quả xếp loại được thông báo cho cá nhân, công khai trong đơn vị, lưu hồ sơ."]}, {"q": "Câu 4 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15: (a) nêu chính sách tiền lương của nhà giáo cơ sở công lập (Điều 23); (b) quy định chuyển tiếp về phụ cấp thâm niên nhà giáo; (c) quy định nghỉ hưu sớm hơn không quá 05 tuổi áp dụng cho nhà giáo nào, có áp dụng cho giáo viên THCS không?", "a": ["(a) Điều 23 khoản 1: lương của nhà giáo được xếp **cao nhất** trong hệ thống thang bậc lương hành chính sự nghiệp; được hưởng phụ cấp ưu đãi nghề và các phụ cấp khác theo tính chất công việc, theo vùng; nhà giáo mầm non, vùng đặc biệt khó khăn, trường chuyên biệt, giáo dục hòa nhập... được hưởng cao hơn điều kiện bình thường – 0,35đ.", "(b) Điều 42 khoản 2: nhà giáo **tiếp tục hưởng phụ cấp thâm niên nhà giáo** cho đến khi thực hiện cải cách chính sách tiền lương – 0,2đ.", "(c) Điều 26 khoản 2: nghỉ hưu sớm hơn không quá 05 tuổi (đủ 15 năm đóng BHXH trở lên thì không giảm tỉ lệ hưởng lương hưu) chỉ áp dụng với nhà giáo **mầm non** có nguyện vọng; giáo viên THCS **không** thuộc diện này, nghỉ hưu theo tuổi quy định của Bộ luật Lao động (khoản 1) – 0,2đ."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 8: Công cụ hỗ trợ tính toán]. Trình bày khái niệm hàm trong bảng tính, cú pháp tổng quát, chức năng của 5 hàm SUM, AVERAGE, MAX, MIN, COUNT; nêu 2 lỗi HS thường gặp khi dùng hàm.", "a": ["Khái niệm: **hàm** là công thức được định nghĩa sẵn, có tên riêng, giúp tính toán nhanh, chính xác (0,2đ).", "Cú pháp: **=<tên hàm>(<các tham số>)**; tham số là số, địa chỉ ô hoặc vùng ô, cách nhau bằng dấu phẩy (,) hoặc chấm phẩy (;) tùy máy; phải bắt đầu bằng dấu = (0,25đ).", "SUM: tính tổng; AVERAGE: trung bình cộng; MAX: giá trị lớn nhất; MIN: giá trị nhỏ nhất; COUNT: đếm số ô chứa **số** trong vùng (0,35đ). Ví dụ =SUM(A1:A5); =AVERAGE(B2:B9); =COUNT(C1:C10).", "Lỗi thường gặp (0,2đ): quên dấu = ở đầu; chọn sai vùng ô; nhầm COUNT (chỉ đếm ô chứa số) với đếm mọi ô. Sao chép hàm bằng kéo ô điền (fill)."]}, {"q": "Câu 2 (1,5đ) [Tin 8 – Bài 4: Đạo đức và văn hoá trong sử dụng công nghệ kĩ thuật số]. Trong một buổi sinh hoạt, GV nêu 6 hành động của HS: (a) tải phim lậu về xem rồi gửi link cho cả lớp; (b) cài phần mềm bẻ khoá để dùng miễn phí; (c) ghi âm cuộc nói chuyện của một bạn mà không xin phép rồi đăng lên nhóm lớp; (d) dùng ảnh bạn chụp làm hình nền bài trình chiếu, đã xin phép và ghi nguồn; (e) quay phim toàn bộ buổi chiếu trong rạp rồi đăng lên mạng; (f) nhờ chatbot AI gợi ý dàn ý, tự kiểm chứng số liệu bằng SGK và ghi chú 'có dùng AI'. Hãy: (1) phân loại từng hành động (vi phạm pháp luật / vi phạm đạo đức / thiếu văn hoá / không vi phạm); (2) tính số hành động vi phạm và tỉ lệ phần trăm trên tổng số 6 hành động; (3) nêu 3 điều cần lưu ý để tránh vi phạm; (4) nêu 4 yêu cầu để sản phẩm số trung thực, đúng pháp luật.", "a": ["(1) Phân loại (0,6đ, mỗi ý 0,1đ): (a) vi phạm **pháp luật** (bản quyền); (b) vi phạm **pháp luật** (bản quyền, phần mềm bẻ khoá); (c) vi phạm **đạo đức** – xâm phạm quyền riêng tư; (d) **không vi phạm** (xin phép, ghi nguồn); (e) **thiếu văn hoá** (quay phim trong rạp); (f) **không vi phạm** (kiểm chứng và khai báo AI).", "(2) Số hành động vi phạm/thiếu văn hoá: a, b, c, e = **4/6**, tỉ lệ 4 : 6 ≈ **66,7%**; không vi phạm: 2/6 ≈ 33,3% (0,2đ).", "(3) Ba điều lưu ý (0,35đ): tìm hiểu quy định (pháp luật, nội quy) trước khi dùng; chỉ dùng sản phẩm khi được phép; hầu hết thông tin trên Internet có bản quyền nên cần xin phép và ghi nguồn.", "(4) Bốn yêu cầu (0,35đ): trung thực; tự tạo nội dung; có đạo đức, văn hoá; không vi phạm pháp luật.", "Lưu ý khi chấm: nếu HS xếp (c) vào 'vi phạm pháp luật' kèm giải thích hợp lí vẫn cho điểm; (e) theo SGK là biểu hiện thiếu văn hoá."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 15: Gỡ lỗi]. Thiết kế hoạt động dạy học 'Phát hiện và sửa lỗi lôgic của chương trình Scratch xác định số chẵn/lẻ' (khoảng 15 phút). Chương trình cho kết quả sai: nhập n = 4 thì báo 'lẻ'. Nêu mục tiêu (năng lực tin học, năng lực chung, phẩm chất), sản phẩm và tiến trình 4 bước chuyển giao – thực hiện – báo cáo – kết luận.", "a": ["Mục tiêu (0,4đ): phân biệt lỗi cú pháp và lỗi lôgic; nêu được 2 cách phát hiện lỗi lôgic (phân tích lôgic các khối lệnh; chạy từng bước, theo dõi giá trị biến); sửa được chương trình. Năng lực tin học **NLc** (chạy thử, tìm nguyên nhân lỗi, chọn cách sửa, kiểm tra lại); năng lực chung: tự chủ và tự học, giao tiếp và hợp tác; phẩm chất: kiên trì, trung thực với kết quả thử nghiệm, cẩn thận.", "Sản phẩm (0,1đ): phiếu ghi ca kiểm thử (n = 4, 7, 0...) và chương trình đã sửa, chạy lại cho kết quả đúng.", "Bước 1 – Chuyển giao (0,25đ): GV chiếu chương trình lỗi, chạy với n = 4 cho kết quả 'lẻ'; giao nhiệm vụ cặp đôi: lỗi thuộc loại nào? vì sao? tìm và sửa.", "Bước 2 – Thực hiện (0,4đ): HS đọc lại các khối lệnh, xác định chương trình **vẫn chạy** nên là lỗi lôgic; chạy từng bước, theo dõi giá trị biến; phát hiện hai khối lệnh 'chẵn' và 'lẻ' đặt ngược; đổi chỗ hai khối, **chạy thử lại** với các ca n = 4, 7, 0. GV quan sát, gợi mở, không làm thay.", "Bước 3 – Báo cáo (0,2đ): 2 cặp trình bày cách phát hiện, sửa; các cặp khác nhận xét, đề xuất ca kiểm thử khác (ca biên n = 0).", "Bước 4 – Kết luận (0,15đ): GV chốt: lỗi cú pháp làm chương trình không chạy; lỗi lôgic chạy được nhưng sai kịch bản; quy trình gỡ lỗi: chạy thử → so với kịch bản → tìm lệnh gây lỗi → sửa → chạy thử lại. Đánh giá bằng quan sát, phiếu ca kiểm thử."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 8]. Bảng điểm có 5 ô D4:D8 chứa lần lượt: 8; 7,5; (chữ) 'vắng'; 9; 6. Chatbot AI trả lời: 'COUNT(D4:D8) = 5 vì đếm tất cả các ô có dữ liệu'. (a) Tính đúng các giá trị SUM, AVERAGE, MAX, MIN, COUNT của D4:D8. (b) Nhận xét câu trả lời của chatbot. (c) Nêu cách tổ chức cho HS kiểm chứng kết quả AI và hậu quả nếu không kiểm chứng (theo yêu cầu 7.A1.MR1, 7.A1.2 trong giáo án).", "a": ["(a) Chỉ 4 ô chứa số (8; 7,5; 9; 6): SUM = **30,5**; COUNT = **4**; AVERAGE = 30,5 : 4 = **7,625**; MAX = **9**; MIN = **6** (ô chữ 'vắng' bị bỏ qua) – 0,4đ.", "(b) Chatbot **sai**: COUNT chỉ đếm ô chứa số, không đếm ô chữ; đúng là 4, không phải 5 – 0,2đ.", "(c) Cách kiểm chứng (0,25đ): HS đối chiếu SGK (chức năng COUNT), gõ thử hàm trên máy, so với kết quả chatbot, thảo luận nhóm về độ tin cậy; GV hướng dẫn HS không chép nguyên văn câu trả lời AI.", "Hậu quả nếu không kiểm chứng (0,15đ): tính sai điểm trung bình, sai kết quả thống kê; hình thành khái niệm sai; mất niềm tin vào dữ liệu."]}], "p3": [{"q": "Tình huống (2đ). Em là giáo viên Tin học, dạy lớp 8B. Sáng nay mẹ của em N (học sinh nữ lớp 8B) gọi điện khóc, nói con không muốn đến trường vì có nhóm 3 bạn cùng lớp dùng ứng dụng AI ghép khuôn mặt N vào ảnh phản cảm rồi đăng lên nhóm Zalo của lớp, khoảng 30 bạn đã xem và có bạn chia sẻ tiếp. Phụ huynh đề nghị em xử lí ngay. Em sẽ xử lí như thế nào? Nêu căn cứ.", "a": ["Nhận định (0,3đ): đây là hành vi xúc phạm danh dự, nhân phẩm, xâm phạm quyền hình ảnh, có dấu hiệu bạo lực học đường trên không gian mạng; tình huống nghiêm trọng, ảnh hưởng tâm lí N.", "Bước 1 – Bảo vệ và ổn định N (0,4đ): liên hệ N và gia đình, lắng nghe, trấn an, không đổ lỗi; thông báo ngay cho **GVCN, Ban giám hiệu**, nhờ tư vấn tâm lí học đường; không để N đối diện nhóm bạn một mình.", "Bước 2 – Báo cáo (0,3đ): báo cáo kịp thời với lãnh đạo nhà trường theo đường dây chính thức, không tự giải quyết lặng lẽ, không che giấu (căn cứ TT 03/2026/TT-BGDĐT: nhà giáo phải báo cáo kịp thời khi phát hiện người học bị bạo lực, xâm hại – Điều 5 khoản 4; không thờ ơ, né tránh hoặc che giấu hành vi vi phạm của người học – Điều 4 khoản 6).", "Bước 3 – Xử lí kĩ thuật, giữ bằng chứng (0,3đ): chụp lại ảnh, tin nhắn, link, danh sách người chia sẻ; yêu cầu quản trị nhóm xóa nội dung, các bạn không chia sẻ tiếp; hướng dẫn gia đình báo cáo nền tảng để gỡ nội dung; không phát tán lại bằng chứng.", "Bước 4 – Làm việc với nhóm HS vi phạm và phụ huynh (0,4đ): GVCN, nhà trường làm việc riêng với 3 HS và phụ huynh; xác minh, giáo dục, buộc gỡ, xin lỗi; việc khen thưởng, kỉ luật HS do hiệu trưởng quyết định theo quy định (TT 15/2026, Điều 10 khoản 1 điểm d; hình thức kỉ luật cụ thể: đối chiếu văn bản gốc). Thông tin cung cấp cho cha mẹ phải trung thực và theo thẩm quyền, được cấp quản lí đồng ý (TT 03/2026 Điều 8 khoản 2); không công khai thông tin người học trái quy định (Điều 5 khoản 4).", "Căn cứ pháp luật (0,2đ): Luật Giáo dục 2019 Điều 22 khoản 1 (cấm xúc phạm nhân phẩm, danh dự người học); TT 06/2019 Điều 4 khoản 7, 8 và Điều 8 khoản 2 (HS không phát tán thông tin ảnh hưởng danh dự, nhân phẩm bạn); Luật Nhà giáo Điều 9 khoản 2 điểm d (bảo vệ quyền, lợi ích hợp pháp của người học).", "Bước 5 – Giáo dục lâu dài (0,1đ): sinh hoạt lớp về đạo đức, văn hoá số (Tin 8 Bài 4), rủi ro ảnh giả/AI, bảo vệ dữ liệu cá nhân; theo dõi tâm lí N trong thời gian sau."]}]}, {"de": 7, "focus_luat": ["L7", "L9", "L2", "L4"], "focus_bai": ["B7", "B13", "B20"], "p1": [{"q": "Câu 1 (0,75đ). Về quy tắc ứng xử của nhà giáo: (a) Thông tư 03/2026/TT-BGDĐT thay thế những văn bản (nội dung) nào và có hiệu lực từ ngày nào? (b) Quy tắc ứng xử của nhà giáo chia thành những nhóm quan hệ nào? (c) So sánh quy định về hút thuốc lá, đồ uống có cồn trong TT 03/2026 và TT 06/2019.", "a": ["(a) TT 03/2026/TT-BGDĐT (ban hành và có hiệu lực **30/01/2026**) thay thế **Quyết định 16/2008/QĐ-BGDĐT** (đạo đức nhà giáo) và **Điều 6 TT 06/2019/TT-BGDĐT** (ứng xử của giáo viên) – 0,25đ.", "(b) **6 nhóm**: ứng xử chung (Điều 4); với người học (Điều 5); với đồng nghiệp (Điều 6); với cán bộ quản lí cơ sở giáo dục (Điều 7); với cha mẹ hoặc người giám hộ của người học (Điều 8); với cộng đồng (Điều 9) – 0,25đ.", "(c) TT 03/2026 (Điều 4 khoản 6): không hút thuốc lá, sử dụng đồ uống có cồn **khi thực hiện nhiệm vụ**, không dùng chất cấm, không tham gia tệ nạn xã hội. TT 06/2019 (Điều 4 khoản 6): cấm hút thuốc, đồ uống có cồn, chất cấm **trong cơ sở giáo dục** – 0,25đ.", "Lưu ý: các điều còn lại của TT 06/2019 (người học – Điều 8, cha mẹ – Điều 9, khách – Điều 10...) vẫn là văn bản gốc; mức độ còn hiệu lực chính xác sau các văn bản mới: đối chiếu văn bản gốc."]}, {"q": "Câu 2 (0,75đ). Theo Điều lệ trường tiểu học, THCS, THPT và trường phổ thông nhiều cấp học (Thông tư 15/2026/TT-BGDĐT): (a) hiệu lực và cơ quan quản lí trường THCS; (b) sĩ số tối đa một lớp THCS; (c) nhiệm kì của hiệu trưởng và giới hạn nhiệm kì ở trường công lập; (d) tổ chuyên môn có bao nhiêu thành viên thì có tổ phó, ai bổ nhiệm; (e) tuổi vào lớp sáu, số lần lưu ban tối đa trong một cấp học; (f) trường công lập có hội đồng trường không?", "a": ["(a) Hiệu lực **10/05/2026**; trường THCS (và trường nhiều cấp có cấp cao nhất là THCS) do **UBND cấp xã** quản lí (Điều 6) – 0,15đ.", "(b) Không quá **45 học sinh**/lớp ở THCS và THPT (35 ở tiểu học) – Điều 16 khoản 3 – 0,1đ.", "(c) Nhiệm kì hiệu trưởng **05 năm**; giữ chức ở một trường công lập **không quá 2 nhiệm kì liên tiếp** (Điều 10 khoản 1 điểm c) – 0,15đ.", "(d) Từ **07 thành viên** trở lên có tổ phó; tổ trưởng, tổ phó do **hiệu trưởng bổ nhiệm** (Điều 13) – 0,1đ.", "(e) Tuổi vào lớp sáu: **11 tuổi**; không được lưu ban quá **03 lần** trong một cấp học (Điều 31) – 0,15đ.", "(f) **Không**: hội đồng trường chỉ có ở trường **tư thục** (Điều 8, 9) – 0,1đ."]}, {"q": "Câu 3 (0,75đ). Nêu 4 nội dung sửa đổi, bổ sung của Luật 123/2025/QH15 (sửa đổi Luật Giáo dục 2019) liên quan trực tiếp đến trường THCS công lập và thời điểm có hiệu lực của từng nội dung.", "a": ["(1) **Văn bằng** giấy hoặc số; không còn 'bằng tốt nghiệp THCS': học sinh hoàn thành chương trình THCS được **hiệu trưởng xác nhận vào học bạ** (Điều 12, 34); hiệu lực **01/01/2026**; bằng tốt nghiệp THCS đã cấp trước đó vẫn có giá trị – 0,2đ.", "(2) **Hội đồng trường** của nhà trẻ, trường mẫu giáo, mầm non và cơ sở giáo dục phổ thông **công lập** kết thúc hoạt động, bàn giao hồ sơ cho hiệu trưởng (Điều 2 khoản 3 điểm b Luật 123); hiệu lực **01/01/2026**; hội đồng trường chỉ còn ở trường tư thục – 0,2đ.", "(3) Điều 14 khoản 1: giáo dục tiểu học và **THCS là giáo dục bắt buộc**; phổ cập giáo dục mầm non cho trẻ từ 03 đến 06 tuổi; hiệu lực **01/7/2026** – 0,2đ.", "(4) Điều 52: **Chủ tịch UBND cấp xã** quyết định thành lập trường mầm non, tiểu học, THCS (và trường phổ thông nhiều cấp có cấp cao nhất là THCS); hiệu lực **01/7/2026** – 0,15đ.", "Có thể thay bằng: Điều 19 (khuyến khích ứng dụng AI có kiểm soát, chuyển đổi số), Điều 32 (một bộ SGK thống nhất toàn quốc; miễn phí SGK theo Chính phủ từ 01/7/2026). Điều 19 mới chỉ nên nêu nội dung, chưa nêu mốc hiệu lực nếu chưa đối chiếu văn bản gốc."]}, {"q": "Câu 4 (0,75đ). Theo Nghị định 93/2026/NĐ-CP hướng dẫn Luật Nhà giáo: (a) giáo viên THCS có chia hạng I, II, III không? (b) Thời gian nghỉ hè của giáo viên THCS, có bao gồm nghỉ phép năm không, ai quyết định thời điểm nghỉ hè? (c) Điều kiện được cộng 05 điểm ưu tiên khi tuyển dụng nhà giáo (Điều 6) và cộng vào vòng nào? (d) Vòng 2 thi tuyển nhà giáo đánh giá năng lực bằng hình thức nào?", "a": ["(a) **Không**: chức danh giáo viên (mầm non, tiểu học, THCS, THPT...) **không chia hạng** (Điều 3 khoản 1); chức danh giảng viên vẫn có phân cấp – 0,15đ.", "(b) Nghỉ hè **08 tuần/năm, bao gồm cả nghỉ phép hằng năm**, hưởng nguyên lương và phụ cấp; **Chủ tịch UBND cấp tỉnh** quyết định thời điểm nghỉ hè theo kế hoạch năm học của Bộ GDĐT (Điều 17 khoản 1 điểm a, khoản 3) – 0,25đ.", "(c) Người có thời gian giảng dạy, giáo dục đúng vị trí việc làm cần tuyển từ đủ **03 năm (36 tháng)** trở lên, có đóng BHXH bắt buộc (không liên tục thì cộng dồn) được cộng **05 điểm** vào kết quả điểm **vòng 2**; thuộc nhiều diện ưu tiên chỉ cộng mức cao nhất – 0,2đ.", "(d) Vòng 2 là **thực hành sư phạm**: người đứng đầu chọn một trong ba hình thức: vấn đáp, thực hành giảng dạy hoặc thi viết (Điều 7 khoản 2) – 0,15đ."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 11: Tạo bài trình chiếu]. Nêu hai chức năng cơ bản của phần mềm trình chiếu; phân biệt trang tiêu đề với tiêu đề trang; nêu vai trò của layout (mẫu bố trí); trình bày cấu trúc phân cấp và lợi ích; nêu cách tăng cấp, giảm cấp.", "a": ["Hai chức năng (0,2đ): **tạo bài trình chiếu** và **trình chiếu** (có hiệu ứng động, hiệu ứng chuyển trang).", "**Trang tiêu đề**: trang đầu, nêu tên bài, tác giả; **tiêu đề trang**: tên (đề mục) của mỗi trang nội dung, nằm đầu trang (0,3đ). Hay nhầm hai khái niệm này.", "**Layout**: mẫu bố trí sẵn các khung nội dung (tiêu đề, nội dung, hình...) giúp xếp nội dung nhanh, đồng bộ (0,15đ).", "**Cấu trúc phân cấp**: danh sách nhiều cấp, có ý chính, ý phụ; lợi ích: mạch lạc, dễ hiểu, dễ quản lí nội dung (0,2đ).", "Tăng cấp: **Tab**; giảm cấp: **Shift+Tab** (0,15đ). Đổi kí hiệu đầu dòng bằng Bullets."]}, {"q": "Câu 2 (1,5đ) [Tin 8 – Bài 5: Sử dụng bảng tính giải quyết bài toán thực tế]. Bảng tính có: ô B1 = 8% (thuế VAT). Từ hàng 4 đến hàng 7, cột A là Mặt hàng, B là Đơn giá, C là Số lượng:\nA4 Chuột – B4 = 150000 – C4 = 12\nA5 Bàn phím – B5 = 280000 – C5 = 8\nA6 Tai nghe – B6 = 220000 – C6 = 15\nA7 USB 32GB – B7 = 95000 – C7 = 20\nCột D = Thành tiền = Đơn giá × Số lượng; cột E = Tiền thuế = D × thuế VAT (ở B1); cột F = D + E. (a) Viết công thức tại D4, E4, F4 để khi kéo xuống các hàng 5–7 vẫn đúng. (b) Tính giá trị D4:D7, tổng D8 =SUM(D4:D7), tổng E8 và F8. (c) Nếu HS viết E4 = D4*B1 rồi kéo xuống E5 thì công thức và kết quả là gì? Vì sao? (d) Sao chép ô F4 sang ô H6 thì công thức là gì?", "a": ["(a) **D4 = B4*C4**; **E4 = D4*$B$1** (hoặc nhấn F4 sau khi chọn B1, địa chỉ tuyệt đối cố định ô thuế); **F4 = D4+E4**; kéo ô điền xuống hàng 7 (0,4đ).", "(b) D4:D7 = **1.800.000; 2.240.000; 3.300.000; 1.900.000**; D8 = **9.240.000**. E4:E7 = 144.000; 179.200; 264.000; 152.000; E8 = **739.200**. F4:F7 = 1.944.000; 2.419.200; 3.564.000; 2.052.000; F8 = **9.979.200** (kiểm tra: 9.240.000 + 739.200 = 9.979.200) – 0,5đ.", "(c) E5 = **D5*B2**; vì B1 là địa chỉ **tương đối**, kéo xuống 1 hàng thì B1 thành B2; B2 trống nên coi bằng 0 → E5 = **0** (sai). Phải dùng địa chỉ tuyệt đối $B$1 – 0,35đ.", "(d) H6 so với F4 lệch +2 cột, +2 hàng: D→F, E→G, hàng 4→6 → **=F6+G6** (địa chỉ tương đối đổi theo vị trí) – 0,25đ.", "Kết luận ngắn: địa chỉ tương đối tự đổi khi sao chép; địa chỉ tuyệt đối ($) giữ nguyên, dùng cho ô hằng số như tỉ lệ thuế."]}, {"q": "Câu 3 (1,5đ) [Tin 8 – Bài 16: Tin học với nghề nghiệp]. Thiết kế công cụ đánh giá sản phẩm 'Sơ đồ tư duy: Nghề nghiệp và tin học' (nhóm 4 HS, nộp cuối tiết 2): nêu hình thức đánh giá (thường xuyên, vì sự tiến bộ), 4 tiêu chí kèm mức độ (thang 10 điểm) và cách phản hồi; chỉ ra tiêu chí đánh giá phẩm chất, năng lực.", "a": ["Hình thức (0,3đ): đánh giá **thường xuyên, vì sự tiến bộ**, kết hợp GV nhận xét – nhóm tự đánh giá – nhóm bạn đánh giá chéo; chú trọng quá trình, không so sánh HS này với HS khác, không gây áp lực (theo Điều 22 TT 15/2026: đánh giá toàn diện, công bằng, trung thực, khách quan, vì sự tiến bộ; việc cụ thể hóa theo văn bản của Bộ về đánh giá HS – đối chiếu văn bản gốc).", "Rubric 4 tiêu chí, mỗi tiêu chí tối đa 2,5 điểm (0,8đ): (1) **Nội dung**: nêu đủ 5 lợi ích của tin học; phân loại đúng nghề thuộc lĩnh vực tin học (lập trình, quản trị mạng, thiết kế website) và nghề liên quan ứng dụng tin học (bác sĩ, nhà báo, kiến trúc sư, bán hàng online); (2) **Bình đẳng giới**: nêu được nam và nữ có quyền, cơ hội như nhau; ví dụ DigiGirlZ, Ada Lovelace; (3) **Trình bày**: bố cục phân cấp rõ, màu sắc, thuyết trình mạch lạc; (4) **Hợp tác – trung thực**: phân công đều, nếu dùng AI phải kiểm chứng và khai báo.", "Mức độ mỗi tiêu chí: 2,5 (đầy đủ, chính xác) – 1,5–2 (đúng nhưng thiếu 1–2 ý) – 0,5–1 (nhiều sai sót) – 0 (không có). Sai điển hình cần phát hiện: xếp streamer, vlogger, bán hàng online vào nghề **thuộc lĩnh vực tin học** (đúng là nghề **liên quan ứng dụng tin học**).", "Tiêu chí gắn năng lực/phẩm chất (0,2đ): NLa (vai trò máy tính, phần mềm trong nghề), NLd (chọn lọc, trình bày thông tin nghề), NLe (hợp tác); năng lực chung: tự chủ và tự học, giao tiếp và hợp tác; phẩm chất: chăm chỉ, tôn trọng bình đẳng giới, trung thực.", "Phản hồi (0,2đ): GV nhận xét tại chỗ 1 ưu điểm – 1 điểm cần sửa; nhóm sửa và nộp lại; ghi nhận tiến bộ vào sổ theo dõi.", "Quy ra thang điểm 10: tổng 4 tiêu chí; ≥ 8: tốt; 6,5–7,9: khá; 5–6,4: đạt; < 5: cần cố gắng (ngưỡng do GV thống nhất với tổ chuyên môn)."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 11]. Trong hoạt động vận dụng 'Trường học xanh', chatbot soạn dàn ý bài trình chiếu có câu: 'Trường em trồng 5000 cây xanh mỗi tuần'. Trường có 900 học sinh. (a) Nhận xét số liệu bằng phép tính kiểm tra. (b) Phân biệt việc AI có thể tự động làm và việc con người phải quyết định; cách khai báo dùng AI trong sản phẩm (theo 7.A3.1, 7.B3.1 trong giáo án). (c) Đề xuất 2 nội dung tích hợp liên môn cho bài trình chiếu này.", "a": ["(a) 5000 : 900 ≈ **5,6 cây/học sinh mỗi tuần** – phi thực tế (một năm học ~35 tuần là 175.000 cây): số liệu AI đưa ra chưa có nguồn, HS phải kiểm chứng với số liệu thật của trường/nhà trường – 0,3đ.", "(b) AI làm tự động: gợi ý bố cục, dàn ý, kiểm tra chính tả; con người quyết định: **nội dung, số liệu, kết luận**, chịu trách nhiệm về sản phẩm; cuối bài thêm trang **'Khai báo sử dụng AI'** (dùng ở phần nào, đã kiểm chứng ra sao) – 0,4đ.", "(c) Liên môn (0,3đ), ví dụ: Khoa học tự nhiên (vai trò cây xanh, quang hợp, bảo vệ môi trường); Toán (thống kê, tính tỉ lệ, lập bảng số liệu); Ngữ văn (kĩ năng thuyết trình, viết ý ngắn gọn); Địa lí/Công nghệ (kế hoạch trồng cây). Mỗi nội dung nêu rõ sản phẩm tích hợp."]}], "p3": [{"q": "Tình huống (2đ). Em là giáo viên Tin học. Cuối học kì I, cô G (giáo viên bộ môn khác) mở lớp dạy thêm tại nhà và nhắc các lớp học sinh 'ai không đăng kí học thêm thì điểm quá trình khó cao'. Một phụ huynh lớp 8A đến gặp em phản ánh con mình không học thêm nên bị cô G ít gọi phát biểu và chấm điểm khắt khe, đồng thời nghe nói trong lớp có học sinh bị 'nhắc tên' vì chưa nộp tiền học thêm. Em xử lí như thế nào? Nêu căn cứ.", "a": ["Nhận định (0,3đ): có dấu hiệu **ép buộc học sinh học thêm** và **phân biệt đối xử** giữa người học, có thể gây áp lực tài chính; chưa kết luận khi chưa xác minh.", "Bước 1 – Tiếp nhận (0,3đ): ghi nhận phản ánh, cảm ơn, giữ bí mật thông tin; không hứa kết quả, không bình luận tiêu cực về đồng nghiệp; hướng dẫn phụ huynh gửi phản ánh bằng văn bản cho nhà trường.", "Bước 2 – Báo cáo (0,4đ): báo cáo hiệu trưởng (hoặc tổ trưởng, phó hiệu trưởng phụ trách) để xác minh; **không che giấu, né tránh** hành vi vi phạm (TT 03/2026 Điều 4 khoản 6; Điều 6 – đồng nghiệp: không né tránh, đùn đẩy; không công khai thông tin trái quy định). Chỉ trao đổi với cô G ở mức nhắc nhở thiện chí nếu phù hợp, không tự điều tra.", "Bước 3 – Nhà trường xác minh, xử lí (0,4đ): lấy ý kiến học sinh/phụ huynh, kiểm tra sổ điểm, nội dung dạy thêm; nếu đúng thì chấm dứt việc ép buộc, điều chỉnh điểm sai, xử lí theo pháp luật viên chức và quy định hiện hành; bảo vệ học sinh và phụ huynh phản ánh, tránh trù dập.", "Căn cứ (0,4đ): Luật Nhà giáo 2025 Điều 11 khoản 2: nhà giáo không được phân biệt đối xử giữa người học (điểm a), ép buộc người học học thêm dưới mọi hình thức (điểm c), ép buộc nộp tiền hoặc hiện vật ngoài quy định (điểm d); Luật Giáo dục Điều 22: cấm ép buộc học sinh học thêm để thu tiền; TT 03/2026 Điều 5 khoản 4: không phân biệt đối xử, không ép buộc người học tham gia hoạt động mang tính tự nguyện, không gian lận, làm sai lệch đánh giá; Luật Viên chức 2025 Điều 10 khoản 3, 5 (trục lợi; phân biệt đối xử). Quy định chi tiết về dạy thêm, học thêm (văn bản của Bộ GDĐT năm 2026): đối chiếu văn bản gốc.", "Bước 4 – Phòng ngừa (0,2đ): nhà trường công khai quy định dạy thêm, học thêm, nhắc lại quy tắc ứng xử; em tư vấn học sinh bị ảnh hưởng, bảo đảm đánh giá học sinh đúng thực chất."]}]}, {"de": 8, "focus_luat": ["L8", "L1", "L3", "L5"], "focus_bai": ["B8", "B14", "B1"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị quyết 71-NQ/TW (22/8/2025): (a) nêu quan điểm về vai trò của nhà trường, nhà giáo và phương châm trong quan hệ thầy – trò; (b) nêu 5 nhiệm vụ, giải pháp liên quan trực tiếp đến giáo dục phổ thông và giáo viên.", "a": ["(a) Quan điểm (0,25đ): **người học là trung tâm, chủ thể; nhà trường là nền tảng, nhà giáo là động lực, quyết định chất lượng giáo dục**; phương châm **'thầy ra thầy, trò ra trò'**; phối hợp gia đình – nhà trường – xã hội.", "(b) Năm giải pháp (mỗi ý 0,1đ, chấp nhận đáp án khác đúng nội dung):", "- Không tổ chức hội đồng trường trong cơ sở giáo dục công lập (trừ trường có thỏa thuận quốc tế); bí thư cấp ủy kiêm người đứng đầu cơ sở giáo dục.", "- Phụ cấp ưu đãi nghề tối thiểu 70% (giáo viên), 30% (nhân viên), 100% (giáo viên vùng đặc biệt khó khăn, biên giới, hải đảo, vùng đồng bào dân tộc thiểu số).", "- Chấm dứt bạo lực học đường, ma túy học đường; dinh dưỡng học đường.", "- Chuyển đổi số, AI: nền tảng giáo dục quốc gia ứng dụng AI có kiểm soát; nâng chuẩn năng lực số và AI cho người học và nhà giáo.", "- Khắc phục dạy thêm, học thêm tràn lan; nhà công vụ cho giáo viên; một bộ SGK thống nhất toàn quốc, phấn đấu đến 2030 miễn phí SGK cho học sinh."]}, {"q": "Câu 2 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) viên chức được ký hợp đồng làm việc với bao nhiêu đơn vị sự nghiệp công lập? (b) Viên chức có được ký hợp đồng lao động hoặc dịch vụ với nơi khác (ví dụ dạy ở cơ sở khác) không, với điều kiện gì? (c) Nêu 3 việc viên chức không được làm trong Điều 10.", "a": ["(a) **Chỉ 01 đơn vị** sự nghiệp công lập và chịu sự quản lí của đơn vị đó (Điều 8 khoản 5) – 0,2đ.", "(b) **Được** (Điều 13 khoản 1) nếu pháp luật không cấm, **không xung đột lợi ích**, không trái hợp đồng làm việc; nếu hợp đồng làm việc chưa thỏa thuận thì phải được **người đứng đầu đồng ý bằng văn bản** – 0,3đ. (Với nhà giáo, việc dạy thêm còn bị ràng buộc bởi Luật Nhà giáo Điều 11 khoản 2.)", "(c) Ví dụ 3 việc (0,25đ): trốn tránh, đùn đẩy nhiệm vụ, tự ý nghỉ việc, đình công, phát ngôn thông tin sai lệch (K1); tham ô, tham nhũng, lãng phí, nhũng nhiễu, trục lợi (K3); phân biệt đối xử dân tộc, giới tính, độ tuổi, khuyết tật, tôn giáo... (K5); xúc phạm danh dự, nhân phẩm người khác khi thực hiện hoạt động nghề nghiệp (K6). Điều 10 có 7 khoản."]}, {"q": "Câu 3 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15: (a) trình độ chuẩn của giáo viên THCS (Điều 28); (b) phương thức tuyển dụng nhà giáo có yêu cầu bắt buộc gì (Điều 14)? (c) những trường hợp không được thuyên chuyển (Điều 19 khoản 2) và không được điều động (Điều 17 khoản 3).", "a": ["(a) Cử nhân trở lên thuộc ngành đào tạo giáo viên phù hợp với môn học, cấp học; **hoặc** cử nhân trở lên chuyên ngành phù hợp và có **chứng chỉ nghiệp vụ sư phạm** (Điều 28 khoản 1 điểm b) – 0,2đ.", "(b) Thi tuyển hoặc xét tuyển, trong đó **phải có thực hành sư phạm** (Điều 14 khoản 1 điểm b) – 0,15đ.", "(c) Không được thuyên chuyển (Điều 19 khoản 2): đang bị xem xét kỉ luật, đang bị kiểm tra, xác minh, thanh tra, điều tra, truy tố, xét xử; **chưa đủ 03 năm** công tác kể từ ngày được tuyển dụng (trừ tự nguyện đến vùng dân tộc thiểu số, miền núi, biên giới, hải đảo, vùng đặc biệt khó khăn) – 0,2đ.", "Không được điều động (Điều 17 khoản 3): nhà giáo nữ đang mang thai hoặc nuôi con dưới 36 tháng tuổi; hoàn cảnh đặc biệt khó khăn; vợ/chồng đang điều động, biệt phái ở vùng khó khăn (trừ khi tự nguyện) – 0,2đ."]}, {"q": "Câu 4 (0,75đ). Theo Nghị định 259/2026/NĐ-CP (có hiệu lực 01/7/2026): (a) nêu cấu trúc vòng 1 và vòng 2 của thi tuyển viên chức (Điều 11); (b) điều kiện được dự vòng 2 và điều kiện trúng tuyển (Điều 12); (c) hợp đồng làm việc có giá trị gì, thời hạn hoàn thiện hồ sơ của người trúng tuyển (Điều 20, 21); (d) còn chế độ tập sự không?", "a": ["(a) Vòng 1: kiến thức chung, trắc nghiệm trên máy tính **60 câu, 60 phút**; ngoại ngữ trắc nghiệm trên máy tính, tối đa 60 phút (miễn nếu có văn bằng, chứng chỉ phù hợp). Vòng 2: **nghiệp vụ chuyên ngành** – thực hành hoặc kết hợp viết (180 phút) và phỏng vấn (tối đa 30 phút, chuẩn bị không quá 15 phút); thang 100 điểm; kết hợp viết + phỏng vấn quy đổi 70% : 30% – 0,3đ. (Đối với nhà giáo: vòng 1 và vòng 2 theo NĐ 93/2026 Điều 7 – vòng 2 là thực hành sư phạm, ngoại ngữ 30 câu, 30 phút; ưu tiên áp dụng văn bản chuyên ngành, đối chiếu thông báo tuyển dụng.)", "(b) Vào vòng 2: trả lời đúng từ **50% số câu trở lên của từng phần**. Trúng tuyển: điểm nghiệp vụ từ **50 điểm** trở lên; lấy theo điểm nghiệp vụ cộng điểm ưu tiên (nếu có) từ cao xuống thấp trong chỉ tiêu từng vị trí; không bảo lưu kết quả – 0,15đ.", "(c) **Hợp đồng làm việc có giá trị như quyết định tuyển dụng** (Điều 21 khoản 2); hoàn thiện hồ sơ chậm nhất **15 ngày** kể từ ngày công khai danh sách trúng tuyển (Điều 20 khoản 1) – 0,15đ.", "(d) **Không còn tập sự** với người tuyển dụng từ 01/7/2026: được xếp lương theo vị trí việc làm tuyển dụng (Luật Viên chức 2025 không có điều về tập sự) – 0,15đ."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 14: Thuật toán tìm kiếm tuần tự]. Nêu bài toán tìm kiếm (đầu vào, đầu ra); mô tả thuật toán tìm kiếm tuần tự bằng ngôn ngữ tự nhiên (5 bước); nêu hai điều kiện dừng.", "a": ["Bài toán tìm kiếm (0,2đ): **đầu vào** là danh sách và đối tượng cần tìm; **đầu ra** là vị trí/thông tin tìm được hoặc thông báo 'không tìm thấy'.", "Thuật toán (0,5đ): xét lần lượt từ đầu đến cuối danh sách theo 5 bước: (1) xem phần tử đầu tiên; (2) so sánh với đối tượng cần tìm; (3) nếu đúng thì ghi kết quả (vị trí/thông tin) và kết thúc; (4) nếu chưa đúng mà đã hết danh sách thì báo 'không tìm thấy' và kết thúc; (5) nếu chưa hết danh sách thì xem phần tử tiếp theo, quay lại bước 2.", "Hai điều kiện dừng (0,3đ): (1) **gặp đúng đối tượng cần tìm**; (2) **hết danh sách** mà không thấy. Thuật toán luôn dừng sau hữu hạn bước.", "Biểu diễn bằng sơ đồ khối có cấu trúc lặp (Hình 14.1) và mô phỏng bằng bảng các bước."]}, {"q": "Câu 2 (1,5đ) [Tin 8 – Bài 8a: Danh sách dạng liệt kê và hình ảnh trong văn bản]. HS soạn 'Nội quy phòng máy' trong Word bằng danh sách có thứ tự (Numbering) gồm 6 mục, đánh số 1 đến 6. (a) Nếu xóa mục 2 và chèn thêm 1 mục mới vào giữa mục 4 và mục 5 (tính theo số thứ tự ban đầu), danh sách mới có mấy mục, đánh số thế nào, mục nào mang số 5? (b) Một danh sách nhiều cấp gồm 8 dòng có cấp lần lượt 1, 2, 2, 1, 2, 3, 2, 1; con trỏ bắt đầu ở cấp 1. Tính số lần dùng Tab và Shift+Tab (theo quy ước Tab tăng cấp, Shift+Tab giảm cấp). (c) Ảnh minh họa kích thước 12 cm × 8 cm, HS kéo góc ảnh cho rộng còn 9 cm: nếu giữ tỉ lệ thì chiều cao mới là bao nhiêu, diện tích còn bao nhiêu phần trăm? (d) Muốn ảnh nằm sau chữ để chữ không bị che, chọn kiểu bao quanh nào? Nêu 2 kiểu danh sách trong Word và tác dụng.", "a": ["(a) Xóa mục 2: còn 5 mục, Word tự đánh lại 1–5 (mục cũ 3 → 2; cũ 4 → 3; cũ 5 → 4; cũ 6 → 5). Chèn mục mới giữa mục cũ 4 và cũ 5: danh sách có 5 + 1 = **6 mục**, đánh **1 đến 6**: mục cũ 1 = 1; cũ 3 = 2; cũ 4 = 3; **mục mới = 4**; **cũ 5 = 5**; cũ 6 = 6. Vậy mục mang số 5 là **mục cũ 5** – 0,5đ.", "(b) Chuyển cấp: 1→2: Tab (1); 2→2: không; 2→1: Shift+Tab (2); 1→2: Tab (3); 2→3: Tab (4); 3→2: Shift+Tab (5); 2→1: Shift+Tab (6). Kết quả: **Tab 3 lần, Shift+Tab 3 lần** (tổng 6 thao tác) – 0,4đ.", "(c) Tỉ lệ 9 : 12 = 0,75 → chiều cao mới = 8 × 0,75 = **6 cm**; diện tích = 9 × 6 = 54 cm² so với 96 cm² → **56,25%** (= 0,75²) – 0,3đ.", "(d) Wrap Text/**Behind Text** (phía sau chữ) – 0,1đ. Hai kiểu danh sách: **dấu đầu dòng (Bullets)** – liệt kê ý ngang hàng; **có thứ tự (Numbering)** – thể hiện trình tự, tự cập nhật số khi thêm/xóa – 0,2đ.", "Lỗi thường gặp: gõ số bằng tay thay vì dùng Numbering; quên Tab để xuống cấp; chưa chỉnh Wrap Text nên ảnh che chữ."]}, {"q": "Câu 3 (1,5đ) [Tin 7 – Bài 2: Phần mềm máy tính]. Xây dựng mục tiêu bài học cho Bài 2 (2 tiết) theo Chương trình giáo dục phổ thông 2018 môn Tin học lớp 7: nêu kiến thức, năng lực tin học (kí hiệu NLa–NLe), năng lực chung, phẩm chất; nêu cách viết mục tiêu để đo được kết quả.", "a": ["Kiến thức (0,6đ): nêu được khái niệm và **3 chức năng của hệ điều hành** (điều khiển phần cứng; quản lí thiết bị và dữ liệu; cung cấp giao diện người dùng, chạy phần mềm ứng dụng); kể tên Windows, Mac OS, Linux, iOS, Android; nêu được khái niệm phần mềm ứng dụng, ví dụ; giải thích được **phần mở rộng tên tệp** cho biết loại tệp; **phân biệt** được hệ điều hành với phần mềm ứng dụng.", "Năng lực tin học (0,4đ): **NLa** – nêu vai trò của hệ điều hành đối với phần cứng, phân biệt hệ điều hành với phần mềm ứng dụng; **NLb** – sử dụng phần mềm hợp pháp, tôn trọng bản quyền.", "Năng lực chung (0,2đ): tự chủ và tự học (đọc SGK, tóm tắt); giao tiếp và hợp tác (thảo luận cặp, nhóm); giải quyết vấn đề (phân loại phần mềm).", "Phẩm chất (0,15đ): chăm chỉ, tự học công nghệ mới; trung thực, trách nhiệm khi dùng phần mềm và AI. Năng lực số/AI (nếu có): kiểm chứng thông tin do AI cung cấp bằng SGK, thầy cô.", "Cách viết (0,15đ): dùng động từ đo được (nêu, kể tên, phân biệt, chọn, giải thích...), gắn sản phẩm/minh chứng (phiếu phân loại, trả lời giơ thẻ), phù hợp thời lượng; không viết mục tiêu của GV ('giúp HS hiểu...') mà viết kết quả HS đạt được."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 14]. Nhận xét đoạn dạy sau: GV nói 'Tìm kiếm tuần tự là xem từng tên từ đầu danh sách, so sánh với tên cần tìm, đúng thì dừng. Vậy thuật toán này luôn tìm được đối tượng'. Rồi GV cho HS hỏi chatbot mô phỏng tìm 'Lê Lan' (không có trong danh sách 8 phần tử) và ghi kết quả chatbot vào vở, không đối chiếu. Nêu 3 điểm chưa phù hợp, đề xuất cách sửa; tính số lần so sánh khi tìm 'Lê Lan' (không có).", "a": ["Điểm chưa phù hợp (0,5đ): (1) **thiếu điều kiện dừng thứ hai** (hết danh sách); (2) kết luận 'luôn tìm được' **sai** – thuật toán luôn dừng nhưng có thể không tìm thấy; (3) HS ghi kết quả AI **không kiểm chứng**, không mô phỏng bằng bảng các bước, không rèn năng lực kiểm chứng/khai báo AI (7.A1.2, 7.A1.MR1).", "Cách sửa (0,3đ): nêu đủ 2 điều kiện dừng; cho HS tự mô phỏng bảng (lần so sánh – phần tử – kết quả) với 'Lê Lan' để phát hiện điều kiện dừng 2; sau đó mới cho chatbot mô phỏng để HS đối chiếu, chỉ ra chỗ sai (vị trí, điều kiện dừng) và khai báo khi dùng AI.", "Tính (0,2đ): danh sách 8 phần tử, không có tên cần tìm → xét hết **8 lần so sánh**, rồi dừng vì hết danh sách và báo 'không tìm thấy'."]}], "p3": [{"q": "Tình huống (2đ). Tiết thực hành Tin học 7 có 36 học sinh, nhưng phòng máy chỉ còn 14 máy chạy được; 22 máy hỏng do mất điện đột ngột tuần trước. Em đã báo cho nhân viên thiết bị nhưng chưa có kinh phí sửa. Hiệu trưởng nhắc 'tuần này vẫn phải đủ tiết thực hành, không được bỏ nội dung'. Em xử lí như thế nào? Nêu căn cứ.", "a": ["Nhận định (0,2đ): phải bảo đảm an toàn, chất lượng và thực hiện chương trình; điều kiện cơ sở vật chất là vấn đề cần báo cáo, không được tự ý bỏ tiết hay đối phó.", "Bước 1 – Báo cáo bằng văn bản (0,4đ): gửi tổ trưởng chuyên môn, nhân viên thiết bị, ban giám hiệu: số máy hỏng/còn dùng, nguyên nhân, ảnh hưởng, đề xuất sửa chữa, kiểm tra an toàn điện; lưu hồ sơ (Luật Viên chức 2025 Điều 8 khoản 1, 2: thực hiện đúng nhiệm vụ, chịu trách nhiệm; báo cáo khi phát hiện vấn đề trong đơn vị).", "Bước 2 – Điều chỉnh kế hoạch bài dạy, vẫn đủ nội dung (0,6đ): chia lớp 36 HS thành nhóm 2–3 HS/máy (14 máy); xoay vòng nhóm thực hành (nhóm không có máy làm nhiệm vụ lí thuyết, mô phỏng bằng thẻ, phiếu học tập 'không cắm điện'); dùng sơ đồ khối, bảng mô phỏng thuật toán trên giấy cho bài thuật toán; thực hành nội dung ngắn trên máy thay vì cả tiết; đánh giá bằng sản phẩm của nhóm; có thể dạy thực hành bù khi máy được sửa. Dùng thiết bị cá nhân của HS chỉ khi nhà trường cho phép và bảo đảm an toàn thông tin, quản lí HS.", "Bước 3 – Bảo đảm an toàn (0,2đ): không cho HS dùng máy nghi hỏng, ổ điện hở; kiểm tra thiết bị trước tiết; nhắc nội quy phòng máy.", "Căn cứ (0,4đ): Luật Nhà giáo 2025 Điều 8 khoản 2 điểm a (nhà giáo được chủ động sắp xếp nội dung, thời lượng theo chương trình, lựa chọn tài liệu, học liệu) và Điều 9 khoản 2 điểm a (thực hiện đầy đủ, có chất lượng chương trình); TT 15/2026 Điều 18 (thiết bị dạy học theo danh mục tối thiểu, giáo viên tự làm thiết bị, ứng dụng AI) và Điều 21 (kế hoạch bài dạy là hồ sơ của giáo viên); trách nhiệm của hiệu trưởng về cơ sở vật chất: đối chiếu văn bản gốc.", "Bước 4 – Trao đổi với hiệu trưởng (0,2đ): thể hiện chính kiến, tham mưu phương án (TT 03/2026 Điều 7: chấp hành phân công, chỉ đạo; tích cực tham mưu, thể hiện chính kiến theo nhiệm vụ), không phản ứng gay gắt hay đổ lỗi."]}]}, {"de": 9, "focus_luat": ["L9", "L2", "L4", "L6"], "focus_bai": ["B9", "B15", "B2"], "p1": [{"q": "Câu 1 (0,75đ). Theo Điều lệ trường phổ thông (Thông tư 15/2026/TT-BGDĐT): (a) nêu hồ sơ riêng của giáo viên và của giáo viên chủ nhiệm (Điều 21); (b) nêu các yêu cầu khi đánh giá học sinh (Điều 22); (c) giáo viên chủ nhiệm được cho phép học sinh nghỉ học tối đa bao lâu (Điều 26); (d) giá trị của hồ sơ điện tử.", "a": ["(a) Giáo viên: **kế hoạch bài dạy (giáo án)**; giáo viên chủ nhiệm: **sổ chủ nhiệm**; (tổng phụ trách Đội: sổ công tác Đội) – 0,2đ.", "(b) Đánh giá theo quy định của Bộ; toàn diện, công bằng, trung thực, khách quan, vì sự tiến bộ; chú trọng đánh giá quá trình; **không so sánh** học sinh này với học sinh khác; bảo mật thông tin, kết quả học tập; **không gây áp lực** cho học sinh, giáo viên, cha mẹ – 0,25đ.", "(c) Cho phép cá nhân học sinh có lí do chính đáng nghỉ học **không quá 03 ngày liên tục** (Điều 26 khoản 3) – 0,15đ.", "(d) Hồ sơ quản lí chủ yếu ở dạng **điện tử**, có **giá trị pháp lí tương đương** hồ sơ giấy, thay thế theo lộ trình (Điều 21 khoản 4) – 0,15đ."]}, {"q": "Câu 2 (0,75đ). Theo Luật Giáo dục 2019 (đã sửa đổi bởi Luật 123/2025/QH15): (a) nêu 6 hành vi bị nghiêm cấm trong cơ sở giáo dục (Điều 22); (b) giáo dục THCS thực hiện trong mấy năm học, tuổi vào lớp sáu là bao nhiêu (Điều 28).", "a": ["(a) Sáu hành vi (Điều 22), mỗi ý đúng 0,1đ: (1) xúc phạm nhân phẩm, danh dự, xâm phạm thân thể nhà giáo, cán bộ, người lao động và người học; (2) xuyên tạc nội dung giáo dục; (3) gian lận trong học tập, kiểm tra, thi, tuyển sinh; (4) hút thuốc; uống rượu, bia; gây rối an ninh, trật tự; (5) ép buộc học sinh học thêm để thu tiền; (6) lợi dụng việc tài trợ, ủng hộ giáo dục để ép buộc đóng góp tiền hoặc hiện vật – 0,6đ.", "(b) THCS: **04 năm học**, từ lớp sáu đến hết lớp chín; tuổi vào lớp sáu: **11 tuổi** (Điều 28 khoản 1 điểm b) – 0,15đ."]}, {"q": "Câu 3 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) thời hạn cơ quan có thẩm quyền xem xét, quyết định việc điều động nhà giáo; (b) nguyên tắc thuyên chuyển nhà giáo; (c) dạy liên trường: ai ra quyết định phân công, số tiết dạy tính thế nào, ai chi trả lương, ai thực hiện đánh giá; (d) hồ sơ nghỉ hưu ở tuổi cao hơn nộp trước bao lâu.", "a": ["(a) **30 ngày làm việc** kể từ ngày nhận đủ hồ sơ hợp lệ; không đồng ý phải trả lời bằng văn bản nêu lí do (Điều 11 khoản 4) – 0,15đ.", "(b) Thuyên chuyển theo **nguyện vọng** nhà giáo; phải được **sự đồng ý của cơ sở/cơ quan nơi đi và nơi đến**, phù hợp vị trí việc làm (Điều 12 khoản 1) – 0,2đ.", "(c) Dạy liên trường (Điều 13): **Chủ tịch UBND cấp xã hoặc Giám đốc Sở GDĐT** ra quyết định phân công (nêu rõ thời gian, khối lượng giảng dạy, trách nhiệm phối hợp); số tiết theo chế độ làm việc = **tổng số tiết** ở các cơ sở; lương và chế độ theo lương do cơ sở **quản lí nhà giáo** chi trả; đánh giá do người đứng đầu cơ sở quản lí nhà giáo thực hiện trên cơ sở nhận xét của cơ sở nơi đến dạy – 0,3đ.", "(d) Hồ sơ nộp trước thời điểm nghỉ hưu ít nhất **06 tháng**; cơ sở xem xét trong 30 ngày làm việc (Điều 18 khoản 3) – 0,1đ."]}, {"q": "Câu 4 (0,75đ). Theo Nghị quyết 248/2025/QH15: (a) nêu quy định về sách giáo khoa (Điều 3); (b) khi hội đồng trường công lập chấm dứt hoạt động, cơ quan quản lí trực tiếp làm gì trong thời gian chuyển tiếp, cấp phó vượt quy định được giữ trong bao lâu (Điều 7); (c) Nghị quyết 248 có quy định miễn học phí cho học sinh phổ thông công lập không? Nội dung đó nằm ở đâu?", "a": ["(a) Bộ trưởng Bộ GDĐT quyết định **một bộ sách giáo khoa** giáo dục phổ thông dùng thống nhất toàn quốc, thực hiện từ **năm học 2026–2027**; đến **2030** hoàn thành cung cấp **miễn phí SGK** cho học sinh; ưu tiên biên giới, hải đảo, vùng dân tộc thiểu số và miền núi, vùng đặc biệt khó khăn (Điều 3 khoản 1) – 0,3đ.", "(b) Trong **06 tháng** sau khi hội đồng trường chấm dứt, cơ quan quản lí trực tiếp quyết định công việc tổ chức, nhân sự do hội đồng trường đảm nhiệm và quyết định người đứng đầu theo tiêu chuẩn Bộ trưởng quy định (khoản 1); cho phép số lượng cấp phó **vượt quy định tối đa trong 05 năm**, lập kế hoạch giảm dần (khoản 2) – 0,3đ.", "(c) **Không**: miễn học phí phổ thông công lập nằm ở **Luật Giáo dục (Luật 123/2025) Điều 99 khoản 3**; NQ 248 chỉ có miễn học phí môn Giáo dục quốc phòng và an ninh ở giáo dục nghề nghiệp, đại học (Điều 3 khoản 1 đoạn 2). Nghị quyết 217/2025/QH15 và Nghị định 238/2025/NĐ-CP về miễn, hỗ trợ học phí: đối chiếu văn bản gốc – 0,15đ."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 15: Thuật toán tìm kiếm nhị phân]. Nêu điều kiện áp dụng, các bước của thuật toán tìm kiếm nhị phân, điều kiện dừng; so sánh với tìm kiếm tuần tự; nêu mối liên hệ giữa sắp xếp và tìm kiếm.", "a": ["Điều kiện (0,2đ): danh sách phải được **sắp xếp** (tăng dần hoặc giảm dần).", "Các bước (0,4đ): xác định vùng tìm kiếm (đầu, cuối); lấy phần tử **ở giữa** (vị trí giữa = (đầu + cuối) : 2, lấy phần nguyên – đối chiếu SGK về cách làm tròn); so sánh với đối tượng cần tìm: bằng nhau thì dừng, báo kết quả; nhỏ hơn/lớn hơn thì **loại bỏ một nửa** danh sách không chứa đối tượng, thu hẹp vùng tìm kiếm; lặp lại.", "Điều kiện dừng (0,1đ): tìm thấy đối tượng; hoặc vùng tìm kiếm **rỗng** (hết) → không có trong danh sách.", "So sánh (0,2đ): tuần tự không cần danh sách sắp xếp, xét từng phần tử, nhiều bước; nhị phân cần sắp xếp trước nhưng **nhanh hơn** (ví dụ SGK tìm 'Trúc': nhị phân 3 bước, tuần tự 8 bước). Với danh sách 7 phần tử, nhị phân tối đa 3 lần so sánh.", "Mối liên hệ (0,1đ): **sắp xếp giúp tìm kiếm nhanh hơn**; HS hay quên điều kiện phải sắp xếp, tính sai vị trí giữa của nửa còn lại."]}, {"q": "Câu 2 (1,5đ) [Tin 8 – Bài 8b: Phần mềm chỉnh sửa ảnh]. Một ảnh chụp có kích thước 1920 × 1080 pixel. (a) Tính tổng số pixel. (b) Nếu giảm kích thước còn 50% theo mỗi chiều thì kích thước mới và số pixel là bao nhiêu, bằng bao nhiêu phần số pixel ban đầu? (c) Nếu lưu không nén với 3 byte cho mỗi pixel thì dung lượng khoảng bao nhiêu (làm tròn 1 chữ số thập phân, 1 MB = 1 000 000 byte)? (d) Ảnh trong GIMP có 3 lớp từ trên xuống: lớp 3 'Chữ', lớp 2 'Hình chữ nhật xanh phủ nửa ảnh', lớp 1 'Nền'. HS chọn lớp 1 rồi tô màu đỏ toàn lớp. Ảnh hiển thị thế nào? (e) Phân biệt Save và Export As; chọn jpg hay png cho ảnh chụp cảnh.", "a": ["(a) 1920 × 1080 = **2.073.600 pixel** – 0,2đ.", "(b) 50% mỗi chiều: **960 × 540** = **518.400 pixel** = **1/4** số pixel ban đầu (0,5² = 0,25) – 0,3đ.", "(c) 2.073.600 × 3 = **6.220.800 byte** ≈ **6,2 MB** (hoặc ≈ 5,9 MiB nếu chia 1024²) – 0,3đ.", "(d) Lớp trên che lớp dưới; thao tác chỉ tác động lên **lớp đang chọn** → phần nền chuyển đỏ nhưng nửa ảnh bị hình chữ nhật xanh (lớp 2) che và chữ (lớp 3) vẫn thấy; chỉ phần nền không bị che mới nhìn thấy màu đỏ – 0,3đ.", "(e) **Save**: lưu ảnh ở định dạng riêng của GIMP, giữ các lớp để chỉnh tiếp; **Export As**: xuất ra ảnh thông dụng như jpg, png để chia sẻ (0,2đ). Ảnh chụp cảnh: thường chọn **jpg** (dung lượng nhỏ); png phù hợp khi cần giữ chất lượng hoặc nền trong suốt – đối chiếu SGK về cách trình bày hai định dạng (0,2đ)."]}, {"q": "Câu 3 (1,5đ) [Tin 7 – Bài 3: Quản lí dữ liệu trong máy tính]. Thiết kế hoạt động thực hành 'Tạo cây thư mục và quản lí tệp' (khoảng 15 phút, File Explorer): nêu mục tiêu, sản phẩm, tiến trình 4 bước chuyển giao – thực hiện – báo cáo – kết luận, tiêu chí đánh giá.", "a": ["Mục tiêu (0,3đ): tạo được cây thư mục; đổi tên, sao chép, di chuyển, xóa tệp, thư mục (Rename, Copy, Cut, Delete); đặt tên dễ nhớ. Năng lực tin học: **NLa** (dùng File Explorer), **NLc** (tổ chức dữ liệu để dễ tìm); năng lực chung: tự chủ và tự học, giải quyết vấn đề; phẩm chất: ngăn nắp, cẩn thận.", "Sản phẩm (0,1đ): cây thư mục (ví dụ thư mục 'HocTap' có các thư mục con theo môn, học kì) chụp ảnh màn hình; nhật kí thao tác.", "Bước 1 – Chuyển giao (0,25đ): GV chiếu cây thư mục mẫu, nêu yêu cầu: tạo đúng cấu trúc, đổi tên một thư mục, sao chép một tệp sang thư mục khác, di chuyển một tệp, xóa tệp thừa; làm theo cặp.", "Bước 2 – Thực hiện (0,4đ): GV làm mẫu nhanh 1 thao tác; HS làm theo cặp, một HS thao tác – một HS kiểm tra theo phiếu; GV quan sát, hỗ trợ HS lúng túng; nhắc phân biệt Copy (còn bản gốc) với Cut (di chuyển).", "Bước 3 – Báo cáo (0,2đ): 2 cặp trình bày cây thư mục; nhóm khác nhận xét tên có dễ nhớ không, cấu trúc có hợp lí không.", "Bước 4 – Kết luận (0,25đ): GV chốt thao tác, nhấn mạnh đặt tên dễ nhớ, tổ chức cây thư mục hợp lí; đánh giá bằng phiếu: đúng cấu trúc, đúng thao tác, thời gian, hợp tác."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 3]. HS A đặt mật khẩu tài khoản học tập là 'NguyenVanAn2012' (tên và năm sinh của em), HS B đặt 'Tn#7a$Q9x!'. Chatbot AI nói với lớp: 'Mật khẩu có chữ hoa và chữ thường là mật khẩu mạnh'. (a) Đánh giá hai mật khẩu theo tiêu chí mật khẩu mạnh. (b) Nhận xét câu trả lời của chatbot, cách tổ chức cho HS kiểm chứng và hậu quả nếu không kiểm chứng. (c) Nêu 3 biện pháp bảo vệ dữ liệu trong máy tính.", "a": ["(a) Tiêu chí (0,3đ): ít nhất 8 kí tự; có chữ hoa, chữ thường, số, kí hiệu; không dùng tên người, ngày sinh. Mật khẩu của A: 15 kí tự, có chữ hoa, thường, số nhưng chứa **tên và năm sinh**, **thiếu kí hiệu** → **chưa mạnh**. Mật khẩu của B: 10 kí tự, đủ chữ hoa, thường, số, kí hiệu, không chứa thông tin cá nhân → **mạnh**.", "(b) Chatbot **sai/thiếu**: chữ hoa, chữ thường chưa đủ; cần cả số, kí hiệu, đủ dài và không dùng thông tin dễ đoán – 0,2đ. Kiểm chứng: HS đối chiếu SGK, bảng tiêu chí, thảo luận độ tin cậy (7.A1.MR1). Hậu quả nếu không kiểm chứng: đặt mật khẩu yếu, lộ tài khoản, mất dữ liệu cá nhân (7.A1.2) – 0,25đ.", "(c) Ba biện pháp (0,25đ): **sao lưu dữ liệu** (cục bộ ở thiết bị ngoài hoặc từ xa trên đám mây); dùng **mật khẩu mạnh**, giữ bí mật mật khẩu; dùng **phần mềm chống virus**, luôn bật và cập nhật."]}], "p3": [{"q": "Tình huống (2đ). Trong giờ ra chơi, phụ huynh em H (học sinh lớp 7) đến trường vì con bị em nhắc nhở và cho điểm 5 bài kiểm tra Tin học. Phụ huynh to tiếng xúc phạm em trước cổng trường, quay clip rồi đăng lên Facebook, cắt ghép để thể hiện như em 'mắng con' và kèm lời lẽ xúc phạm. Clip có hàng trăm lượt chia sẻ. Em xử lí như thế nào? Nêu căn cứ.", "a": ["Nhận định (0,2đ): hành vi xúc phạm danh dự, nhân phẩm nhà giáo và đưa thông tin sai lệch lên mạng; cần xử lí bình tĩnh, đúng quy trình, bảo vệ uy tín nhà giáo và quyền lợi của HS H.", "Bước 1 – Tại chỗ (0,3đ): giữ bình tĩnh, ứng xử mẫu mực, không đáp trả, không tranh cãi; mời phụ huynh vào phòng làm việc/nhờ bảo vệ, ban giám hiệu hỗ trợ; không xử lí nóng giận, không trút lên HS H.", "Bước 2 – Báo cáo (0,3đ): báo cáo ngay hiệu trưởng, tổ trưởng chuyên môn, GVCN; viết tường trình trung thực, sự việc diễn biến, nội dung kiểm tra, thang điểm.", "Bước 3 – Giữ bằng chứng, xử lí nội dung (0,3đ): lưu clip gốc và bản cắt ghép, link, số lượt chia sẻ; nhà trường làm việc với phụ huynh, yêu cầu gỡ clip và đính chính; nhà trường (không phải cá nhân em) phát đi thông tin chính thức, chính xác trên kênh chính thống; em không đăng bài tranh cãi trên mạng (TT 03/2026 Điều 4 khoản 2: có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng; Điều 9 khoản 3: chống tin giả trên kênh mạng xã hội chính thống).", "Bước 4 – Công khai minh bạch chuyên môn (0,3đ): rà soát lại bài kiểm tra, thang điểm, giải thích cho phụ huynh bằng văn bản/cuộc họp có đại diện nhà trường (TT 03/2026 Điều 8 khoản 2: trao đổi thông tin trung thực về người học khi được cấp quản lí đồng ý); nếu chấm sai thì điều chỉnh; hướng dẫn kênh khiếu nại đúng quy định.", "Bước 5 – Xử lí vi phạm (0,3đ): nếu phụ huynh vẫn cố tình, nhà trường báo cáo cấp quản lí/cơ quan chức năng để xử lí theo pháp luật.", "Căn cứ (0,3đ): Luật Nhà giáo Điều 8 khoản 2 điểm c (nhà giáo được tôn trọng, bảo vệ uy tín, danh dự, nhân phẩm) và Điều 37 (xử lí hành vi xâm phạm uy tín, danh dự, nhân phẩm nhà giáo); Luật Giáo dục Điều 22 khoản 1 (cấm xúc phạm nhân phẩm, danh dự, xâm phạm thân thể nhà giáo) và Điều 90 (gia đình tôn trọng nhà giáo, không xúc phạm danh dự, nhân phẩm – số khoản đối chiếu văn bản gốc); TT 06/2019 Điều 9 khoản 2 (cha mẹ không bịa đặt thông tin, không xúc phạm tinh thần, danh dự, nhân phẩm giáo viên)."]}]}, {"de": 10, "focus_luat": ["L1", "L3", "L5", "L7"], "focus_bai": ["B10", "B16", "B3"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) nêu các hình thức kỉ luật viên chức; (b) thời hiệu xử lí kỉ luật và thời hạn xử lí kỉ luật; (c) trường hợp đương nhiên bị buộc thôi việc.", "a": ["(a) **4 hình thức** (Điều 35 khoản 1): khiển trách; cảnh cáo; cách chức (áp dụng với viên chức quản lí); buộc thôi việc – 0,25đ.", "(b) Thời hiệu: **05 năm** (khiển trách), **10 năm** (các hình thức còn lại) (Điều 36 khoản 1); có trường hợp không áp dụng thời hiệu (đảng viên vi phạm đến mức khai trừ, vi phạm bảo vệ chính trị nội bộ, xâm hại lợi ích quốc gia, dùng văn bằng chứng chỉ giả...) (khoản 2). Thời hạn xử lí kỉ luật **không quá 90 ngày**; trường hợp phức tạp kéo dài **không quá 150 ngày** (khoản 3) – 0,3đ.", "(c) Bị Tòa án kết án **phạt tù không được hưởng án treo** hoặc bị kết án về **tội tham nhũng** thì đương nhiên bị buộc thôi việc kể từ ngày bản án có hiệu lực (Điều 35 khoản 3); viên chức quản lí phạm tội bị kết án đương nhiên thôi giữ chức vụ – 0,2đ."]}, {"q": "Câu 2 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15: (a) nêu những việc nhà giáo không được làm đối với người học (Điều 11 khoản 2); (b) tạm đình chỉ giảng dạy: ai quyết định, trong trường hợp nào (Điều 36); (c) Ngày Nhà giáo Việt Nam (Điều 32).", "a": ["(a) Nhà giáo không được (Điều 11 khoản 2), mỗi ý đúng 0,1đ: phân biệt đối xử giữa người học dưới mọi hình thức; gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học; ép buộc người học tham gia học thêm dưới mọi hình thức; ép buộc người học nộp tiền hoặc hiện vật ngoài quy định (đối chiếu văn bản gốc về nguyên văn điểm d) – 0,4đ. Công lập: còn không được làm những việc viên chức không được làm (khoản 1).", "(b) **Người đứng đầu cơ sở giáo dục** quyết định tạm đình chỉ giảng dạy trong thời hạn xem xét kỉ luật nếu việc tiếp tục giảng dạy gây khó khăn cho xem xét kỉ luật hoặc ảnh hưởng uy tín nhà giáo, tâm lí người học (Điều 36) – 0,25đ.", "(c) Ngày **20 tháng 11** hằng năm (Điều 32) – 0,1đ."]}, {"q": "Câu 3 (0,75đ). Theo Nghị định 259/2026/NĐ-CP: (a) Trong một kì xét tuyển viên chức có 01 chỉ tiêu, thí sinh A là người dân tộc thiểu số, đồng thời là con thương binh, điểm vòng 2 là 72; thí sinh B là thương binh, điểm vòng 2 là 70. Tính điểm xét của hai thí sinh và cho biết ai trúng tuyển (điều kiện khác như nhau). (b) Nêu mức điểm ưu tiên của 3 nhóm đầu. (c) Thành phần Hội đồng tuyển dụng và những người không được bố trí vào Hội đồng.", "a": ["(a) Điểm ưu tiên cộng vào kết quả **vòng 2**; thuộc nhiều diện chỉ cộng mức **cao nhất** (Điều 8 khoản 2). A: dân tộc thiểu số và con thương binh đều thuộc nhóm **5 điểm** → chỉ cộng 5: 72 + 5 = **77**. B: thương binh thuộc nhóm **7,5 điểm**: 70 + 7,5 = **77,5**. Vậy **B trúng tuyển** (77,5 > 77), cả hai đều trên 50 điểm – 0,35đ.", "(b) Nhóm 7,5 điểm: Anh hùng LLVTND, Anh hùng Lao động, thương binh, người hưởng chính sách như thương binh, thương binh loại B; nhóm 5 điểm: người dân tộc thiểu số, sĩ quan quân đội/công an phục viên, xuất ngũ, con liệt sĩ, con thương binh...; nhóm 2,5 điểm: người hoàn thành nghĩa vụ quân sự, nghĩa vụ tham gia công an nhân dân... (Điều 8 khoản 1 a, b, c) – 0,2đ.", "(c) Hội đồng **05 hoặc 07 thành viên**; Chủ tịch là người đứng đầu hoặc cấp phó cơ quan có thẩm quyền tuyển dụng; Phó Chủ tịch là người phụ trách tổ chức cán bộ; ủy viên kiêm thư kí; quyết định theo đa số. Không bố trí người có quan hệ vợ/chồng, cha mẹ, con, anh chị em ruột... với người dự tuyển; người đang trong thời hạn xử lí kỉ luật hoặc thi hành kỉ luật, người đã bị xử lí về tham nhũng, tiêu cực trong công tác cán bộ (Điều 9) – 0,2đ. Với nhà giáo: thêm diện +5 điểm riêng theo NĐ 93 Điều 6, cũng chỉ cộng mức cao nhất."]}, {"q": "Câu 4 (0,75đ). Theo Thông tư 03/2026/TT-BGDĐT: (a) nêu 3 điều nhà giáo không được làm với người học (Điều 5); (b) khi nào nhà giáo được cung cấp thông tin về chương trình, kế hoạch giảng dạy cho cha mẹ người học (Điều 8)? (c) Cơ sở giáo dục có trách nhiệm gì trong tổ chức thực hiện quy tắc ứng xử? (d) Theo TT 06/2019, thủ trưởng cơ sở giáo dục báo cáo việc thực hiện bộ Quy tắc ứng xử định kì thế nào?", "a": ["(a) Ví dụ (mỗi ý 0,1đ): không phân biệt đối xử giữa người học; không xúc phạm, gây tổn thương, trù dập, bạo hành, xâm hại người học – **phải báo cáo kịp thời** khi phát hiện người học bị bạo lực, xâm hại; không ép buộc người học tham gia hoạt động mang tính tự nguyện; không công khai thông tin người học trái quy định; không gian lận, làm sai lệch kết quả đánh giá – 0,3đ.", "(b) Khi **được sự đồng ý của cấp quản lí theo thẩm quyền**, và thông tin về người học phải trung thực (Điều 8 khoản 2) – 0,15đ.", "(c) Cụ thể hóa, ban hành quy tắc chi tiết; **công khai** trên website hoặc niêm yết bảng tin; phổ biến đến cán bộ, nhà giáo, người học, cha mẹ; thiết lập **kênh phản ánh** hành vi ứng xử an toàn, bảo mật; khen thưởng, kỉ luật; báo cáo (số điều phần tổ chức thực hiện: đối chiếu văn bản gốc) – 0,15đ.", "(d) TT 06/2019 Điều 13 khoản 3: tổ chức thực hiện, đánh giá, tổng kết, báo cáo cấp quản lí trực tiếp **định kì mỗi năm học** – 0,15đ."]}], "p2": [{"q": "Câu 1 (1đ) [Tin 7 – Bài 16: Thuật toán sắp xếp]. Nêu ý nghĩa của sắp xếp và thao tác hoán đổi; mô tả thuật toán sắp xếp nổi bọt (hướng duyệt, điều kiện đổi chỗ, điều kiện dừng); mô tả sắp xếp chọn; nêu ý nghĩa của việc chia bài toán thành bài toán nhỏ.", "a": ["Ý nghĩa (0,2đ): sắp xếp tăng dần/giảm dần giúp dữ liệu có thứ tự, **dễ tìm kiếm**; hoán đổi hai phần tử cần một **chỗ trống tạm** (biến trung gian).", "Nổi bọt (0,4đ): duyệt từ **cuối dãy lên đầu**, so sánh cặp phần tử cạnh nhau, nếu số sau nhỏ hơn số trước thì **đổi chỗ**; sau mỗi vòng số nhỏ nhất **nổi lên đầu**; lặp các vòng; **dừng** khi một vòng không còn hoán đổi nào.", "Sắp xếp chọn (0,2đ): tìm phần tử nhỏ nhất trong phần chưa sắp xếp rồi đổi chỗ với phần tử đầu phần đó; lặp cho phần còn lại.", "Chia bài toán nhỏ (0,2đ): sắp xếp cả dãy được đưa về lặp lại việc sắp xếp dãy ngắn hơn/đưa một phần tử về đúng chỗ, giúp bài toán đơn giản, dễ mô phỏng, dễ kiểm tra. Lỗi thường gặp: duyệt từ đầu dãy; dừng sớm khi chưa kiểm tra vòng không đổi."]}, {"q": "Câu 2 (1,5đ) [Tin 8 – Bài 12: Từ thuật toán đến chương trình]. Cho chương trình Scratch: lặp 5 lần { di chuyển 80 bước; xoay phải 72° }. (a) Chương trình vẽ hình gì? Tính tổng số bước di chuyển (chu vi) và tổng góc quay. (b) Nêu thông số lặp, di chuyển, xoay để vẽ lục giác đều cạnh 50 và bát giác đều cạnh 40; tính chu vi mỗi hình. (c) Một HS cho rằng ngũ giác đều có góc trong 108° nên phải xoay 108°. Nhận xét và nêu tổng góc quay nếu làm theo HS này. (d) Nêu quan hệ giữa thuật toán (sơ đồ khối) và chương trình; chỉ ra khối lệnh tương ứng với bước 'lặp' và 'quay'.", "a": ["(a) Vẽ **ngũ giác đều** cạnh 80; chu vi = 5 × 80 = **400 bước**; tổng góc quay = 5 × 72° = **360°** (quy tắc: góc quay = 360° : số cạnh) – 0,4đ.", "(b) Lục giác đều: **lặp 6 lần**, di chuyển **50 bước**, xoay phải **60°** (360 : 6); chu vi = 6 × 50 = **300 bước**. Bát giác đều: **lặp 8 lần**, di chuyển **40 bước**, xoay **45°** (360 : 8); chu vi = 8 × 40 = **320 bước** – 0,4đ.", "(c) HS **nhầm góc quay với góc trong hình** (lỗi thường gặp, tương tự tam giác đều phải xoay 120°, không phải 60°). Nếu xoay 108° sau 5 lần: tổng quay 5 × 108° = **540°**, không phải bội của 360° nên hướng cuối lệch 180° so với ban đầu và hình **không khép kín** – 0,35đ.", "(d) Chương trình là **dãy lệnh** điều khiển máy tính thực hiện một thuật toán; mỗi bước trong sơ đồ khối ứng với một lệnh/khối lệnh Scratch: bước lặp ↔ khối 'lặp n lần'; di chuyển ↔ 'di chuyển ... bước'; quay ↔ 'xoay phải ... độ' (với tam giác đều: lặp 3, di chuyển 100, xoay 120°; hình vuông: lặp 4, xoay 90°) – 0,35đ."]}, {"q": "Câu 3 (1,5đ) [Tin 7 – Bài 5: Ứng xử trên mạng]. Thiết kế hoạt động dạy học sử dụng kĩ thuật đóng vai kết hợp giơ thẻ A/B cho nội dung phân biệt hành vi nên và không nên khi giao tiếp qua mạng và cách xử lí khi bị bắt nạt trên mạng (khoảng 15 phút). Nêu mục tiêu, chuẩn bị, tiến trình 4 bước, lưu ý sư phạm.", "a": ["Mục tiêu (0,3đ): phân biệt hành vi nên/không nên khi giao tiếp qua mạng; nêu cách xử lí khi bị bắt nạt (nhờ bố mẹ, thầy cô giúp đỡ, không giấu). Năng lực tin học: **NLb** (ứng xử phù hợp trong môi trường số), **NLe** (hợp tác, nhờ người lớn hỗ trợ); năng lực chung: giao tiếp và hợp tác, giải quyết vấn đề; phẩm chất: nhân ái, trách nhiệm, trung thực.", "Chuẩn bị (0,1đ): 3 tình huống ngắn (bình luận chê bạn; bị nhắn tin dọa nạt; nhận link lạ), thẻ A (nên)/B (không nên), phiếu quan sát, kịch bản gợi ý.", "Bước 1 – Chuyển giao (0,25đ): GV nêu tình huống, chia nhóm 4, mỗi nhóm bốc 1 tình huống; yêu cầu chuẩn bị 2 phút để đóng vai và xử lí đúng cách.", "Bước 2 – Thực hiện (0,4đ): nhóm phân vai (người đăng, bạn bị bắt nạt, người chứng kiến, người lớn); tập đóng vai tình huống xử lí đúng; GV quan sát, nhắc không dùng lời lẽ xúc phạm thật.", "Bước 3 – Báo cáo (0,25đ): 2–3 nhóm trình diễn; lớp giơ thẻ A/B đánh giá hành vi nhân vật, giải thích lí do; nhóm đóng vai nói cảm nhận.", "Bước 4 – Kết luận (0,2đ): GV chốt: lịch sự, tôn trọng; không đáp trả; chụp lại bằng chứng, **nhờ người lớn**; gặp thông tin xấu thì đóng trang và báo người lớn; 'chia sẻ – rời xa – giới hạn – theo đuổi' để tránh nghiện Internet.", "Lưu ý (không tính điểm riêng): không dùng tên bạn thật làm 'nạn nhân'; không gán vai tiêu cực cho HS vốn bị bạn bè xa lánh; bảo mật tâm lí; có phương án nếu có HS chia sẻ trải nghiệm thật (báo GVCN, tư vấn học đường)."]}, {"q": "Câu 4 (1đ) [Tin 7 – Bài 16]. Chatbot AI trả lời: 'Sắp xếp nổi bọt dãy 3, 5, 4, 1, 2 (duyệt từ đầu): vòng 1: 3, 4, 1, 2, 5; vòng 2: 3, 1, 2, 4, 5; vòng 3: 1, 2, 3, 4, 5. Tổng cộng 6 lần hoán đổi.' (a) Thực hiện đúng theo SGK (duyệt từ cuối dãy lên đầu): ghi dãy sau mỗi vòng và số lần hoán đổi. (b) Chỉ ra điểm khác/sai trong câu trả lời của chatbot. (c) Nêu cách tổ chức cho HS kiểm chứng và khai báo khi dùng AI.", "a": ["(a) Duyệt từ cuối lên đầu: vòng 1: **1, 3, 5, 4, 2** (3 lần hoán đổi); vòng 2: **1, 2, 3, 5, 4** (3 lần); vòng 3: **1, 2, 3, 4, 5** (1 lần); vòng 4: không hoán đổi → dừng. Tổng **7 lần** hoán đổi – 0,5đ.", "(b) Chatbot duyệt từ **đầu dãy** (số lớn nhất 'nổi' về cuối), khác cách duyệt của SGK; kết quả cuối đúng nhưng các vòng trung gian khác SGK; **tổng số lần hoán đổi sai**: duyệt từ đầu cũng cần 3 + 2 + 2 = 7 lần (bằng số cặp ngược thứ tự của dãy), không phải 6; chatbot cũng không nêu vòng kiểm tra cuối không còn hoán đổi – 0,25đ.", "(c) Cách kiểm chứng (0,25đ): HS tự mô phỏng bằng thẻ số/bảng theo SGK, đối chiếu từng vòng, đếm lần hoán đổi, thảo luận độ tin cậy (7.A1.MR1); nêu hậu quả nếu tin ngay (7.A1.2); khai báo 'có dùng AI ở phần nào, đã kiểm chứng ra sao'."]}], "p3": [{"q": "Tình huống (2đ). Em là giáo viên Tin học kiêm giáo viên chủ nhiệm lớp 7C. Hai tuần nay em K bỏ tiết cuối buổi chiều, có hôm vào phòng máy tự ý chơi game khi chưa được phép, bạn bè phản ánh em K ra quán net chơi game và vay tiền bạn. Bố mẹ em K làm xa nhà, em ở với ông bà. Khi em gọi điện, bà nói 'cháu nó ngoan, chắc cô hiểu nhầm'. Em xử lí như thế nào? Nêu căn cứ.", "a": ["Nhận định (0,2đ): dấu hiệu sa đà trò chơi điện tử, bỏ học; cần xác minh, hỗ trợ, phối hợp gia đình – nhà trường; không quy kết, không trừng phạt nặng nề, không công khai trước lớp.", "Bước 1 – Xác minh và nói chuyện riêng với K (0,5đ): tìm hiểu nguyên nhân (áp lực học, thiếu người quan tâm, bạn bè rủ rê, nợ tiền); lắng nghe, không áp đặt; xác định mức độ thời gian chơi; hướng dẫn K nhận ra tác hại: hại sức khỏe, học tập, quan hệ (nội dung Bài 5 Tin 7), áp dụng 'chia sẻ – rời xa – giới hạn – theo đuổi' (TT 03/2026 Điều 5 khoản 3: lắng nghe, kịp thời tư vấn, hỗ trợ về học tập, xã hội, phù hợp tâm sinh lí).", "Bước 2 – Phối hợp gia đình (0,4đ): trao đổi với ông bà và liên hệ bố mẹ qua điện thoại/họp trực tuyến; cung cấp thông tin **trung thực** về việc K nghỉ tiết, kết quả học tập, cam kết cùng hỗ trợ (TT 03/2026 Điều 8 khoản 1, 2; thông tin cần được sự đồng ý của cấp quản lí theo thẩm quyền); gợi ý ông bà giữ liên lạc, đặt giờ dùng thiết bị, ghi nhận việc tốt của K.", "Bước 3 – Báo cáo, phối hợp nhà trường (0,3đ): báo ban giám hiệu, giáo viên bộ môn, tư vấn học đường; không che giấu việc học sinh vi phạm (TT 03/2026 Điều 4 khoản 6: không thờ ơ, né tránh, che giấu hành vi vi phạm của người học); xử lí kỉ luật nếu cần theo quy định (hiệu trưởng quyết định theo TT 15/2026 Điều 10 khoản 1 điểm d; hình thức cụ thể: đối chiếu văn bản gốc); chú ý việc vay tiền, khả năng bị lôi kéo – báo gia đình.", "Bước 4 – Giải pháp ở lớp và phòng máy (0,3đ): nhắc nội quy phòng máy, chỉ dùng máy khi có phép và giám sát; giao K nhiệm vụ tích cực phù hợp (hỗ trợ thiết bị, câu lạc bộ tin học); sinh hoạt lớp về an toàn và sử dụng Internet hợp lí; theo dõi tiến bộ.", "Căn cứ (0,3đ): Luật Nhà giáo 2025 Điều 9 khoản 2 điểm c, d (phát huy phẩm chất, năng lực người học, bảo vệ quyền, lợi ích hợp pháp của người học); Điều 26 khoản 2 TT 15/2026 (nhiệm vụ giáo viên chủ nhiệm: tổ chức hoạt động giáo dục lớp, phối hợp với cha mẹ); Luật Giáo dục Điều 89, 91 (nhà trường phối hợp gia đình, thông báo kết quả học tập, rèn luyện cho cha mẹ – số khoản đối chiếu văn bản gốc); NQ 71-NQ/TW (phối hợp gia đình – nhà trường – xã hội)."]}]}, {"de": 11, "focus_luat": ["L2", "L4", "L6", "L8"], "focus_bai": ["B11", "B17", "B4"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Giáo dục 2019 (Điều 22), kể các hành vi bị nghiêm cấm trong cơ sở giáo dục. Việc ép buộc học sinh học thêm được quy định ở Luật Giáo dục và Luật Nhà giáo 2025 khác nhau như thế nào?", "a": ["**Điều 22 Luật Giáo dục 2019 – 6 hành vi bị nghiêm cấm (0,5đ, đúng 5/6 ý vẫn cho đủ):**", "- Xúc phạm nhân phẩm, danh dự, xâm phạm thân thể nhà giáo, cán bộ, người lao động và người học.", "- Xuyên tạc nội dung giáo dục.", "- Gian lận trong học tập, kiểm tra, thi, tuyển sinh.", "- Hút thuốc; uống rượu, bia; gây rối an ninh, trật tự.", "- Ép buộc học sinh học thêm để thu tiền.", "- Lợi dụng việc tài trợ, ủng hộ giáo dục để ép buộc đóng góp tiền hoặc hiện vật.", "**Điểm khác (0,25đ):** Luật Giáo dục (Điều 22) chỉ cấm \"ép buộc học sinh học thêm để thu tiền\"; Luật Nhà giáo 2025 (Điều 11 khoản 2 điểm c) cấm nhà giáo \"ép buộc người học tham gia học thêm dưới mọi hình thức\" (phạm vi rộng hơn, không cần có thu tiền)."]}, {"q": "Câu 2 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) thi tuyển nhà giáo gồm mấy vòng, vòng 1 thi gì (số câu, thời gian)? (b) Vòng 2 có những hình thức nào, thang điểm bao nhiêu? (c) Ai được cộng 5 điểm ưu tiên, cộng vào đâu?", "a": ["**(a) (0,25đ)** Thi tuyển 02 vòng (Điều 7). Vòng 1: trắc nghiệm trên máy vi tính; Phần I kiến thức chung 60 câu/60 phút; Phần II ngoại ngữ 30 câu/30 phút (không yêu cầu ngoại ngữ trong bản mô tả công việc thì không thi Phần II). Đúng từ 50% số câu của từng phần mới được thi vòng 2.", "**(b) (0,25đ)** Vòng 2 đánh giá năng lực qua thực hành sư phạm; người đứng đầu chọn 1 trong 3 hình thức: vấn đáp, thực hành giảng dạy hoặc thi viết. Vấn đáp 30 phút (chuẩn bị không quá 15 phút); thi viết 180 phút (không kể chép đề); thang điểm 100 (Điều 7 khoản 2).", "**(c) (0,25đ)** Điều 6: (1) người có thời gian giảng dạy, giáo dục đúng vị trí việc làm cần tuyển từ đủ 03 năm (36 tháng) trở lên, có đóng BHXH bắt buộc; (2) người có chứng chỉ kỹ năng nghề quốc gia bậc 4 trở lên hoặc kinh nghiệm thực tế phù hợp từ đủ 03 năm, có đóng BHXH. Cộng 05 điểm vào kết quả VÒNG 2; thuộc nhiều diện chỉ cộng điểm cao nhất (Điều 6 khoản 4)."]}, {"q": "Câu 3 (0,75đ). Theo Nghị quyết 248/2025/QH15, ai có thẩm quyền tuyển dụng nhà giáo cơ sở giáo dục phổ thông công lập và ai có thẩm quyền điều động, thuyên chuyển nhà giáo thuộc thẩm quyền quản lý? Nêu mức phụ cấp ưu đãi nghề tối thiểu đối với giáo viên.", "a": ["**Thẩm quyền tuyển dụng (0,25đ):** Giám đốc Sở Giáo dục và Đào tạo có thẩm quyền tuyển dụng, tiếp nhận nhà giáo, cán bộ quản lý, nhân viên cơ sở giáo dục mầm non, phổ thông, thường xuyên... công lập trên địa bàn tỉnh (Điều 2 khoản 1 điểm a); việc điều động, thuyên chuyển liên quan từ 02 đơn vị hành chính cấp xã trở lên cũng do Giám đốc Sở.", "**Điều động, thuyên chuyển (0,25đ):** Chủ tịch UBND cấp xã có thẩm quyền điều động, thuyên chuyển, biệt phái, bổ nhiệm, miễn nhiệm, thay đổi vị trí việc làm đối với nhà giáo, cán bộ quản lý, nhân viên thuộc thẩm quyền quản lý (Điều 2 khoản 1 điểm b).", "**Phụ cấp ưu đãi nghề (0,25đ):** theo lộ trình do Chính phủ quy định, cơ sở mầm non, phổ thông công lập tối thiểu 70% đối với giáo viên, tối thiểu 30% đối với nhân viên; 100% đối với giáo viên công tác ở biên giới, hải đảo, vùng đồng bào dân tộc thiểu số và miền núi, vùng đặc biệt khó khăn (Điều 2 khoản 2 điểm a).", "(Ghi chú: NQ 248 có hiệu lực từ 01/01/2026, Điều 9 khoản 1.)"]}, {"q": "Câu 4 (0,75đ). Nghị quyết 71-NQ/TW (22/8/2025) đặt các mục tiêu đến năm 2030 về giáo dục phổ thông như thế nào? Nêu tỉ lệ chi ngân sách nhà nước cho giáo dục và đào tạo mà Nghị quyết yêu cầu.", "a": ["**Mục tiêu đến 2030 (0,5đ, nêu đúng 3 ý chính):**", "- Ít nhất 80% trường phổ thông đạt chuẩn quốc gia.", "- Hoàn thành phổ cập giáo dục mầm non cho trẻ 3 đến 5 tuổi và giáo dục bắt buộc hết trung học cơ sở.", "- Ít nhất 85% người trong độ tuổi hoàn thành THPT và tương đương, không tỉnh nào dưới 60%.", "- Bước đầu nâng năng lực công nghệ, trí tuệ nhân tạo và tiếng Anh ở phổ thông.", "**Chi ngân sách (0,25đ):** tối thiểu 20% tổng chi NSNN cho giáo dục và đào tạo; trong đó chi đầu tư ít nhất 5% và chi cho giáo dục đại học ít nhất 3%.", "(Nghị quyết do Bộ Chính trị ban hành; ký: Tổng Bí thư Tô Lâm.)"]}], "p2": [{"q": "Câu 1 (1,0đ). [Tin 8 – Bài 2: Thông tin trong môi trường số] Nêu các đặc điểm của thông tin số. Kể 3 dạng thông tin không đáng tin cậy và 4 cách xác định thông tin đáng tin cậy.", "a": ["**Đặc điểm của thông tin số (0,4đ):** dễ nhân bản, lan truyền; khó xoá bỏ hoàn toàn; có thể truy cập từ xa; dễ chỉnh sửa.", "- Thông tin số trong xã hội (bổ sung, không bắt buộc): đa dạng, thu thập nhanh; lưu trữ dung lượng lớn; có công cụ tìm kiếm, chuyển đổi, xử lí; có bản quyền; độ tin cậy khác nhau.", "**3 dạng thông tin không đáng tin cậy (0,3đ):** không trung thực, lừa dối; đồn thổi; kết luận thiếu căn cứ.", "**4 cách xác định thông tin đáng tin cậy (0,3đ):** xác định nguồn tin; phân biệt ý kiến với sự kiện; kiểm tra chứng cứ; đánh giá tính thời sự.", "Lưu ý kiến thức hay nhầm: xoá ảnh trên máy không có nghĩa thông tin biến mất (bản gửi đi vẫn còn); ý kiến kém tin cậy hơn sự kiện; blog thường có độ tin cậy thấp."]}, {"q": "Câu 2 (1,5đ). [Tin 8 – Bài 13: Biểu diễn dữ liệu] Trong Scratch, các biến có giá trị: r = 7; n = 18; ten = \"Tin\"; lop = 8. Hãy xác định giá trị và kiểu kết quả (số, xâu kí tự hay lôgic) của các biểu thức:\n a) 2 × 3.14 × r\n b) 3.14 × r × r\n c) n chia lấy dư 5\n d) (n chia lấy dư 2) = 0\n e) kết hợp(ten, lop)\n f) (r > 3) và (n < 10)\n g) 360 / n\nChương trình vẽ đa giác đều n cạnh dùng khối lệnh \"quay 360 / n độ\": hãy chỉ rõ đâu là hằng, đâu là biến, đâu là biểu thức.", "a": ["**Mỗi ý a–g đúng giá trị và kiểu: 0,15đ (tổng 1,05đ):**", "- a) 43.96 – kiểu số.", "- b) 153.86 – kiểu số.", "- c) 18 chia lấy dư 5 = 3 – kiểu số.", "- d) 18 chia lấy dư 2 = 0, so sánh 0 = 0 là đúng: true – kiểu lôgic.", "- e) \"Tin8\" – kiểu xâu kí tự (phép kết hợp luôn cho xâu, không tự thêm khoảng trắng).", "- f) (7 > 3) = true; (18 < 10) = false; true và false = false – kiểu lôgic.", "- g) 360 / 18 = 20 – kiểu số.", "**Hằng, biến, biểu thức (0,45đ):** hằng là giá trị không đổi: 360 (và 3.14); biến có tên, giá trị thay đổi khi chạy: n; biểu thức kết hợp hằng, biến và phép toán: 360 / n.", "Cách làm: kiểu kết quả do phép toán cuối cùng quyết định (so sánh, và, hoặc cho kết quả lôgic; kết hợp cho xâu)."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 6: Làm quen với phần mềm bảng tính] Thiết kế hoạt động hình thành kiến thức mục \"Địa chỉ ô và địa chỉ vùng\" (khoảng 13 phút) với bảng tính khảo sát 200 cây xanh trường học: nêu mục tiêu của hoạt động, sản phẩm học tập và tổ chức thực hiện theo 4 bước chuyển giao – thực hiện – báo cáo – kết luận.", "a": ["**Mục tiêu (0,3đ):** HS nêu quy tắc địa chỉ ô = <tên cột><tên hàng> và địa chỉ vùng = <ô trên trái>:<ô dưới phải>; viết đúng địa chỉ; góp phần NLa (sử dụng giao diện bảng tính), năng lực chung tự chủ và tự học, giao tiếp và hợp tác; phẩm chất chăm chỉ, trách nhiệm.", "**Sản phẩm:** phiếu học tập điền đúng: ô giao cột C hàng 5 là C5; vùng 3 cột × 4 hàng từ A1 là A1:C4; vùng A5:B10 có 12 ô.", "**Bước 1 – Chuyển giao (0,3đ):** GV chiếu trang tính khảo sát; giao nhiệm vụ: viết địa chỉ ô được tô màu, địa chỉ vùng được bao khung; nêu thời gian 5 phút, làm cá nhân rồi trao đổi cặp đôi.", "**Bước 2 – Thực hiện (0,3đ):** HS làm theo Think – Pair – Share; GV đi quan sát, gợi ý \"cột trước, hàng sau\"; chú ý lỗi hay gặp: nhầm hàng ghi tên cột (chữ) với cột ghi tên hàng (số), viết ngược 3B.", "**Bước 3 – Báo cáo, thảo luận (0,3đ):** 2 cặp trình bày, bạn khác nhận xét; cả lớp giơ thẻ A–D với 3 câu trắc nghiệm nhanh.", "**Bước 4 – Kết luận, đánh giá (0,3đ):** GV chốt quy tắc (ví dụ B3, A1:C4), nêu lại lỗi thường gặp; đánh giá bằng quan sát và thẻ; ghi nhớ trong SGK."]}, {"q": "Câu 4 (1,0đ). [Năng lực AI – Tin 7 Bài 6] Khi hỏi chatbot \"Vùng C3:F8 trong bảng tính có bao nhiêu ô?\", chatbot trả lời \"18 ô\". Em hãy kiểm tra kết quả, nêu cách tổ chức cho học sinh kiểm chứng và những điều giáo viên cần giáo dục học sinh về dùng AI.", "a": ["**Kiểm tra (0,3đ):** cột C đến F là 4 cột; hàng 3 đến 8 là 6 hàng; 4 × 6 = **24 ô**. Chatbot sai (18 = 3 × 6, quên tính cột đầu).", "**Cách kiểm chứng (0,3đ):** đối chiếu quy tắc địa chỉ vùng trong SGK; chọn thử vùng C3:F8 trên bảng tính và đếm; trao đổi với bạn, thầy cô trước khi tin.", "**Giáo dục về AI (0,2đ):** AI có thể sai nhưng trình bày rất thuyết phục; người dùng chịu trách nhiệm về kết quả; khi dùng AI phải khai báo; không sao chép nguyên văn.", "**An toàn thông tin (0,2đ):** không nhập thông tin cá nhân của học sinh (họ tên, điểm số thật, ảnh) vào chatbot.", "(Mã năng lực AI tham chiếu trong KHDH: 7.A1.2, 7.A1.MR1.)"]}], "p3": [{"q": "Tình huống (2,0đ). Em Hạ (lớp 8A) phát hiện ảnh khuôn mặt của mình bị một số học sinh lớp khác dùng ứng dụng AI ghép vào ảnh phản cảm, lan truyền trong nhóm Zalo của khối 8. Hạ khóc, sợ đến lớp và xin nghỉ học. Anh/chị là giáo viên chủ nhiệm lớp 8A đồng thời là giáo viên Tin học. Hãy nêu cách xử lí và căn cứ.", "a": ["**Bảo vệ và ổn định tâm lí học sinh (0,4đ):** gặp riêng Hạ, lắng nghe, trấn an; không để em một mình; đề nghị hỗ trợ tư vấn tâm lí học đường (học sinh có quyền được hỗ trợ tư vấn tâm lí – Điều 33 khoản 6 TT 15/2026).", "**Báo cáo kịp thời (0,4đ):** báo hiệu trưởng ngay; không né tránh, che giấu (TT 03/2026: Điều 5 khoản 4 – phải báo cáo kịp thời khi phát hiện người học bị bạo lực, xâm hại; Điều 4 khoản 6 – không thờ ơ, né tránh).", "**Ngăn chặn lan truyền (0,3đ):** lưu bằng chứng (ảnh chụp màn hình, tên nhóm), yêu cầu quản trị nhóm và học sinh xoá, ngừng chia sẻ; hướng dẫn gửi báo cáo gỡ bỏ nội dung trên nền tảng.", "**Xác minh, xử lí học sinh vi phạm (0,4đ):** làm việc riêng từng em, giữ bí mật thông tin; giáo dục là chính; xem xét kỉ luật theo quy định (hiệu trưởng quyết định khen thưởng, kỉ luật học sinh – Điều 10 khoản 1 điểm d TT 15/2026); căn cứ vi phạm: học sinh không được phát tán thông tin nói xấu, xúc phạm bạn (TT 06/2019 Điều 8 khoản 2); hành vi xúc phạm nhân phẩm, danh dự người học là hành vi bị nghiêm cấm (Điều 22 Luật Giáo dục).", "**Phối hợp gia đình (0,3đ):** mời cha mẹ Hạ và cha mẹ các em vi phạm trao đổi trung thực, đúng chừng mực, không công khai danh tính trái quy định (TT 03/2026 Điều 5 khoản 4, Điều 8 khoản 2).", "**Phòng ngừa (0,2đ):** là giáo viên Tin học, tổ chức chuyên đề ứng xử trên mạng, nhận biết ảnh giả do AI, quyền riêng tư, chấm dứt bạo lực học đường (NQ 71-NQ/TW).", "(Xử phạt hành chính/trách nhiệm pháp lí khác với hành vi dùng AI ghép ảnh: đối chiếu văn bản gốc.)"]}]}, {"de": 12, "focus_luat": ["L3", "L5", "L7", "L9"], "focus_bai": ["B12", "B18", "B5"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Nhà giáo 2025, quyền, nghĩa vụ, đạo đức nhà giáo và những việc nhà giáo không được làm quy định ở các điều nào? Nêu 5 việc nhà giáo không được làm đối với người học.", "a": ["**Căn cứ điều (0,25đ):** quyền – Điều 8; nghĩa vụ – Điều 9; đạo đức nhà giáo – Điều 10 (Bộ trưởng Bộ GDĐT ban hành quy tắc ứng xử); những việc không được làm – Điều 11. (Hay nhầm: không phải Điều 9–10.)", "**5 việc không được làm (Điều 11 khoản 2) (0,5đ):**", "- Phân biệt đối xử giữa những người học dưới mọi hình thức.", "- Gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học.", "- Ép buộc người học tham gia học thêm dưới mọi hình thức.", "- Ép buộc người học nộp tiền hoặc hiện vật ngoài quy định của pháp luật.", "- Lợi dụng chức danh nhà giáo và hoạt động nghề nghiệp để thực hiện hành vi vi phạm pháp luật.", "(Nhà giáo công lập còn không được làm những việc viên chức không được làm – Điều 11 khoản 1.)"]}, {"q": "Câu 2 (0,75đ). Theo Nghị định 259/2026/NĐ-CP, (a) vòng 1 thi tuyển viên chức gồm những phần nào, điều kiện để dự vòng 2? (b) Vòng 2 có những hình thức nào? (c) Thí sinh A thi vòng 2 theo hình thức kết hợp viết và phỏng vấn, được 80 điểm bài viết, 60 điểm phỏng vấn, thuộc diện ưu tiên 5 điểm. Thí sinh B được 45 điểm bài viết, 90 điểm phỏng vấn. Tính điểm vòng 2 của mỗi thí sinh và cho biết ai đủ điều kiện xét trúng tuyển.", "a": ["**(a) (0,25đ)** Vòng 1 trắc nghiệm trên máy tính: kiến thức chung 60 câu/60 phút; ngoại ngữ theo thông báo tuyển dụng (tối đa 60 phút; có văn bằng, chứng chỉ phù hợp thì được miễn). Trả lời đúng từ 50% số câu của TỪNG phần mới được dự vòng 2 (Điều 11 khoản 1).", "**(b) (0,1đ)** Vòng 2 – môn nghiệp vụ chuyên ngành: chọn 1 trong 2 hình thức: thực hành; hoặc kết hợp viết và phỏng vấn (Điều 11 khoản 2).", "**(c) (0,4đ)** Kết hợp viết và phỏng vấn: quy đổi thang 100 theo tỉ lệ viết 70%, phỏng vấn 30%.", "- A: 0,7 × 80 + 0,3 × 60 = 56 + 18 = **74 điểm**; cộng ưu tiên 5 điểm vào kết quả vòng 2: 74 + 5 = **79 điểm** (Điều 8, Điều 12). Hai bài đều trên 50 điểm nên **đủ điều kiện**.", "- B: 0,7 × 45 + 0,3 × 90 = 31,5 + 27 = 58,5 điểm; nhưng bài viết 45 < 50 (dưới 50% điểm tối đa) nên **không đủ điều kiện** trúng tuyển (Điều 12 khoản 1 điểm a: phải dự đủ 2 bài, mỗi bài đạt từ 50% điểm tối đa).", "(Thứ tự quy đổi và cộng điểm ưu tiên khi xếp hạng: đối chiếu văn bản gốc. Vị trí giáo viên áp dụng thêm Nghị định 93/2026.)"]}, {"q": "Câu 3 (0,75đ). Theo Thông tư 03/2026/TT-BGDĐT, nhà giáo ứng xử với cha mẹ hoặc người giám hộ của người học như thế nào (Điều 8)? Nêu điều kiện khi cung cấp thông tin và những điều không được làm.", "a": ["**Điều 8 – ứng xử với cha mẹ/người giám hộ (0,25đ):** sẵn sàng hợp tác, hỗ trợ, chia sẻ về hoạt động giảng dạy, giáo dục vì sự tiến bộ của người học; khuyến khích, tạo điều kiện để cha mẹ tham gia hoạt động giáo dục.", "**Điều kiện cung cấp thông tin (0,25đ):** chủ động, kịp thời cung cấp, trao đổi thông tin TRUNG THỰC về người học; chương trình, kế hoạch giảng dạy, giáo dục khi được sự đồng ý của cấp quản lý theo thẩm quyền.", "**Không được làm (0,25đ):** xúc phạm, áp đặt, vụ lợi, ép buộc cha mẹ tham gia hoạt động trái quy định của Nhà nước và các hoạt động mang tính chất tự nguyện.", "(Ghi nhớ: quy tắc ứng xử có 6 nhóm ở Điều 4–9: chung, người học, đồng nghiệp, cán bộ quản lý, cha mẹ/người giám hộ, cộng đồng.)"]}, {"q": "Câu 4 (0,75đ). Theo Điều lệ trường phổ thông (Thông tư 15/2026/TT-BGDĐT): (a) tổ chuyên môn do ai bổ nhiệm tổ trưởng, khi nào có tổ phó, sinh hoạt tối thiểu bao lâu một lần? (b) Sĩ số tối đa của lớp THCS? Ai quy định cụ thể? (c) Nhiệm kì hiệu trưởng trường công lập và giới hạn số nhiệm kì liên tiếp?", "a": ["**(a) (0,3đ)** Hiệu trưởng bổ nhiệm tổ trưởng, tổ phó; tổ có từ 07 thành viên trở lên thì có tổ phó; sinh hoạt chuyên môn ít nhất 01 lần trong 02 tuần (Điều 13).", "**(b) (0,25đ)** Mỗi lớp THCS và THPT không quá 45 học sinh (tiểu học không quá 35); Chủ tịch UBND cấp tỉnh quy định cụ thể theo hướng giảm sĩ số (Điều 16 khoản 3).", "**(c) (0,2đ)** Nhiệm kì hiệu trưởng 05 năm; giữ chức vụ tại một trường công lập không quá hai nhiệm kì liên tiếp (vùng sâu, vùng xa, đặc biệt khó khăn do cấp bổ nhiệm xem xét) (Điều 10 khoản 1 điểm c).", "(Thông tư 15/2026 hiệu lực từ 10/5/2026; trường THCS do UBND cấp xã quản lý – Điều 6.)"]}], "p2": [{"q": "Câu 1 (1,0đ). [Tin 8 – Bài 4: Đạo đức và văn hoá trong sử dụng công nghệ kĩ thuật số] Phân biệt biểu hiện vi phạm đạo đức, vi phạm pháp luật và thiếu văn hoá khi dùng công nghệ số (mỗi loại cho 1 ví dụ). Nêu 3 điều cần lưu ý khi dùng sản phẩm số của người khác và 4 yêu cầu đối với sản phẩm số do em tạo ra.", "a": ["**Phân biệt (0,4đ, mỗi loại 0,13đ; ví dụ minh hoạ):**", "- Vi phạm pháp luật: dùng phần mềm bẻ khoá, xem web phim không bản quyền, phát tán thông tin sai sự thật (vi phạm bản quyền, có thể bị xử phạt).", "- Vi phạm đạo đức: tự ý sửa, đăng ảnh của bạn khi chưa xin phép (xâm phạm quyền riêng tư); chép bài của người khác nhận là của mình.", "- Thiếu văn hoá: dùng ngôn từ thô tục, bình luận miệt thị trên mạng xã hội (chưa chắc vi phạm pháp luật).", "**3 điều lưu ý (0,3đ):** (1) tìm hiểu quy định về sử dụng sản phẩm; (2) chỉ dùng khi được phép; (3) hầu hết thông tin trên Internet có bản quyền – xin phép, ghi nguồn.", "**4 yêu cầu với sản phẩm số (0,3đ):** trung thực; tự tạo nội dung; có đạo đức, văn hoá; không vi phạm pháp luật.", "Lưu ý: sửa ảnh người khác vẫn phải xin phép và ghi nguồn."]}, {"q": "Câu 2 (1,5đ). [Tin 8 – Bài 14: Cấu trúc điều khiển] Cho thuật toán:\n B1. tong ← 0; i ← 1.\n B2. Lặp lại cho đến khi i > 10:\n   B2.1. Nếu (i chia lấy dư 2) = 1 thì tong ← tong + i.\n   B2.2. i ← i + 1.\n B3. Thông báo tong.\na) Chỉ ra các cấu trúc điều khiển có trong thuật toán và loại của từng cấu trúc.\nb) Lập bảng theo dõi giá trị i và tong sau mỗi lần lặp, cho biết kết quả và số lần lặp.\nc) Nếu đổi điều kiện dừng thành i > 7 thì kết quả là bao nhiêu? Sửa B2.1 thành \"Nếu i chia hết cho 2 thì tongchan ← tongchan + i, nếu không thì tongle ← tongle + i\" (cả hai tổng bắt đầu bằng 0, dừng khi i > 10): cho biết hai kết quả và gọi tên loại rẽ nhánh.", "a": ["**a) (0,4đ):** tuần tự (B1 → B2 → B3 thực hiện lần lượt); lặp đến khi điều kiện đúng (i > 10) ở B2; rẽ nhánh khuyết (\"Nếu … thì …\", không có nhánh còn lại) ở B2.1.", "**b) (0,6đ) Bảng (i trước khi cộng → tong sau lần lặp):** i=1 → 1; i=2 → 1; i=3 → 4; i=4 → 4; i=5 → 9; i=6 → 9; i=7 → 16; i=8 → 16; i=9 → 25; i=10 → 25. Sau lần lặp thứ 10, i = 11 > 10 nên dừng.", "- Kết quả **tong = 25** (tổng các số lẻ 1 + 3 + 5 + 7 + 9); lặp **10 lần**; nhánh \"đúng\" thực hiện 5 lần.", "**c) (0,5đ):** dừng khi i > 7 (lặp 7 lần): tong = 1 + 3 + 5 + 7 = **16**.", "- Phiên bản sửa: tongchan = 2 + 4 + 6 + 8 + 10 = **30**; tongle = 1 + 3 + 5 + 7 + 9 = **25**; đây là cấu trúc **rẽ nhánh đầy đủ** (có cả nhánh \"nếu không thì\").", "Lưu ý hay nhầm: rẽ nhánh khuyết với đầy đủ; lặp có điều kiện kết thúc với lặp vô hạn."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 7: Tính toán tự động trên bảng tính] Đề xuất phương pháp và kĩ thuật dạy học phù hợp cho nội dung \"Sao chép công thức\" (bảng diện tích rừng: D4 = B4 + C4, sao chép cho D5:D8; lớp 40 học sinh, phòng máy 20 máy). Nêu cách thực hiện, vì sao chọn và những lỗi thường gặp cần lưu ý.", "a": ["**Phương pháp (0,4đ):** dạy học nêu và giải quyết vấn đề (mở đầu: tính tổng số cây của các lớp, nhập phép tính được không?); dạy học hợp tác, thực hành trực quan trên máy (2 HS/máy).", "**Kĩ thuật (0,5đ):**", "- Think – Pair – Share: HS dự đoán công thức ở D5 khi sao chép từ D4 rồi trao đổi cặp đôi.", "- Mảnh ghép hoặc khăn trải bàn: nhóm chuyên gia tìm hiểu 3 việc (gõ công thức bắt đầu bằng =, sao chép bằng Ctrl+C/Ctrl+V, quan sát công thức ô mới), rồi chia sẻ ở nhóm ghép.", "- Tia chớp/giơ thẻ: kiểm tra nhanh E5 sau khi sao chép E4 = C4*D4 là gì (E5 = C5*D5).", "**Vì sao chọn (0,3đ):** phòng máy ít máy nên làm cặp; hợp tác giúp HS yếu theo kịp; trực quan, tự quan sát địa chỉ tương đối đổi theo vị trí; phù hợp năng lực NLa, NLc và năng lực chung giao tiếp – hợp tác.", "**Lỗi thường gặp (0,3đ):** quên dấu =; gõ số thay vì địa chỉ ô nên sửa ô gốc kết quả không tự cập nhật; nhầm dấu × với *; sao chép sai vùng đích."]}, {"q": "Câu 4 (1,0đ). [Tích hợp liên môn và năng lực AI – Tin 8 Bài 4] Một học sinh nộp bài thuyết trình \"An toàn trên mạng\" do chatbot viết toàn bộ, dán nguyên văn, không nêu nguồn và không khai báo. Em xử lí tình huống sư phạm này như thế nào để giáo dục đúng chuẩn mực số? Đề xuất 1 hoạt động tích hợp với môn Giáo dục công dân hoặc Ngữ văn.", "a": ["**Đối chiếu với 4 yêu cầu sản phẩm số (0,3đ):** vi phạm \"trung thực\" và \"tự tạo nội dung\"; chưa khai báo khi dùng AI.", "**Cách xử lí (0,4đ):** trao đổi riêng, không công khai làm xấu hổ; yêu cầu HS đọc lại, kiểm chứng thông tin bằng nguồn tin cậy (SGK, trang chính thống); làm lại bằng lời của em, chỉ dùng AI để gợi ý và có câu khai báo; AI không chịu trách nhiệm, người dùng chịu trách nhiệm; nêu tiêu chí đánh giá rõ ràng cho lần sau.", "**Tích hợp liên môn (0,3đ):** ví dụ phối hợp Giáo dục công dân (quyền tác giả, trung thực) hoặc Ngữ văn (viết đoạn văn thuyết phục về quy tắc ứng xử trên mạng); sản phẩm: áp phích/khẩu hiệu nhắc bạn dùng công nghệ số đúng chuẩn mực.", "(Mã năng lực AI tham chiếu: 8.A3.3.)"]}], "p3": [{"q": "Tình huống (2,0đ). Cuối học kì, hiệu trưởng nhắn riêng cho thầy/cô, yêu cầu \"điều chỉnh điểm kiểm tra giữa kì\" của 6 học sinh lớp 8B lên mức Khá để lớp đạt danh hiệu thi đua, đồng thời nói \"việc này không ai biết, cứ làm theo chỉ đạo\". Thầy/cô là giáo viên dạy Tin học lớp 8B. Hãy nêu cách xử lí và căn cứ.", "a": ["**Nhận diện đúng (0,3đ):** sửa điểm để đạt thi đua là gian lận, làm sai lệch kết quả đánh giá người học – trái pháp luật.", "**Căn cứ (0,6đ):**", "- Luật Nhà giáo Điều 11 khoản 2 điểm b: nhà giáo không được gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học; Điều 9 khoản 2: bảo đảm liêm chính, đối xử công bằng với người học.", "- TT 03/2026 Điều 5 khoản 3, 4: đánh giá đúng thực chất năng lực, không gian lận, làm sai lệch kết quả đánh giá.", "- Luật Viên chức 2025 Điều 11 (quyền từ chối thực hiện công việc nếu cho rằng trái pháp luật – khoản 6) và Điều 8 khoản 2 (báo cáo người có thẩm quyền khi phát hiện vi phạm pháp luật trong đơn vị).", "- TT 15/2026 Điều 22: đánh giá trung thực, khách quan, không gây áp lực cho học sinh, giáo viên.", "**Cách ứng xử (0,7đ):** không thực hiện; trao đổi lại với hiệu trưởng một cách lễ phép, nêu rõ căn cứ, đề xuất giải pháp hợp lệ (ôn tập, kiểm tra lại cho học sinh có nhu cầu theo quy chế); lưu giữ tin nhắn; nếu vẫn bị ép, báo cáo bằng văn bản lên cấp quản lí trực tiếp (UBND cấp xã/Sở GDĐT) hoặc cơ quan có thẩm quyền; giữ nguyên bảng điểm đã lập.", "**Vừa đúng quy tắc, vừa giữ đoàn kết (0,2đ):** TT 03/2026 Điều 7 – chấp hành phân công trong phạm vi chức năng, nhiệm vụ, nhưng được tham mưu và thể hiện chính kiến đúng kênh; không xúc phạm, không đăng lên mạng xã hội.", "**Không được làm (0,2đ):** làm theo vì sợ bị trù dập; che giấu vi phạm (TT 03/2026 Điều 4 khoản 6 – không thờ ơ, né tránh, che giấu).", "(Chế tài cụ thể đối với người ra lệnh gian lận: đối chiếu văn bản gốc.)"]}]}, {"de": 13, "focus_luat": ["L4", "L6", "L8", "L1"], "focus_bai": ["B13", "B19", "B6"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) giáo viên trung học cơ sở có chia hạng không? (b) Thời gian nghỉ hè của giáo viên THCS là bao lâu, ai quyết định thời điểm nghỉ hè? (c) Giáo viên được phân công dạy liên trường thì số tiết tính theo chế độ làm việc như thế nào, ai chi trả lương?", "a": ["**(a) (0,25đ)** Không. \"Giáo viên trung học cơ sở\" là một chức danh, không chia hạng I, II, III (Điều 3 khoản 1); chỉ chức danh giảng viên mới có phân cấp.", "**(b) (0,25đ)** 08 tuần/năm, bao gồm cả nghỉ phép hằng năm, hưởng nguyên lương và phụ cấp (Điều 17 khoản 1 điểm a, g); Chủ tịch UBND cấp tỉnh quyết định thời điểm nghỉ hè theo kế hoạch năm học của Bộ GDĐT (Điều 17 khoản 3).", "**(c) (0,25đ)** Số tiết theo chế độ làm việc là TỔNG số tiết ở các cơ sở được phân công (Điều 13 khoản 3 điểm a); lương và chế độ theo lương do cơ sở QUẢN LÝ nhà giáo chi trả (khoản 3 điểm c); việc phân công do UBND cấp xã/Sở GDĐT ra quyết định (khoản 2)."]}, {"q": "Câu 2 (0,75đ). Theo Nghị quyết 248/2025/QH15, từ năm học nào thực hiện một bộ sách giáo khoa thống nhất toàn quốc, đến năm nào hoàn thành cung cấp sách giáo khoa miễn phí? Nêu tỉ lệ chi ngân sách tối thiểu cho giáo dục và cách xử lí chuyển tiếp khi hội đồng trường công lập chấm dứt hoạt động.", "a": ["**SGK (0,25đ):** Bộ trưởng Bộ GDĐT quyết định một bộ SGK giáo dục phổ thông dùng thống nhất toàn quốc, thực hiện từ năm học 2026–2027; đến năm 2030 hoàn thành cung cấp miễn phí SGK cho học sinh (Điều 3 khoản 1).", "**Ngân sách (0,2đ):** bố trí tối thiểu 20% tổng chi NSNN cho giáo dục và đào tạo (Điều 6 khoản 4).", "**Chuyển tiếp hội đồng trường (0,3đ):** trong 06 tháng sau khi hội đồng trường chấm dứt, cơ quan quản lí trực tiếp quyết định công việc tổ chức, nhân sự do hội đồng trường đảm nhiệm và quyết định người đứng đầu; số cấp phó được vượt mức tối đa trong 05 năm và phải lập kế hoạch giảm dần (Điều 7).", "(Kết hợp Luật 123/2025: từ 01/01/2026 hội đồng trường các cơ sở phổ thông công lập kết thúc hoạt động, bàn giao hồ sơ cho hiệu trưởng. Số khoản Điều 6, 7: đối chiếu văn bản gốc.)"]}, {"q": "Câu 3 (0,75đ). Nghị quyết 71-NQ/TW nêu phương châm nào về thầy – trò? Nêu vị trí của người học, nhà trường, nhà giáo. Kể 3 nhiệm vụ, giải pháp có liên quan đến môn Tin học và chuyển đổi số trong giáo dục phổ thông.", "a": ["**Phương châm (0,15đ):** \"Thầy ra thầy, trò ra trò\".", "**Vị trí (0,2đ):** người học là trung tâm, chủ thể; nhà trường là nền tảng; nhà giáo là động lực, quyết định chất lượng giáo dục.", "**3 nhiệm vụ, giải pháp (0,4đ):**", "- Chuyển đổi số, AI: xây dựng nền tảng giáo dục quốc gia ứng dụng AI có kiểm soát; nâng chuẩn năng lực số và AI cho người học và nhà giáo.", "- Tăng thời lượng khoa học, công nghệ, tin học, nghệ thuật; nghiên cứu đưa năng lực số, AI vào chương trình phổ thông; STEM/STEAM.", "- Đưa tiếng Anh từng bước thành ngôn ngữ thứ hai trong trường học; khắc phục dạy thêm, học thêm tràn lan.", "(Ngoài ra: một bộ SGK thống nhất, phấn đấu 2030 miễn phí SGK.)"]}, {"q": "Câu 4 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) nêu các hình thức kỉ luật viên chức, hình thức nào chỉ áp dụng với viên chức quản lí? (b) Thời hiệu và thời hạn xử lí kỉ luật? (c) Trường hợp nào đương nhiên bị buộc thôi việc?", "a": ["**(a) (0,25đ)** 4 hình thức: khiển trách; cảnh cáo; cách chức (áp dụng đối với viên chức quản lí); buộc thôi việc (Điều 35 khoản 1).", "**(b) (0,3đ)** Thời hiệu 05 năm (khiển trách) và 10 năm (các hình thức còn lại) – Điều 36 khoản 1; thời hạn xử lí kỉ luật không quá 90 ngày, vụ việc phức tạp kéo dài không quá 150 ngày – Điều 36 khoản 3. Một số trường hợp không áp dụng thời hiệu, ví dụ dùng văn bằng, chứng chỉ giả (Điều 36 khoản 2).", "**(c) (0,2đ)** Bị Tòa án kết án phạt tù không được hưởng án treo hoặc bị kết án về tội tham nhũng thì đương nhiên bị buộc thôi việc kể từ ngày bản án có hiệu lực (Điều 35 khoản 3); viên chức quản lí phạm tội bị kết án đương nhiên thôi giữ chức vụ."]}], "p2": [{"q": "Câu 1 (1,0đ). [Tin 8 – Bài 5: Sử dụng bảng tính giải quyết bài toán thực tế] Phân biệt địa chỉ tương đối và địa chỉ tuyệt đối. Khi nào cần dùng địa chỉ tuyệt đối? Nêu cách tạo địa chỉ tuyệt đối. Ví dụ: ô G2 = E2*$F$1 được sao chép sang G3 thì công thức thế nào?", "a": ["**Địa chỉ tương đối (0,3đ):** địa chỉ thay đổi theo vị trí ô đích khi sao chép công thức (ví dụ =A1*B1 ở C1 sao chép xuống C2 thành =A2*B2).", "**Địa chỉ tuyệt đối (0,3đ):** có kí hiệu $ trước tên cột và số hàng (ví dụ $B$1); giữ nguyên khi sao chép.", "**Khi nào dùng (0,2đ):** khi công thức phải luôn tham chiếu một ô cố định (ví dụ tỉ lệ giảm giá, tỉ lệ 75%, đơn giá) trong bài toán doanh thu, giảm giá.", "**Cách tạo:** gõ dấu $ hoặc đặt con trỏ vào địa chỉ trong thanh công thức rồi nhấn phím **F4**; sau đó kéo núm điền.", "**Ví dụ (0,2đ):** G3 = E3*$F$1 (E đổi theo hàng, $F$1 giữ nguyên). Lỗi hay gặp: quên $ ở ô cố định nên kết quả sai khi kéo; gắn $ cho cả ô phải đổi theo dòng."]}, {"q": "Câu 2 (1,5đ). [Tin 8 – Bài 15: Gỡ lỗi] Chương trình sau dùng để tính tổng S = 1 + 2 + … + n:\n B1. tong ← 0; i ← 1.\n B2. Lặp n lần: i ← i + 1; tong ← tong + i.\n B3. Thông báo tong.\na) Tính kết quả chương trình cho n = 5 và kết quả đúng. Đây là lỗi cú pháp hay lỗi lôgic? Vì sao?\nb) Lập bảng 4 ca kiểm thử n = 0, 1, 5, 10: cho biết kết quả mong đợi, kết quả chương trình, ca nào phát hiện lỗi.\nc) Nêu 2 cách sửa và quy trình gỡ lỗi sau khi sửa.", "a": ["**a) (0,5đ):** chương trình cộng i sau khi tăng nên cộng 2, 3, 4, 5, 6: **tong = 20**; kết quả đúng 1 + 2 + 3 + 4 + 5 = **15**. Đây là **lỗi lôgic** (chương trình vẫn chạy, đúng quy tắc nhưng sai kịch bản), khó phát hiện hơn lỗi cú pháp.", "**b) (0,6đ) – Bảng ca kiểm thử:**", "- n = 0: mong đợi 0; chương trình 0 – không phát hiện lỗi (ca biên bỏ sót).", "- n = 1: mong đợi 1; chương trình 2 – phát hiện lỗi.", "- n = 5: mong đợi 15; chương trình 20 – phát hiện lỗi.", "- n = 10: mong đợi 55; chương trình 2 + 3 + … + 11 = 65 – phát hiện lỗi.", "**c) (0,4đ):** Cách 1: đặt i ← 0 ở B1. Cách 2: đổi thứ tự trong vòng lặp: tong ← tong + i trước, rồi i ← i + 1. (Một lỗi có nhiều cách sửa.)", "- Quy trình: chạy thử → so với kịch bản → tìm lệnh gây lỗi (phân tích lôgic hoặc theo dõi giá trị biến từng bước) → sửa → **chạy thử lại** với toàn bộ ca kiểm thử."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 8: Công cụ hỗ trợ tính toán] Xây dựng công cụ đánh giá (bảng tiêu chí 3 mức) cho hoạt động thực hành: dùng hàm SUM, AVERAGE, MAX, MIN, COUNT tính trên bảng điểm 5 học sinh. Nêu các hình thức đánh giá nên phối hợp và cách dùng kết quả đánh giá.", "a": ["**Bảng tiêu chí (0,8đ, 4 tiêu chí × 0,2đ; mỗi tiêu chí mô tả 3 mức Tốt / Đạt / Cần cố gắng):**", "- Công thức, cú pháp: Tốt – viết đúng dấu =, tên hàm, vùng ô cả 5 hàm; Đạt – đúng 3–4 hàm; Cần cố gắng – dưới 3 hàm hoặc quên dấu =.", "- Chọn đúng hàm cho yêu cầu (tổng, trung bình, lớn nhất, nhỏ nhất, đếm): Tốt – đúng cả 5; Đạt – sai 1; Cần cố gắng – sai từ 2 trở lên.", "- Chọn vùng ô và sao chép (kéo ô điền): Tốt – chọn vùng chính xác, sao chép đúng; Đạt – cần gợi ý 1 lần; Cần cố gắng – chọn sai vùng nhiều lần.", "- Hợp tác và kiểm tra kết quả: Tốt – tự kiểm tra lại bằng tính nhẩm; Đạt – kiểm tra khi được nhắc; Cần cố gắng – không kiểm tra.", "**Hình thức phối hợp (0,4đ):** GV quan sát, đánh giá thường xuyên bằng bảng kiểm; đánh giá đồng đẳng giữa các cặp; HS tự đánh giá; sản phẩm: tệp bảng điểm đã lưu.", "**Sử dụng kết quả (0,3đ):** phản hồi ngay, giúp HS sửa lỗi và chạy lại; điều chỉnh bài dạy, phân hóa bài tập; đánh giá vì sự tiến bộ, không so sánh học sinh này với học sinh khác (TT 15/2026 Điều 22).", "**Lưu ý (0,1đ):** công bố tiêu chí cho HS trước khi làm."]}, {"q": "Câu 4 (1,0đ). [Năng lực AI và an toàn thông tin – Tin 7 Bài 8] Bảng tính có vùng D4:D8 chứa: 4; 5; chữ \"vắng\"; 7; một ô trống. Một học sinh hỏi chatbot kết quả của =COUNT(D4:D8) và chatbot trả lời \"5\". (a) Tính đúng COUNT, SUM, AVERAGE của vùng. (b) Nêu cách hướng dẫn HS kiểm chứng, và (c) những điều cần dặn về an toàn thông tin khi dùng chatbot với bảng điểm.", "a": ["**(a) (0,4đ):** COUNT chỉ đếm ô chứa số: 4, 5, 7 → **3** (chatbot sai: nhầm COUNT với đếm mọi ô). SUM = 4 + 5 + 7 = **16** (bỏ qua chữ và ô trống). AVERAGE = 16 / 3 ≈ **5,33**.", "**(b) (0,3đ):** đối chiếu bảng 5 hàm trong SGK (COUNT đếm ô chứa số); chạy thử công thức trên máy; so sánh kết quả với kết quả chatbot, ghi nhận mức độ tin cậy; khai báo khi có dùng AI.", "**(c) (0,3đ):** không nhập bảng điểm thật, họ tên, mã học sinh hoặc thông tin cá nhân vào chatbot; dùng dữ liệu mẫu; không công khai thông tin của người học trái quy định (TT 03/2026 Điều 5 khoản 4).", "(Mã năng lực AI tham chiếu: 7.A1.2, 7.A1.MR1.)"]}], "p3": [{"q": "Tình huống (2,0đ). Phòng máy của trường có 40 máy nhưng chỉ còn 15 máy hoạt động. Tuần sau đoàn kiểm tra chuyên môn đến dự giờ. Hiệu trưởng nhắc thầy/cô giáo viên Tin học: \"cứ dạy bình thường, báo cáo là đủ tiết thực hành, đừng nói máy hỏng\". Có học sinh còn tranh thủ chơi game trên các máy còn chạy. Thầy/cô xử lí thế nào? Nêu căn cứ.", "a": ["**Nguyên tắc (0,3đ):** trung thực trong báo cáo; vẫn bảo đảm chất lượng dạy học bằng phương án phù hợp.", "**Giải pháp chuyên môn (0,6đ):** chia nhóm 2–3 học sinh/máy, luân phiên thực hành; kết hợp bài giảng trực quan, mô phỏng, hoạt động \"không cắm điện\" (phiếu học tập, sơ đồ khối) cho phần còn lại; điều chỉnh kế hoạch bài dạy, vẫn đạt yêu cầu cần đạt; GV được chủ động sắp xếp nội dung, lựa chọn học liệu theo chương trình (Luật Nhà giáo Điều 8 khoản 2 điểm a).", "**Quản lí học sinh dùng máy (0,3đ):** nêu nội quy phòng máy, phân công ghi sổ sử dụng máy, giám sát bằng phần mềm/quan sát, giáo dục HS về dùng máy đúng mục đích; nếu HS tái phạm thì phối hợp GVCN, cha mẹ (TT 03/2026 Điều 5 khoản 3 – tư vấn, hỗ trợ phù hợp tâm sinh lí lứa tuổi).", "**Báo cáo, đề xuất (0,4đ):** lập biên bản hiện trạng thiết bị, đề xuất bằng văn bản với hiệu trưởng/tổ trưởng về kế hoạch sửa chữa, bổ sung (nhà trường chịu trách nhiệm quản lí cơ sở vật chất, thiết bị – TT 15/2026 Điều 3 khoản 9); báo cáo đúng thực tế về số tiết thực hành (Luật Viên chức Điều 8 khoản 1: chịu trách nhiệm về kết quả nhiệm vụ; khoản 2: chấp hành quy chế, báo cáo khi phát hiện vi phạm).", "**Ứng xử với hiệu trưởng (0,3đ):** lễ phép trình bày thực trạng và rủi ro khi báo cáo sai; không tự ý khai khống hồ sơ, sổ sách chuyên môn (TT 15/2026 Điều 21 quy định hồ sơ giáo viên gồm kế hoạch bài dạy; yêu cầu trung thực theo TT 03/2026 Điều 4 khoản 2); thể hiện chính kiến đúng kênh, chấp hành phân công trong phạm vi chức năng (TT 03/2026 Điều 7 khoản 1, 3).", "**Không được làm (0,1đ):** khai khống số tiết, che giấu hạn chế thiết bị (TT 03/2026 Điều 4 khoản 2: trung thực).", "(Mức xử lí đối với hành vi báo cáo sai sự thật: đối chiếu văn bản gốc.)"]}]}, {"de": 14, "focus_luat": ["L5", "L7", "L9", "L2"], "focus_bai": ["B14", "B20", "B7"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị định 259/2026/NĐ-CP và Luật Viên chức 2025: (a) người trúng tuyển phải hoàn thiện hồ sơ trong bao lâu kể từ ngày công khai danh sách? Hợp đồng làm việc được ký chậm nhất khi nào và có giá trị gì? (b) Viên chức tuyển dụng từ 01/7/2026 có phải tập sự không, xếp lương thế nào? (c) Thời hạn mỗi lần bổ nhiệm viên chức quản lí?", "a": ["**(a) (0,3đ)** Hoàn thiện hồ sơ chậm nhất 15 ngày kể từ ngày công khai danh sách trúng tuyển (Điều 20 khoản 1); chậm nhất 05 ngày làm việc sau khi đơn vị nhận kết quả thì ký hợp đồng làm việc; **hợp đồng làm việc có giá trị như quyết định tuyển dụng** (Điều 21). Không hoàn thiện hồ sơ, gian lận kê khai, dùng văn bằng sai quy định thì bị xoá tên khỏi danh sách (Điều 20 khoản 3).", "**(b) (0,25đ)** Không còn chế độ tập sự: viên chức tuyển từ 01/7/2026 được bổ nhiệm, xếp lương theo vị trí việc làm tuyển dụng (căn cứ Luật Viên chức Điều 43 khoản 4; số điều chuyển tiếp của NĐ 259: đối chiếu văn bản gốc). Xếp mức lương khởi điểm của bậc nghề nghiệp ở vị trí được tuyển (Điều 10 khoản 1); có thời gian công tác phù hợp, đóng BHXH thì người đứng đầu quyết định xếp bậc phù hợp (Điều 10 khoản 2).", "**(c) (0,2đ)** 05 năm mỗi lần bổ nhiệm (trừ pháp luật nghề nghiệp quy định khác, chức danh đặc thù có thể dưới 5 năm) – Luật Viên chức Điều 30 khoản 2; hết hạn phải xem xét bổ nhiệm lại hoặc không."]}, {"q": "Câu 2 (0,75đ). Thông tư 06/2019/TT-BGDĐT (quy tắc ứng xử trong cơ sở giáo dục) hiện còn hiệu lực đến mức nào sau khi có Thông tư 03/2026? Nêu 5 giá trị cốt lõi cần thể hiện. So sánh quy định về hút thuốc, rượu bia của hai Thông tư.", "a": ["**Hiệu lực (0,25đ):** TT 03/2026/TT-BGDĐT (30/01/2026) thay Quyết định 16/2008 và Điều 6 TT 06/2019 (ứng xử của giáo viên) – Điều 6 hết hiệu lực từ 30/01/2026; các điều còn lại của TT 06/2019 (ứng xử của cán bộ quản lí, nhân viên, người học, cha mẹ, khách) vẫn là văn bản gốc (mức còn hiệu lực chính xác từng điều: đối chiếu văn bản gốc).", "**5 giá trị cốt lõi (0,25đ, Điều 3 khoản 2 TT 06/2019):** nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực.", "**So sánh hút thuốc, rượu bia (0,25đ):** TT 06/2019 (Điều 4 khoản 6): không hút thuốc, sử dụng đồ uống có cồn, chất cấm TRONG CƠ SỞ GIÁO DỤC; không tham gia tệ nạn xã hội. TT 03/2026 (Điều 4 khoản 6): nhà giáo không hút thuốc lá, sử dụng đồ uống có cồn KHI THỰC HIỆN NHIỆM VỤ; không sử dụng chất cấm, chất kích thích; không tham gia tệ nạn xã hội.", "(Điểm riêng của TT 06/2019: có cả ứng xử của người học (Điều 8), cha mẹ (Điều 9), khách (Điều 10); TT 03/2026 chỉ dành cho nhà giáo.)"]}, {"q": "Câu 3 (0,75đ). Theo Điều lệ trường phổ thông (TT 15/2026/TT-BGDĐT): (a) tuổi vào lớp 6, lớp 10; học sinh không được lưu ban quá mấy lần trong một cấp học? (b) Giáo viên chủ nhiệm được cho phép học sinh nghỉ học có lí do chính đáng tối đa mấy ngày liên tục? (c) Học sinh có những quyền nào liên quan đến khiếu nại và tư vấn tâm lí?", "a": ["**(a) (0,3đ)** Vào lớp 6: 11 tuổi; vào lớp 10: 15 tuổi (tính theo năm); không được lưu ban quá 03 lần trong một cấp học (Điều 31 khoản 2, 3).", "**(b) (0,2đ)** Giáo viên chủ nhiệm cho phép cá nhân học sinh có lí do chính đáng nghỉ học không quá 03 ngày liên tục (Điều 26 khoản 3); trên 3 ngày báo nhà trường.", "**(c) (0,25đ)** Học sinh có quyền khiếu nại với nhà trường và các cấp quản lí giáo dục về quyết định đối với bản thân (Điều 33 khoản 2); được bảo vệ thân thể, danh dự, nhân phẩm, sức khỏe tinh thần và được hỗ trợ tư vấn tâm lí học đường (Điều 33 khoản 6)."]}, {"q": "Câu 4 (0,75đ). Theo Luật Giáo dục 2019 (sửa đổi bởi Luật 123/2025/QH15): (a) giáo dục THCS thực hiện trong mấy năm, mục tiêu giáo dục THCS là gì (Điều 29 khoản 3)? (b) Từ 01/01/2026, học sinh học hết THCS nhận được gì? (c) Giáo dục bắt buộc gồm những cấp nào và từ khi nào?", "a": ["**(a) (0,35đ)** 04 năm học, từ lớp sáu đến hết lớp chín; vào lớp sáu 11 tuổi (Điều 28 khoản 1 điểm b). Mục tiêu: củng cố và phát triển kết quả giáo dục tiểu học; bảo đảm học sinh có học vấn phổ thông nền tảng, hiểu biết tối thiểu về kĩ thuật và hướng nghiệp để tiếp tục học THPT hoặc giáo dục nghề nghiệp (Điều 29 khoản 3).", "**(b) (0,2đ)** Không còn bằng tốt nghiệp THCS: học sinh đủ điều kiện được hiệu trưởng xác nhận vào học bạ việc hoàn thành chương trình THCS (Điều 34 khoản 1 mới); bằng tốt nghiệp THCS cấp trước 01/01/2026 vẫn có giá trị.", "**(c) (0,2đ)** Giáo dục tiểu học và giáo dục THCS là giáo dục bắt buộc; Nhà nước phổ cập giáo dục mầm non cho trẻ từ 03 đến 06 tuổi (Điều 14 khoản 1 mới – hiệu lực 01/7/2026)."]}], "p2": [{"q": "Câu 1 (1,0đ). [Tin 8 – Bài 8a: Danh sách dạng liệt kê và hình ảnh trong văn bản] Nêu 2 kiểu danh sách dạng liệt kê và tác dụng; cách tạo danh sách nhiều cấp; cách chèn và co dãn ảnh sao cho không che chữ, không méo; yêu cầu khi sử dụng ảnh.", "a": ["**Hai kiểu danh sách (0,3đ):** (1) dấu đầu dòng (Bullets: •, –, ✓); (2) có thứ tự (Numbering: 1, 2, 3 hoặc a, b, c). Tác dụng: văn bản rõ ràng, chia nhóm dễ đọc; số tự động cập nhật khi thêm bớt mục (không gõ số tay).", "**Danh sách nhiều cấp (0,2đ):** Home → Bullets/Numbering, Enter để tạo mục mới; nhấn Tab để xuống cấp (thụt lề), Shift + Tab để lên cấp.", "**Ảnh (0,3đ):** Insert → Pictures; kéo núm góc để co dãn không méo; chỉnh Wrap Text (ví dụ Behind Text khi làm ảnh nền) để ảnh không che chữ; hình đồ hoạ vẽ bằng Shapes.", "**Yêu cầu khi dùng ảnh (0,2đ):** ghi nguồn, tôn trọng bản quyền, xin phép khi cần; khai báo khi dùng ảnh/nội dung do AI tạo.", "Lỗi hay gặp: gõ số tay thay vì Numbering; quên Tab; ảnh che chữ do chưa chỉnh Wrap Text."]}, {"q": "Câu 2 (1,5đ). [Tin 8 – Bài 16: Tin học với nghề nghiệp] Lớp 8A có 40 học sinh (18 nữ, 22 nam). Khảo sát cho thấy 12 học sinh muốn theo nghề thuộc lĩnh vực tin học, trong đó có 3 nữ. Phòng kế toán xử lí 200 phiếu thu chi: làm thủ công mất 4 giờ, dùng phần mềm kế toán mất 20 phút.\na) Phân loại các nghề sau vào 2 nhóm \"nghề thuộc lĩnh vực tin học\" hoặc \"nghề liên quan ứng dụng tin học\": lập trình viên, quản trị mạng, nhà báo, streamer, bác sĩ, thiết kế website, kiến trúc sư, bán hàng trực tuyến.\nb) Tính tỉ lệ nữ trong cả lớp và trong nhóm 12 học sinh; nhận xét về bình đẳng giới và nêu 2 hoạt động giúp nữ tham gia nghề tin học.\nc) Phần mềm kế toán giúp nhanh gấp bao nhiêu lần? Đó là lợi ích nào trong 5 lợi ích của ứng dụng tin học?", "a": ["**a) (0,5đ):** nghề thuộc lĩnh vực tin học: lập trình viên, quản trị mạng, thiết kế website. Nghề liên quan ứng dụng tin học: nhà báo, streamer, bác sĩ, kiến trúc sư, bán hàng trực tuyến. (Hay nhầm: streamer, bán hàng online không phải nghề tin học mà là nghề có ứng dụng tin học.)", "**b) (0,6đ):** tỉ lệ nữ cả lớp 18/40 = **45%**; trong nhóm 12 học sinh: 3/12 = **25%**, thấp hơn nhiều so với tỉ lệ nữ của lớp. Nhận xét: nữ và nam đều có quyền và cơ hội như nhau; thực tế tỉ lệ nữ trong ngành tin học còn thấp, cần khuyến khích. Hoạt động: Ngày Quốc tế trẻ em gái với CNTT, chương trình DigiGirlZ; giới thiệu gương nữ như Ada Lovelace; câu lạc bộ lập trình có nữ làm nhóm trưởng.", "**c) (0,4đ):** 4 giờ = 240 phút; 240 / 20 = **12 lần**. Lợi ích: tăng tốc độ xử lí (nâng cao hiệu quả công việc).", "5 lợi ích: tăng tốc độ xử lí; liên lạc, trao đổi dễ dàng; làm việc nhóm, mở rộng phạm vi; nâng cao tay nghề; hỗ trợ thông tin cho người lao động."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 11: Tạo bài trình chiếu] Xây dựng mục tiêu bài học (toàn bài 2 tiết) gồm kiến thức, năng lực tin học, năng lực chung, phẩm chất và năng lực số/AI; nêu 2 tiêu chí kiểm tra đạt mục tiêu.", "a": ["**Kiến thức (0,4đ):** nêu 2 chức năng của phần mềm trình chiếu (tạo bài trình chiếu, trình chiếu có hiệu ứng động, chuyển trang); phân biệt trang tiêu đề với tiêu đề trang, trang nội dung, layout; nêu lợi ích của cấu trúc phân cấp (mạch lạc, dễ hiểu, dễ quản lí); tạo bài trình chiếu có cấu trúc phân cấp và lưu tệp.", "**Năng lực tin học (0,3đ):** NLa – sử dụng phần mềm trình chiếu (chọn layout, nhập nội dung, tăng/giảm cấp bằng Tab/Shift + Tab); NLc – chọn cách trình bày thông tin phù hợp để báo cáo dự án; NLd – dùng trình chiếu trong học tập.", "**Năng lực chung (0,2đ):** tự chủ và tự học; giao tiếp và hợp tác (làm việc nhóm báo cáo dự án).", "**Phẩm chất (0,2đ):** chăm chỉ, trách nhiệm; trung thực khi dùng nội dung của người khác.", "**Năng lực số/AI (0,2đ):** khai báo khi dùng AI (có slide khai báo); kiểm chứng số liệu chatbot đưa ra (ví dụ \"5000 cây/tuần\") trước khi đưa vào bài.", "**2 tiêu chí kiểm tra (0,2đ):** (1) HS tạo được bài trình chiếu ≥ 3 trang, có trang tiêu đề, tiêu đề trang đúng; (2) có ít nhất 1 trang nội dung dùng cấu trúc phân cấp (ví dụ \"Công việc trong ngày\") và lưu tệp đúng tên.", "(Mục tiêu viết bằng động từ đo được, theo chương trình Tin học 2018.)"]}, {"q": "Câu 4 (1,0đ). [Nhận xét – đánh giá đoạn dạy, Tin 7 – Bài 11] Giáo viên A dạy phần \"Cấu trúc phân cấp\": (1) giảng nhanh \"trang tiêu đề là trang đầu, tiêu đề trang là tên trang\" rồi cho HS tự làm; (2) HS tạo ý phụ bằng cách gõ nhiều dấu cách đầu dòng, GV không nhắc; (3) GV cho chatbot soạn nội dung \"Trường học xanh\" rồi yêu cầu HS dán nguyên vào bài trình chiếu, không kiểm chứng; (4) cuối giờ GV không đánh giá sản phẩm. Hãy nhận xét ưu, nhược điểm và đề xuất cải tiến.", "a": ["**Ưu điểm (0,2đ):** có gắn tình huống thực (Trường học xanh); cho HS thực hành; có dùng công nghệ AI hỗ trợ.", "**Nhược điểm (0,4đ):**", "- Giảng nhanh, không có hoạt động so sánh nên HS dễ nhầm trang tiêu đề với tiêu đề trang.", "- Không hướng dẫn tăng/giảm cấp bằng Tab/Shift + Tab, HS tạo cấu trúc giả bằng dấu cách (lỗi hay gặp: quên dùng tăng cấp).", "- Dùng AI không kiểm chứng, không khai báo – không phát triển năng lực AI; thông tin có thể sai.", "- Không có kiểm tra, đánh giá sản phẩm cuối giờ.", "**Đề xuất (0,4đ):** hoạt động Think – Pair – Share so sánh 2 trang chiếu mẫu để phân biệt khái niệm; GV làm mẫu Tab/Shift + Tab, HS thực hành \"Công việc trong ngày\"; yêu cầu kiểm chứng số liệu AI bằng nguồn tin cậy và thêm slide khai báo AI; kết thúc bằng giơ thẻ Đúng/Sai và đánh giá chéo sản phẩm theo tiêu chí."]}], "p3": [{"q": "Tình huống (2,0đ). Em Khoa (lớp 8C) gần đây hay ngủ gật trong giờ, bỏ tiết, điểm sa sút; bạn bè cho biết em chơi game đến 2–3 giờ sáng. Mẹ em tìm gặp thầy/cô (giáo viên chủ nhiệm) nhờ giúp đỡ nhưng bố em cho rằng \"con trai chơi game là bình thường\". Một phụ huynh khác nhắn hỏi thầy/cô về \"tình hình học tập và đời tư\" của Khoa vì con họ chơi cùng. Thầy/cô xử lí thế nào? Nêu căn cứ.", "a": ["**Tìm hiểu nguyên nhân, hỗ trợ học sinh (0,5đ):** trò chuyện riêng, lắng nghe, không quát mắng, không dán nhãn; tìm hiểu hoàn cảnh gia đình, mức độ chơi game, sức khỏe; hướng dẫn xây dựng thời gian biểu; tư vấn, hỗ trợ về học tập và tâm lí phù hợp lứa tuổi (TT 03/2026 Điều 5 khoản 1, 3); đề nghị hỗ trợ tư vấn tâm lí học đường (TT 15/2026 Điều 33 khoản 6).", "**Phối hợp cha mẹ (0,5đ):** mời cả bố và mẹ trao đổi; chủ động, trung thực chia sẻ thông tin về học tập, rèn luyện của chính Khoa (TT 03/2026 Điều 8 khoản 1, 2); thống nhất biện pháp quản lí giờ chơi, thiết bị; không áp đặt, không xúc phạm phụ huynh (Điều 8 khoản 4).", "**Bảo mật thông tin (0,3đ):** không trao đổi \"đời tư\" của Khoa với phụ huynh khác; chỉ cung cấp thông tin về chính con của họ theo thẩm quyền và khi được cấp quản lí đồng ý (TT 03/2026 Điều 5 khoản 4 – không công khai thông tin người học trái quy định; Điều 8 khoản 2).", "**Phối hợp nhà trường (0,3đ):** báo cáo ban giám hiệu, phối hợp Đoàn, Đội, giáo viên bộ môn theo dõi; vai trò giáo viên chủ nhiệm: phối hợp với cha mẹ học sinh (TT 15/2026 Điều 26 khoản 3).", "**Giáo dục, phòng ngừa chung (0,2đ):** là giáo viên Tin học, lồng ghép giáo dục sử dụng công nghệ có trách nhiệm, an toàn trên mạng, quản lí thời gian trực tuyến vào giờ học, sinh hoạt lớp.", "**Không được làm (0,2đ):** công khai tên em trước lớp, trù dập, đánh giá thấp để \"trừng phạt\" (TT 03/2026 Điều 5 khoản 3, 4).", "(Quy định riêng về trách nhiệm cha mẹ trong Luật Giáo dục Điều 90: số khoản đối chiếu văn bản gốc.)"]}]}, {"de": 15, "focus_luat": ["L6", "L8", "L1", "L3"], "focus_bai": ["B15", "B1", "B8"], "p1": [{"q": "Câu 1 (0,75đ). Nghị quyết 248/2025/QH15 được Quốc hội thông qua ngày nào, có hiệu lực khi nào? Nếu NQ 248 và luật khác quy định khác nhau về cùng một vấn đề thì áp dụng văn bản nào? Nêu 2 chính sách khác của NQ (cơ chế đặc thù, vượt trội) liên quan đến chuyển đổi số hoặc hỗ trợ người học.", "a": ["**Ban hành, hiệu lực (0,25đ):** thông qua ngày 10/12/2025 (Kì họp thứ 10, Quốc hội khóa XV); hiệu lực từ 01/01/2026 (Điều 9 khoản 1). Tên: về một số cơ chế, chính sách đặc thù, vượt trội để thực hiện đột phá phát triển giáo dục và đào tạo.", "**Quan hệ với luật khác (0,25đ):** nếu NQ 248 và luật, nghị quyết khác quy định khác nhau thì áp dụng NQ 248; nếu văn bản của Quốc hội ban hành sau có chính sách ưu đãi hơn thì áp dụng văn bản đó (Điều 9 khoản 2, 3).", "**2 chính sách khác (0,25đ, nêu đúng 2 ý):** ưu tiên cơ sở dữ liệu quốc gia về giáo dục và đào tạo, hạ tầng số, nền tảng dùng chung (Điều 4); người học vay tín dụng ưu đãi từ Ngân hàng Chính sách xã hội cho học tập, sinh hoạt (Điều 5 khoản 1); cơ sở giáo dục hợp tác với tổ chức khoa học công nghệ, doanh nghiệp để thực hiện chương trình gắn với thị trường lao động (Điều 3 khoản 2).", "(Số khoản của Điều 4, 5: đối chiếu văn bản gốc; NQ 248 không quy định miễn học phí phổ thông – nội dung này ở Luật 123/2025 Điều 99 khoản 3.)"]}, {"q": "Câu 2 (0,75đ). Nghị quyết 71-NQ/TW ban hành ngày nào, của cơ quan nào, có mấy quan điểm chỉ đạo và mấy nhóm nhiệm vụ, giải pháp? Nêu mục tiêu đến 2035 và tầm nhìn 2045. NQ 71 chủ trương gì về hội đồng trường trong cơ sở giáo dục công lập?", "a": ["**Ban hành (0,2đ):** 22/8/2025; Bộ Chính trị; về đột phá phát triển giáo dục và đào tạo (Tổng Bí thư Tô Lâm ký). Có 06 quan điểm chỉ đạo và 08 nhóm nhiệm vụ, giải pháp.", "**Mục tiêu 2035 (0,2đ):** hoàn thành phổ cập giáo dục THPT và tương đương; chỉ số giáo dục trong HDI trên 0,85; ít nhất 02 cơ sở đại học thuộc nhóm 100 thế giới.", "**Tầm nhìn 2045 (0,15đ):** hệ thống giáo dục quốc dân hiện đại, công bằng, chất lượng, thuộc nhóm 20 quốc gia hàng đầu thế giới; ít nhất 05 cơ sở đại học thuộc nhóm 100 thế giới.", "**Hội đồng trường (0,2đ):** không tổ chức hội đồng trường trong cơ sở giáo dục công lập (trừ trường có thỏa thuận quốc tế); thực hiện bí thư cấp ủy kiêm người đứng đầu cơ sở giáo dục (đã được cụ thể hóa: hội đồng trường các cơ sở phổ thông công lập kết thúc hoạt động từ 01/01/2026; Điều lệ trường phổ thông chỉ còn hội đồng trường ở trường tư thục)."]}, {"q": "Câu 3 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) viên chức được ký hợp đồng làm việc với tối đa bao nhiêu đơn vị sự nghiệp công lập? (b) Nêu 3 việc viên chức không được làm trong Điều 10. (c) Xếp loại viên chức hằng năm có mấy mức? Thời hạn kiến nghị và thời hạn giải quyết kiến nghị về kết quả xếp loại?", "a": ["**(a) (0,15đ)** Chỉ được ký hợp đồng làm việc với 01 đơn vị sự nghiệp công lập và chịu sự quản lí của đơn vị đó (Điều 8 khoản 5).", "**(b) (0,3đ, nêu đúng 3 ý trong 7 khoản Điều 10):** trốn tránh, thoái thác, đùn đẩy nhiệm vụ; gây bè phái, mất đoàn kết; tự ý nghỉ việc, bỏ việc; tham gia đình công; phát tán thông tin sai lệch làm ảnh hưởng uy tín đất nước, địa phương, đơn vị (khoản 1); phân biệt đối xử về dân tộc, giới tính, độ tuổi, khuyết tật, tôn giáo, tín ngưỡng, thành phần xã hội (khoản 5); xúc phạm danh dự, nhân phẩm, uy tín người khác khi thực hiện hoạt động nghề nghiệp (khoản 6); tham ô, tham nhũng, lãng phí, tiêu cực, nhũng nhiễu (khoản 3).", "**(c) (0,3đ)** 4 mức: Hoàn thành xuất sắc nhiệm vụ; Hoàn thành tốt nhiệm vụ; Hoàn thành nhiệm vụ; Không hoàn thành nhiệm vụ (Điều 26 khoản 1). Kiến nghị bằng văn bản trong 05 ngày kể từ ngày công khai kết quả (Điều 27 khoản 2); cấp có thẩm quyền giải quyết trong 10 ngày làm việc kể từ ngày nhận kiến nghị (khoản 3); không xem xét lại kết quả giải quyết kiến nghị (khoản 4)."]}, {"q": "Câu 4 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15: (a) trình độ chuẩn của giáo viên THCS? (b) Phương thức tuyển dụng nhà giáo có yêu cầu gì đặc thù? (c) Khi nào nhà giáo không được thuyên chuyển? (d) Chính sách tiền lương nhà giáo công lập?", "a": ["**(a) (0,2đ)** Bằng cử nhân trở lên thuộc ngành đào tạo giáo viên phù hợp với môn học, cấp học; hoặc cử nhân trở lên chuyên ngành phù hợp và có chứng chỉ nghiệp vụ sư phạm (Điều 28 khoản 1 điểm b).", "**(b) (0,15đ)** Thi tuyển hoặc xét tuyển, trong đó phải có thực hành sư phạm (Điều 14 khoản 1 điểm b).", "**(c) (0,2đ)** Không được thuyên chuyển khi: đang bị xem xét kỉ luật, đang bị kiểm tra, xác minh, thanh tra, điều tra, truy tố, xét xử; chưa đủ 03 năm công tác kể từ ngày được tuyển dụng (trừ tự nguyện đến vùng dân tộc thiểu số, miền núi, biên giới, hải đảo, vùng đặc biệt khó khăn) – Điều 19 khoản 2.", "**(d) (0,2đ)** Lương nhà giáo trong cơ sở công lập được xếp cao nhất trong hệ thống thang bậc lương hành chính sự nghiệp; có phụ cấp ưu đãi nghề và phụ cấp khác theo tính chất công việc, theo vùng (Điều 23 khoản 1 điểm a, b).", "(Ghi nhớ thêm: nhà giáo tiếp tục hưởng phụ cấp thâm niên đến khi cải cách tiền lương – Điều 42 khoản 2.)"]}], "p2": [{"q": "Câu 1 (1,0đ). [Tin 8 – Bài 8b: Phần mềm chỉnh sửa ảnh] Nêu 3 chức năng của phần mềm chỉnh sửa ảnh. Giải thích khái niệm đối tượng và lớp ảnh, quan hệ giữa lớp trên và lớp dưới. Phân biệt pixel, độ phân giải; phân biệt lưu bằng Save và Export As trong GIMP.", "a": ["**3 chức năng (0,25đ):** tạo mới ảnh; chỉnh sửa ảnh (cắt, xoá phần lỗi, chỉnh màu…); chuyển đổi định dạng ảnh.", "**Đối tượng, lớp (0,3đ):** đối tượng là từng phần có thể xử lí riêng trong ảnh; lớp ảnh giống các tờ giấy bóng kính xếp chồng; lớp ảnh nền ở dưới cùng; **lớp trên che lớp dưới** (không phải ngược lại); thao tác chỉ tác động lên lớp đang chọn nên phải chọn lớp trước khi chỉnh.", "**Pixel, độ phân giải (0,2đ):** pixel là điểm ảnh nhỏ nhất; độ phân giải là số pixel theo chiều rộng × chiều cao (ví dụ 1920 × 1080).", "**Lưu (0,25đ):** Save lưu định dạng riêng của phần mềm (.xcf) để tiếp tục sửa, giữ các lớp; Export As xuất ra .png, .jpg để chia sẻ.", "Lỗi hay gặp: nhầm lớp dưới che lớp trên; quên chọn lớp trước khi chỉnh."]}, {"q": "Câu 2 (1,5đ). [Tin 7 – Bài 2: Phần mềm máy tính] Máy tính của phòng Tin học có ổ đĩa 256 GB. Đã cài: hệ điều hành 28 GB, bộ Office 4,5 GB, GIMP 0,3 GB, Scratch 0,4 GB.\na) Tính tổng dung lượng đã cài, dung lượng trống còn lại và tỉ lệ ổ đĩa đã dùng (làm tròn 1 chữ số thập phân %).\nb) Ghép mỗi tệp với phần mềm ứng dụng thích hợp qua phần mở rộng: bai1.docx, bang.xlsx, tp.pptx, game.sb3, anh.png.\nc) Phân loại thành phần mềm hệ thống hoặc phần mềm ứng dụng: Windows, Word, Android, Paint, Linux, Scratch; nêu 3 chức năng của hệ điều hành và vì sao phải chọn đúng bản Scratch theo hệ điều hành.", "a": ["**a) (0,5đ):** tổng đã cài 28 + 4,5 + 0,3 + 0,4 = **33,2 GB**; còn trống 256 − 33,2 = **222,8 GB**; tỉ lệ đã dùng 33,2 / 256 ≈ 0,1297 ≈ **13,0%**.", "**b) (0,35đ, mỗi ý 0,07đ):** .docx – Word (soạn thảo văn bản); .xlsx – Excel hoặc phần mềm bảng tính; .pptx – PowerPoint hoặc phần mềm trình chiếu; .sb3 – Scratch; .png – phần mềm xem/chỉnh sửa ảnh (Paint, GIMP).", "**c) (0,65đ):** phần mềm hệ thống (hệ điều hành): Windows, Android, Linux. Phần mềm ứng dụng: Word, Paint, Scratch (0,25đ).", "- 3 chức năng của hệ điều hành (0,25đ): quản lí, điều khiển thiết bị và dữ liệu; tạo giao diện giữa người dùng và máy tính; tạo môi trường để chạy các phần mềm ứng dụng.", "- Phần mềm ứng dụng chạy trên hệ điều hành, nên phải cài bản phù hợp (Windows, macOS, Linux) (0,15đ).", "Lưu ý nhầm: Windows Explorer, Word không phải hệ điều hành."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 14: Thuật toán tìm kiếm tuần tự] Thiết kế hoạt động luyện tập mô phỏng thuật toán bằng phương pháp đóng vai (lớp 40 HS; danh sách 8 số: 15, 8, 23, 4, 42, 16, 9, 30): nêu mục tiêu, thẻ vai, tổ chức 4 bước chuyển giao – thực hiện – báo cáo – kết luận và kết quả mong đợi khi tìm 23 và khi tìm 50.", "a": ["**Mục tiêu (0,3đ):** HS mô phỏng được thuật toán tìm kiếm tuần tự, nêu đầu vào, đầu ra và 2 điều kiện dừng (gặp đúng đối tượng; hết danh sách); NLc giải quyết vấn đề, năng lực chung giao tiếp – hợp tác; phẩm chất trách nhiệm.", "**Chuẩn bị (0,1đ):** 8 thẻ số đặt thành hàng, 1 thẻ \"cần tìm\", thẻ vai: người tìm, người ghi, người kiểm tra điều kiện dừng.", "**Bước 1 – Chuyển giao (0,2đ):** nêu bài toán tìm số 23 (rồi 50) trong danh sách, quy tắc xét lần lượt từ đầu đến cuối, mỗi nhóm 5 HS đóng vai, 7 phút.", "**Bước 2 – Thực hiện (0,2đ):** nhóm đóng vai, người ghi điền bảng (lần xét, phần tử, so sánh); GV quan sát, nhắc điều kiện dừng thứ hai.", "**Bước 3 – Báo cáo (0,2đ):** 2 nhóm trình diễn; các nhóm còn lại đối chiếu bảng mô phỏng, tia chớp trả lời \"khi nào dừng\".", "**Bước 4 – Kết luận (0,2đ):** GV chốt: xét lần lượt, còn dừng khi gặp đúng hoặc hết danh sách; thuật toán luôn dừng.", "**Kết quả mong đợi (0,3đ):** tìm 23: xét 15, 8, 23 – dừng ở **vị trí 3** sau **3 lần xét**; tìm 50: xét hết **8 phần tử**, không thấy, kết luận \"không tìm thấy\" do hết danh sách.", "Lỗi hay gặp: quên điều kiện dừng thứ hai; xét tiếp dù đã tìm thấy."]}, {"q": "Câu 4 (1,0đ). [Năng lực AI và bản quyền – Tin 8 Bài 8b] Chatbot trả lời: \"Trong ảnh nhiều lớp, lớp dưới che lớp trên\" và \"ảnh jpg 1920 × 1080 có khoảng 2 triệu pixel\". Một học sinh dùng công cụ AI tạo ảnh \"cảnh lũ lụt\" rồi đăng lên mạng như ảnh thật. (a) Nhận xét hai câu trả lời của chatbot. (b) Giáo viên cần giáo dục học sinh điều gì về ảnh do AI tạo và bản quyền ảnh?", "a": ["**(a) (0,4đ):** câu 1 SAI – lớp trên che lớp dưới (đối chiếu SGK). Câu 2 ĐÚNG về bậc độ lớn: 1920 × 1080 = 2 073 600 ≈ 2,07 triệu pixel; ngoài ra jpg là định dạng nén, số pixel do độ phân giải quyết định.", "- Bài học: AI trả lời đúng lẫn sai trong cùng một đoạn, nghe đều thuyết phục nên phải kiểm chứng từng ý bằng SGK hoặc thử trên GIMP.", "**(b) (0,6đ):** không đăng ảnh do AI tạo như ảnh thật vì lan truyền thông tin sai lệch, vi phạm yêu cầu trung thực khi dùng công nghệ số; phải ghi chú ảnh do AI tạo và khai báo khi dùng; ảnh trên Internet hầu hết có bản quyền: xin phép, ghi nguồn; không dùng ảnh người khác để chỉnh sửa, ghép xúc phạm (liên quan quyền riêng tư).", "(Mã năng lực AI tham chiếu: 8.B1.1, 8.B2.1.)"]}], "p3": [{"q": "Tình huống (2,0đ). Một đoạn clip ngắn cắt ghép lời nói của thầy/cô giáo Tin học trong giờ dạy (bỏ ngữ cảnh) bị đăng lên Facebook kèm nội dung \"giáo viên xúc phạm học sinh\", nhiều người bình luận chửi bới. Phụ huynh nhắn tin yêu cầu nhà trường xử lí ngay. Thầy/cô nên xử lí thế nào? Nêu căn cứ.", "a": ["**Giữ bình tĩnh, báo cáo ngay (0,4đ):** báo hiệu trưởng, tổ trưởng chuyên môn; cung cấp thông tin đầy đủ; lưu bằng chứng (đường dẫn, ảnh chụp màn hình, bản gốc clip nếu có).", "**Không đáp trả bằng thông tin sai lệch (0,4đ):** không tranh cãi, không đăng bài phản bác bằng lời lẽ xúc phạm trên mạng xã hội (Luật Viên chức Điều 10 khoản 1: không phát tán, phát ngôn thông tin sai lệch làm ảnh hưởng uy tín đơn vị; khoản 6: không xúc phạm người khác); TT 03/2026 Điều 4 khoản 2 – có trách nhiệm khi sử dụng thông tin và ứng xử trên không gian mạng.", "**Căn cứ bảo vệ nhà giáo (0,4đ):** Luật Nhà giáo Điều 11 khoản 3 điểm b – tổ chức, cá nhân không được đăng tải, phát tán thông tin mang tính quy kết về trách nhiệm của nhà giáo khi chưa có kết luận của cơ quan có thẩm quyền; Điều 8 khoản 2 điểm c – được tôn trọng, bảo vệ uy tín, danh dự, nhân phẩm; Điều 37 – xử lí hành vi xâm phạm uy tín, danh dự, nhân phẩm nhà giáo.", "**Làm rõ sự việc đúng quy trình (0,4đ):** nhà trường xác minh ngữ cảnh, xem lại camera hoặc ý kiến học sinh trong lớp, mời cha mẹ làm việc, trao đổi trung thực; nếu thầy/cô có sai sót thì nhận xét, rút kinh nghiệm theo TT 03/2026 Điều 5 (ngôn ngữ đúng mực, không xúc phạm học sinh); nếu nhà trường thấy cần thiết, có thể tạm đình chỉ giảng dạy trong thời gian xem xét (Luật Nhà giáo Điều 36 – người đứng đầu cơ sở giáo dục quyết định).", "**Truyền thông chính thống (0,2đ):** nhà trường đăng thông tin chính thức về kết quả xác minh trên kênh chính thống; thầy/cô góp phần chống tin giả (TT 03/2026 Điều 9 khoản 3).", "**Phòng ngừa (0,2đ):** nhắc học sinh không quay clip, phát tán nội dung khi chưa được phép (TT 06/2019 Điều 8, Điều 4 khoản 7); GV rà soát lời nói trong giờ dạy.", "(Xử phạt hành chính hoặc trách nhiệm hình sự đối với người đăng clip cắt ghép, bồi thường danh dự: đối chiếu văn bản gốc.)"]}]}, {"de": 16, "focus_luat": ["L7", "L9", "L2", "L4"], "focus_bai": ["B16", "B2", "B9"], "p1": [{"q": "Câu 1 (0,75đ). Theo Thông tư 03/2026/TT-BGDĐT về quy tắc ứng xử của nhà giáo: (a) cho biết ngày ban hành và văn bản bị thay thế; (b) nêu 6 nhóm quan hệ ứng xử được quy định ở Điều 4–9; (c) nêu 3 điều nhà giáo không được làm trong ứng xử chung (Điều 4 khoản 6).", "a": ["**(a) 0,25đ:** ban hành 30/01/2026, hiệu lực từ 30/01/2026 (3 chương, 15 điều); thay thế Quyết định 16/2008/QĐ-BGDĐT (đạo đức nhà giáo) và Điều 6 Thông tư 06/2019/TT-BGDĐT.", "**(b) 0,25đ:** 6 nhóm: ứng xử chung (Điều 4); với người học (Điều 5); với đồng nghiệp (Điều 6); với cán bộ quản lí cơ sở giáo dục (Điều 7); với cha mẹ hoặc người giám hộ của người học (Điều 8); với cộng đồng (Điều 9).", "**(c) 0,25đ** (nêu đúng 3 trong các ý): không lợi dụng chức danh, danh hiệu, hình ảnh nhà giáo để vi phạm pháp luật hay tư lợi; không tự ý bỏ việc; không tuyên truyền nội dung trái quan điểm, chính sách của Đảng và Nhà nước; không hút thuốc lá, dùng đồ uống có cồn khi thực hiện nhiệm vụ; không dùng chất cấm, không tham gia tệ nạn xã hội; **không thờ ơ, né tránh hoặc che giấu** hành vi vi phạm của người học, đồng nghiệp."]}, {"q": "Câu 2 (0,75đ). Theo Điều lệ trường tiểu học, THCS, THPT và trường phổ thông nhiều cấp học (Thông tư 15/2026/TT-BGDĐT), nêu: (a) nhiệm kỳ của hiệu trưởng và giới hạn số nhiệm kỳ ở trường công lập; (b) sĩ số tối đa một lớp THCS; (c) tuổi vào lớp sáu và số lần lưu ban tối đa trong một cấp học; (d) quy định về tổ phó và tần suất sinh hoạt của tổ chuyên môn.", "a": ["**(a) 0,2đ:** nhiệm kỳ hiệu trưởng 05 năm; giữ chức ở một trường công lập không quá 02 nhiệm kỳ liên tiếp (vùng sâu, vùng xa, vùng đặc biệt khó khăn do cấp bổ nhiệm xem xét) – Điều 10 khoản 1 điểm c.", "**(b) 0,15đ:** không quá 45 học sinh/lớp ở cấp THCS (và THPT); Chủ tịch UBND cấp tỉnh quy định cụ thể theo hướng giảm sĩ số – Điều 16 khoản 3.", "**(c) 0,2đ:** vào lớp sáu là 11 tuổi (tính theo năm); không được lưu ban quá 03 lần trong một cấp học – Điều 31.", "**(d) 0,2đ:** tổ chuyên môn từ 07 thành viên trở lên có tổ phó; tổ trưởng, tổ phó do hiệu trưởng bổ nhiệm; sinh hoạt chuyên môn ít nhất 01 lần trong 02 tuần – Điều 13."]}, {"q": "Câu 3 (0,75đ). Theo Luật Giáo dục 43/2019/QH14 (sửa đổi bởi Luật 123/2025/QH15): (a) giáo dục nào là giáo dục bắt buộc theo Điều 14 khoản 1 mới và từ ngày nào áp dụng; (b) học sinh học hết chương trình THCS nhận văn bản gì (Điều 34 khoản 1); (c) thời gian học THCS và mục tiêu giáo dục THCS (Điều 28, Điều 29 khoản 3).", "a": ["**(a) 0,25đ:** giáo dục tiểu học và giáo dục THCS là giáo dục bắt buộc; Nhà nước phổ cập giáo dục mầm non cho trẻ từ 03 đến 06 tuổi; áp dụng từ **01/7/2026** (Luật 123/2025 ban hành 10/12/2025, hiệu lực chung 01/01/2026, riêng nội dung này 01/7/2026).", "**(b) 0,25đ:** từ 01/01/2026 không còn cấp bằng tốt nghiệp THCS; học sinh đủ điều kiện được **hiệu trưởng xác nhận vào học bạ** việc hoàn thành chương trình THCS (bằng đã cấp trước đó vẫn có giá trị).", "**(c) 0,25đ:** THCS học 04 năm (lớp 6 đến lớp 9), vào lớp sáu 11 tuổi; mục tiêu: củng cố, phát triển kết quả giáo dục tiểu học; bảo đảm học vấn phổ thông nền tảng, hiểu biết tối thiểu về kĩ thuật và hướng nghiệp để học THPT hoặc giáo dục nghề nghiệp."]}, {"q": "Câu 4 (0,75đ). Theo Nghị định 93/2026/NĐ-CP hướng dẫn Luật Nhà giáo: (a) giáo viên THCS có chia hạng I, II, III không (căn cứ điều nào)? (b) thời gian nghỉ hè của giáo viên THCS và ai quyết định thời điểm nghỉ hè; (c) người có thời gian giảng dạy phù hợp từ bao lâu thì được cộng điểm ưu tiên khi tuyển dụng, cộng bao nhiêu điểm, vào vòng nào, và nếu thuộc nhiều diện thì xử lí thế nào?", "a": ["**(a) 0,25đ:** Không. \"Giáo viên trung học cơ sở\" là một chức danh, không chia hạng (Điều 3 khoản 1); chỉ chức danh giảng viên mới có phân cấp (giảng viên, chính, cao cấp...).", "**(b) 0,25đ:** 08 tuần/năm, **đã bao gồm** nghỉ phép hằng năm, hưởng nguyên lương và phụ cấp (Điều 17 khoản 1 điểm a, g); Chủ tịch UBND cấp tỉnh quyết định thời điểm nghỉ hè theo kế hoạch năm học của Bộ GDĐT (Điều 17 khoản 3).", "**(c) 0,25đ:** từ đủ 03 năm (36 tháng) trở lên, có đóng BHXH bắt buộc (không liên tục thì cộng dồn) → cộng **05 điểm** vào kết quả **vòng 2**; thuộc nhiều diện thì chỉ cộng điểm cao nhất (Điều 6 khoản 1, khoản 4)."]}], "p2": [{"q": "Câu 1 (1đ). [Tin 8 – Bài 12: Từ thuật toán đến chương trình] (a) Nêu mối quan hệ giữa thuật toán và chương trình; mỗi bước của sơ đồ khối ứng với gì trong Scratch? (b) Viết thuật toán (ngôn ngữ tự nhiên) vẽ **hình lục giác đều cạnh 80 bước** cho nhân vật bọ rùa; nêu khối lệnh Scratch cần dùng, số lần lặp và góc quay.", "a": ["**(a) 0,4đ:** thuật toán là dãy hữu hạn các bước để giải một bài toán; **chương trình là dãy lệnh điều khiển máy tính thực hiện một thuật toán**; mỗi bước của sơ đồ khối ứng với một (nhóm) lệnh/khối lệnh Scratch.", "**(b) 0,6đ** – thuật toán: Bước 1: đặt bọ rùa ở vị trí xuất phát; Bước 2: lặp lại 6 lần: di chuyển 80 bước, xoay phải 60°; Bước 3: kết thúc.", "Công thức: góc quay = 360° : số cạnh = 360° : 6 = **60°** (HS hay nhầm với góc trong 120° của lục giác).", "Khối lệnh Scratch: \"lặp lại 6 lần\" chứa \"di chuyển 80 bước\" và \"xoay phải 60 độ\" (có thể thêm \"bút xuống\" từ phần Bút vẽ).", "Thang điểm gợi ý: ý (a) 0,4đ; thuật toán đủ 3 bước 0,2đ; đúng số lần lặp 6 và góc 60° 0,3đ; khối lệnh 0,1đ."]}, {"q": "Câu 2 (1,5đ). [Tin 7 – Bài 3: Quản lí dữ liệu trong máy tính] Thư mục DuLich của bạn Nam gồm 3 thư mục con: Anh (2,4 GB), Video (5,8 GB), TaiLieu (650 MB). Quy ước 1 GB = 1024 MB.\n(a) Tính tổng dung lượng thư mục DuLich theo MB và theo GB (làm tròn 2 chữ số thập phân).\n(b) Nam có 3 phương án sao lưu: USB 4 GB; ổ cứng ngoài 500 GB; kho lưu trữ đám mây miễn phí 5 GB. Phương án nào đủ chỗ? Mỗi phương án thuộc loại sao lưu nào?\n(c) Nếu tốc độ chép trung bình 40 MB/s thì cần khoảng bao nhiêu giây để sao lưu (làm tròn đến giây)?\n(d) Đánh giá độ mạnh của 4 mật khẩu: Nam2010; T#m7!kQz9; 12345678; matkhau@A. Nêu tiêu chí mật khẩu mạnh.", "a": ["**(a) 0,4đ:** Anh = 2,4 × 1024 = 2457,6 MB; Video = 5,8 × 1024 = 5939,2 MB; TaiLieu = 650 MB → tổng = **9046,8 MB** ≈ 9046,8 : 1024 = **8,83 GB**.", "**(b) 0,4đ:** USB 4 GB (4 < 8,83) và đám mây 5 GB (5 < 8,83) **không đủ**; ổ cứng ngoài 500 GB **đủ**. USB và ổ cứng ngoài là sao lưu cục bộ; đám mây là sao lưu từ xa.", "**(c) 0,3đ:** 9046,8 : 40 = 226,17 → khoảng **226 giây** (≈ 3,8 phút).", "**(d) 0,4đ:** tiêu chí: tối thiểu 8 kí tự; có chữ hoa, chữ thường, chữ số, kí hiệu đặc biệt; không dùng tên người, ngày sinh. Nam2010: yếu (7 kí tự, tên + năm sinh); T#m7!kQz9: **mạnh** (9 kí tự, đủ 4 loại); 12345678: rất yếu (chỉ có số, dễ đoán); matkhau@A: chưa mạnh (từ dễ đoán, thiếu chữ số).", "Kiểm chứng: 2457,6 + 5939,2 + 650 = 9046,8."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 15: Thuật toán tìm kiếm nhị phân] Thiết kế **Hoạt động Khám phá** (khoảng 15 phút) cho bài này, theo chương trình Tin học 2018, gồm: (a) mục tiêu hoạt động (kiến thức, năng lực tin học, năng lực chung, phẩm chất); (b) nội dung/tình huống và sản phẩm dự kiến; (c) tổ chức 4 bước: chuyển giao – thực hiện – báo cáo – kết luận.", "a": ["**(a) 0,4đ:** kiến thức: giải thích được tìm kiếm nhị phân là chia đôi vùng tìm kiếm của danh sách **đã sắp xếp**, so sánh với phần tử ở giữa; năng lực tin học: **NLc** (giải thích, mô phỏng thuật toán), **NLd** (chọn thuật toán tìm kiếm phù hợp, biểu diễn bằng bảng), **NLe** (hợp tác kiểm tra kết quả); năng lực chung: tự chủ và tự học, giao tiếp và hợp tác, giải quyết vấn đề; phẩm chất: chăm chỉ, cẩn thận, trung thực.", "**(b) 0,4đ:** tình huống – trò chơi \"đoán số bí mật từ 1 đến 100\": người đoán nói một số, người giữ số chỉ trả lời \"lớn hơn/nhỏ hơn/đúng\". Ví dụ số bí mật 73, chiến lược chia đôi: 50 → 75 → 62 → 68 → 71 → 73 (**6 lần**); chiến lược đoán lần lượt từ 1 có thể mất 73 lần. Tối đa 7 lần cho 100 số (vì 2^7 = 128 ≥ 100). Sản phẩm: bảng ghi các lần đoán; nhận xét \"mỗi lần loại bỏ một nửa\"; rút ra điều kiện danh sách phải sắp xếp.", "**(c) 0,5đ – 4 bước:** (1) **Chuyển giao:** GV nêu luật chơi, chia cặp, phát bảng ghi lần đoán; (2) **Thực hiện:** HS chơi 2 ván (số bí mật khác nhau), ghi lại từng lần đoán, thử chiến lược đoán chia đôi, GV quan sát, gợi ý \"chọn số ở giữa vùng còn lại\"; (3) **Báo cáo:** 2–3 cặp trình bày chiến lược và số lần đoán, lớp nhận xét; (4) **Kết luận:** GV chốt thuật toán tìm kiếm nhị phân, nhấn mạnh danh sách phải đã sắp xếp, dẫn vào hình thức hoá bằng bảng theo dõi lần lặp (đầu, cuối, giữa).", "**0,2đ** cho tính khả thi (thời gian, phương tiện, phân hoá), nhận xét đánh giá bằng quan sát/phiếu. Lưu ý lỗi HS hay gặp: quên điều kiện sắp xếp, tính sai vị trí giữa của nửa còn lại."]}, {"q": "Câu 4 (1đ). [Tin 8 – Bài 12; năng lực AI] Trong hoạt động vận dụng, GV nhờ chatbot viết chương trình Scratch vẽ tam giác đều cạnh 100 bước. Chatbot trả lời: \"lặp lại 3 lần: di chuyển 100 bước, xoay phải 60 độ\".\n(a) Chương trình trên sai ở đâu? Nếu chạy thì bọ rùa vẽ ra gì, điểm cuối cách điểm đầu bao nhiêu bước?\n(b) Nêu 3 việc người dùng cần làm khi sử dụng kết quả do AI tạo ra.", "a": ["**(a) 0,6đ:** sai góc quay: tam giác đều phải quay **360° : 3 = 120°**, không phải 60° (60° là góc trong). Với 60° bọ rùa chỉ vẽ 3 cạnh liên tiếp của một lục giác đều (tổng góc quay 180°), đường gấp khúc **không khép kín**; điểm cuối cách điểm đầu **200 bước** (bằng đường kính lục giác cạnh 100).", "**(b) 0,4đ:** (1) **kiểm chứng** kết quả bằng SGK/chạy thử, so với kiến thức đã học (NL AI 8.A1.2); (2) **khai báo** có dùng AI và dùng ở phần nào; (3) **tự chịu trách nhiệm** về sản phẩm, không phụ thuộc, không sao chép nguyên văn (8.A3.3).", "Cách sửa: đổi góc 60 → 120; chạy thử lại để xác nhận hình khép kín."]}], "p3": [{"q": "Tình huống (2đ). Lớp 8A có nhóm học sinh dùng ứng dụng AI ghép mặt bạn nữ N vào ảnh không phù hợp rồi đăng lên nhóm Zalo của lớp. N bị bạn bè bàn tán, sợ không dám đi học. Phụ huynh N đến trường gặp bạn (giáo viên chủ nhiệm lớp 8A) và đề nghị công khai tên nhóm học sinh để \"cho cả trường biết\". Anh/chị xử lí như thế nào? Nêu căn cứ.", "a": ["**Xử lí (1,2đ):**", "- Tiếp nhận bình tĩnh, lắng nghe, bảo vệ ngay quyền lợi của N: yêu cầu gỡ ảnh khỏi nhóm, lưu bằng chứng (chụp màn hình, ghi nhận tên nhóm, thời điểm), không tiếp tục chia sẻ ảnh (0,3đ).", "- **Báo cáo kịp thời** với hiệu trưởng/ban giám hiệu và bộ phận tư vấn; không tự ý xử lí riêng hoặc che giấu (0,3đ).", "- Hỗ trợ tâm lí cho N (tư vấn tâm lí học đường, trò chuyện với gia đình); làm việc riêng với nhóm học sinh và phụ huynh các em; giáo dục là chính, việc xem xét kỉ luật thuộc hiệu trưởng theo quy định (0,3đ).", "- Với phụ huynh N: trao đổi trung thực, thông báo hướng xử lí; giải thích không công khai danh tính học sinh trái quy định để tránh gây thêm tổn thương; nếu cần, phối hợp cơ quan chức năng. Với lớp: tổ chức sinh hoạt về ứng xử trên mạng, rủi ro deepfake, tôn trọng quyền riêng tư (0,3đ).", "**Căn cứ (0,8đ):**", "- Thông tư 03/2026/TT-BGDĐT: Điều 5 khoản 4 (không xúc phạm, xâm hại người học; **phải báo cáo kịp thời** khi phát hiện người học bị bạo lực, xâm hại; không công khai thông tin người học trái quy định); Điều 4 khoản 6 (không thờ ơ, né tránh, che giấu vi phạm); Điều 4 khoản 2 (trách nhiệm ứng xử trên không gian mạng); Điều 8 khoản 2 (trao đổi thông tin trung thực với cha mẹ khi được cấp quản lí đồng ý theo thẩm quyền).", "- Luật Nhà giáo 73/2025/QH15 Điều 9 khoản 2 điểm d, e (bảo vệ quyền, lợi ích của người học; xây dựng môi trường giáo dục an toàn).", "- Điều lệ trường phổ thông (TT 15/2026): Điều 3 khoản 8 (phòng chống bạo lực học đường, tư vấn học sinh); Điều 33 khoản 6 (quyền được bảo vệ danh dự, nhân phẩm, tư vấn tâm lí học đường); Điều 10 khoản 1 điểm d (hiệu trưởng quyết định khen thưởng, kỉ luật học sinh).", "- Luật Giáo dục Điều 22 khoản 1 (cấm xúc phạm nhân phẩm, danh dự người học).", "Ghi chú: hình thức xử phạt hành chính/hình sự với hành vi ghép ảnh (nếu có) – đối chiếu văn bản gốc."]}]}, {"de": 17, "focus_luat": ["L8", "L1", "L3", "L5"], "focus_bai": ["B17", "B3", "B10"], "p1": [{"q": "Câu 1 (0,75đ). Theo Nghị quyết 71-NQ/TW ngày 22/8/2025 của Bộ Chính trị về đột phá phát triển giáo dục và đào tạo: (a) nêu 3 mục tiêu đến năm 2030 (về trường chuẩn quốc gia, phổ cập, hoàn thành THPT); (b) mức phụ cấp ưu đãi nghề tối thiểu đối với giáo viên, nhân viên và giáo viên vùng đặc biệt khó khăn; (c) tỉ lệ chi ngân sách nhà nước cho giáo dục và đào tạo.", "a": ["**(a) 0,3đ:** ít nhất **80%** trường phổ thông đạt chuẩn quốc gia; hoàn thành phổ cập giáo dục mầm non cho trẻ 3 đến 5 tuổi và giáo dục bắt buộc hết THCS; ít nhất **85%** người trong độ tuổi hoàn thành THPT và tương đương, không tỉnh nào dưới 60%.", "**(b) 0,25đ:** tối thiểu **70%** đối với giáo viên; tối thiểu **30%** đối với nhân viên mầm non, phổ thông; **100%** đối với giáo viên khu vực đặc biệt khó khăn, biên giới, hải đảo, vùng đồng bào dân tộc thiểu số và miền núi.", "**(c) 0,2đ:** tối thiểu **20%** tổng chi NSNN cho giáo dục và đào tạo; trong đó chi đầu tư ít nhất 5%, giáo dục đại học ít nhất 3%."]}, {"q": "Câu 2 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) nêu 4 hình thức kỉ luật viên chức và hình thức nào chỉ áp dụng với viên chức quản lí; (b) thời hiệu xử lí kỉ luật; (c) thời hạn xử lí kỉ luật; (d) trường hợp nào đương nhiên bị buộc thôi việc?", "a": ["**(a) 0,25đ:** khiển trách; cảnh cáo; cách chức (chỉ áp dụng với viên chức quản lí); buộc thôi việc (Điều 35 khoản 1).", "**(b) 0,2đ:** thời hiệu 05 năm đối với khiển trách; 10 năm đối với các hình thức còn lại (Điều 36 khoản 1); không áp dụng thời hiệu trong một số trường hợp (vd dùng văn bằng, chứng chỉ giả hoặc không hợp pháp – khoản 2).", "**(c) 0,15đ:** thời hạn xử lí kỉ luật không quá 90 ngày; vụ việc phức tạp kéo dài không quá 150 ngày (Điều 36 khoản 3).", "**(d) 0,15đ:** bị Tòa án kết án phạt tù không được hưởng án treo hoặc bị kết án tội tham nhũng thì đương nhiên bị buộc thôi việc kể từ ngày bản án có hiệu lực (Điều 35 khoản 3)."]}, {"q": "Câu 3 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15 Điều 11: (a) nêu 5 việc nhà giáo không được làm (khoản 2); (b) tổ chức, cá nhân không được đăng tải thông tin nào liên quan đến nhà giáo (khoản 3)?", "a": ["**(a) 0,5đ** (mỗi ý 0,1đ): phân biệt đối xử giữa những người học dưới mọi hình thức; gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học; ép buộc người học tham gia học thêm **dưới mọi hình thức**; ép buộc người học nộp tiền hoặc hiện vật ngoài quy định của pháp luật; lợi dụng chức danh nhà giáo và hoạt động nghề nghiệp để vi phạm pháp luật.", "**(b) 0,25đ:** không được đăng tải, phát tán thông tin mang tính quy kết về trách nhiệm của nhà giáo khi chưa có kết luận của cơ quan có thẩm quyền (Điều 11 khoản 3 điểm b); (còn không thực hiện đầy đủ chế độ, chính sách đối với nhà giáo – điểm a).", "Lưu ý: nhà giáo công lập còn không được làm những việc viên chức không được làm (khoản 1)."]}, {"q": "Câu 4 (0,75đ). Theo Nghị định 259/2026/NĐ-CP: (a) thi tuyển viên chức gồm mấy vòng, vòng 1 thi gì (số câu, thời gian), điều kiện để được dự vòng 2; (b) thời hạn người trúng tuyển hoàn thiện hồ sơ và giá trị pháp lí của hợp đồng làm việc; (c) việc tuyển dụng nhà giáo áp dụng văn bản nào là chủ yếu?", "a": ["**(a) 0,35đ:** 02 vòng. Vòng 1: trắc nghiệm trên máy tính – kiến thức chung 60 câu/60 phút; ngoại ngữ theo thông báo tuyển dụng (tối đa 60 phút, được miễn nếu có văn bằng/chứng chỉ phù hợp); trả lời đúng từ **50%** số câu của **từng phần** mới được dự vòng 2 (Điều 11 khoản 1). Vòng 2: nghiệp vụ chuyên ngành.", "**(b) 0,2đ:** hoàn thiện hồ sơ chậm nhất **15 ngày** kể từ ngày công khai danh sách trúng tuyển (Điều 20 khoản 1); ký hợp đồng làm việc chậm nhất 05 ngày làm việc; **hợp đồng làm việc có giá trị như quyết định tuyển dụng** (Điều 21).", "**(c) 0,2đ:** với giáo viên, ưu tiên áp dụng Nghị định 93/2026/NĐ-CP (Điều 7: vòng 1 phần kiến thức chung 60 câu/60 phút, ngoại ngữ 30 câu/30 phút; vòng 2 là thực hành sư phạm); NĐ 259 áp dụng cho hội đồng, trình tự, thủ tục chung (Điều 9 NĐ 93). Cụ thể từng địa phương – đối chiếu thông báo tuyển dụng và văn bản gốc."]}], "p2": [{"q": "Câu 1 (1đ). [Tin 8 – Bài 13: Biểu diễn dữ liệu] (a) Nêu khái niệm kiểu dữ liệu, hằng, biến. Kể 3 kiểu dữ liệu trong Scratch. (b) Cho biết kiểu và kết quả của các biểu thức: (1) 17 mod 5; (2) kết hợp \"3\" và \"5\"; (3) 3 + 5; (4) (7 > 4) và (2 > 5); (5) 360 / n khi n = 8.", "a": ["**(a) 0,4đ:** kiểu dữ liệu = tập các giá trị cùng các phép toán có thể thực hiện trên các giá trị đó; 3 kiểu: **số, xâu kí tự, lôgic**; hằng là đại lượng có giá trị không đổi trong quá trình chạy chương trình; biến có tên, giá trị có thể thay đổi.", "**(b) 0,6đ** (mỗi ý 0,12đ): (1) 17 mod 5 = **2** (số, chia lấy dư); (2) kết hợp \"3\" \"5\" = **\"35\"** (xâu kí tự, không phải số 35); (3) 3 + 5 = **8** (số); (4) (7 > 4) là đúng, (2 > 5) là sai → \"và\" cho kết quả **sai** (kiểu lôgic); (5) 360 / 8 = **45** (số; chính là góc quay khi vẽ đa giác 8 cạnh).", "Lưu ý: phép so sánh cho kết quả kiểu lôgic; HS hay nhầm xâu \"35\" với số 35."]}, {"q": "Câu 2 (1,5đ). [Tin 7 – Bài 5: Ứng xử trên mạng] Khảo sát 40 học sinh lớp 7 cho thấy: 14 em dùng mạng hơn 3 giờ mỗi ngày; 6 em từng bị bình luận xúc phạm trên mạng; 4 em thuộc cả hai nhóm.\n(a) Có bao nhiêu em thuộc ít nhất một nhóm, chiếm bao nhiêu phần trăm? Bao nhiêu em không thuộc nhóm nào?\n(b) Phân loại \"nên\" hoặc \"không nên\": (1) dùng ngôn ngữ lịch sự khi nhắn tin; (2) đăng ảnh bạn lên mạng khi chưa xin phép; (3) mở trang web có nội dung xấu để xem thử; (4) báo với thầy cô khi thấy tin nhắn đe dọa.\n(c) Nêu cách xử lí khi bị bắt nạt trên mạng và 4 cách phòng tránh nghiện Internet.", "a": ["**(a) 0,5đ:** ít nhất một nhóm = 14 + 6 − 4 = **16 em** (16 : 40 = **40%**); không thuộc nhóm nào = 40 − 16 = **24 em** (60%).", "**(b) 0,4đ** (mỗi ý 0,1đ): (1) nên; (2) không nên (cần xin phép); (3) không nên (nếu gặp trang xấu phải đóng ngay); (4) nên (nhờ người lớn giúp).", "**(c) 0,6đ:** bị bắt nạt: không đáp trả bằng lời lẽ xúc phạm; lưu bằng chứng (chụp màn hình); **chia sẻ với người lớn** (bố mẹ, thầy cô); chặn/báo cáo tài khoản vi phạm. Phòng tránh nghiện Internet (4 cách theo SGK): **chia sẻ** với người thân; **rời xa** thiết bị khi không cần; **giới hạn** thời gian dùng; **theo đuổi** sở thích, hoạt động lành mạnh khác.", "Kiểm chứng: 14 + 6 − 4 = 16; 16/40 = 0,4."]}, {"q": "Câu 3 (1,5đ). [Tin 7 – Bài 16: Thuật toán sắp xếp] Xây dựng **mục tiêu bài học** (bài 2 tiết) theo chương trình Tin học 2018 và yêu cầu cần đạt, gồm: kiến thức; năng lực tin học (kí hiệu NLa–NLe); năng lực chung; phẩm chất; năng lực số/AI. Nêu 1 hoạt động mở đầu phù hợp.", "a": ["**Kiến thức (0,4đ):** nêu ý nghĩa của sắp xếp dữ liệu (tăng dần, giảm dần) và của thao tác hoán đổi hai phần tử (cần chỗ trống tạm); giải thích, mô phỏng được sắp xếp **nổi bọt** và sắp xếp **chọn** với dãy số nhỏ; nêu ý nghĩa của việc chia bài toán thành bài toán nhỏ hơn.", "**Năng lực tin học (0,3đ):** **NLc** – mô phỏng, mô tả thuật toán sắp xếp; **NLd** – ứng dụng sắp xếp vào học tập (xếp chiều cao, điểm số); **NLe** – hợp tác kiểm tra từng bước, đối chiếu kết quả.", "**Năng lực chung (0,2đ):** tự chủ và tự học; giao tiếp và hợp tác; giải quyết vấn đề và sáng tạo. **Phẩm chất (0,2đ):** cẩn thận, chính xác; chăm chỉ; trách nhiệm trong nhóm.", "**Năng lực số/AI (0,1đ):** nêu hậu quả khi không xác thực kết quả AI, kiểm chứng bằng SGK/tự mô phỏng (7.A1.2, 7.A1.MR1).", "**Hoạt động mở đầu (0,3đ):** Hình 16.1 – đổi chỗ chất lỏng của cốc A và cốc B cần mấy bước? Vì sao phải dùng thêm cốc C (3 bước, cần chỗ trống tạm) → dẫn vào hoán đổi và sắp xếp. Kĩ thuật tia chớp/cặp đôi.", "Yêu cầu: mục tiêu viết bằng động từ đo được (nêu, giải thích, mô phỏng, thực hiện), không viết chung chung \"hiểu được\"."]}, {"q": "Câu 4 (1đ). [Tin 7 – Bài 16: nhận xét đoạn dạy] GV chiếu dãy 5, 2, 4, 1, 3 và nói: \"Nổi bọt là duyệt **từ đầu dãy**, so sánh hai số cạnh nhau, số trước lớn hơn số sau thì đổi chỗ. Sau **một lượt** là dãy đã sắp xếp xong.\" Rồi GV tự làm lượt 1 trên bảng, HS chỉ chép lại.\nHãy nhận xét: (a) kiến thức sai/chưa chặt chẽ; (b) cách tổ chức dạy học; (c) đề xuất cách sửa. Cho biết kết quả sau lượt 1 và số lượt cần thiết nếu làm đúng theo SGK (duyệt từ cuối dãy lên đầu).", "a": ["**(a) 0,4đ:** kết luận \"một lượt là xong\" **sai**: duyệt từ đầu, sau lượt 1 dãy là 2, 4, 1, 3, 5 (chưa sắp xếp). Cần lặp đến khi một lượt không còn hoán đổi. Cách duyệt từ đầu là biến thể (số lớn nổi về cuối) khác SGK (duyệt từ cuối lên đầu để số nhỏ nổi lên đầu) – gây nhầm nếu không nói rõ.", "**(b) 0,3đ:** GV làm thay, HS thụ động; chưa cho HS mô phỏng bằng thẻ số/bảng từng lượt; chưa có hoạt động hợp tác, kiểm tra chéo.", "**(c) 0,3đ:** cho HS dùng 5 thẻ số xếp thật, mô phỏng theo cặp, ghi bảng từng lượt; GV nêu rõ chiều duyệt thống nhất với SGK; chốt điều kiện dừng \"một lượt không có hoán đổi\".", "Theo SGK (duyệt từ cuối lên đầu, số nhỏ nổi lên đầu): lượt 1: **1, 5, 2, 4, 3** (3 lần đổi); lượt 2: 1, 2, 5, 3, 4; lượt 3: 1, 2, 3, 5, 4; lượt 4: **1, 2, 3, 4, 5**; lượt 5 không còn hoán đổi nên dừng. Tổng 7 lần hoán đổi, cần 4 lượt có hoán đổi (cộng 1 lượt kiểm tra)."]}], "p3": [{"q": "Tình huống (2đ). Cô M (giáo viên Toán cùng tổ với anh/chị) mở lớp dạy thêm tại nhà và nhắn vào nhóm phụ huynh lớp anh/chị chủ nhiệm: \"Em nào đi học thêm với cô thì cô ưu tiên cho điểm kiểm tra thường xuyên cao hơn\". Một học sinh kể lại việc này với anh/chị và có phụ huynh đòi anh/chị đăng nội dung tin nhắn lên nhóm lớp để \"phanh phui\". Anh/chị xử lí thế nào? Nêu căn cứ.", "a": ["**Xử lí (1,2đ):**", "- Bình tĩnh tiếp nhận, trấn an học sinh và phụ huynh; xác minh thông tin (xin bản chụp tin nhắn), không kết luận vội (0,3đ).", "- Trao đổi riêng, thẳng thắn, mang tính xây dựng với cô M (nếu phù hợp) và **báo cáo tổ trưởng chuyên môn/hiệu trưởng** để xác minh theo thẩm quyền; không né tránh, che giấu (0,4đ).", "- Không đăng nội dung lên nhóm lớp, không quy kết công khai khi chưa có kết luận; giải thích cho phụ huynh kênh phản ánh đúng quy định (0,3đ).", "- Bảo đảm học sinh không bị phân biệt, không bị ảnh hưởng đánh giá; kiểm tra lại cách chấm điểm của lớp mình để đúng thực chất (0,2đ).", "**Căn cứ (0,8đ):**", "- Luật Nhà giáo Điều 11 khoản 2: nhà giáo không được phân biệt đối xử, làm sai lệch kết quả đánh giá, ép buộc học thêm dưới mọi hình thức, lợi dụng chức danh để vi phạm pháp luật; khoản 3 điểm b: không đăng tải, phát tán thông tin quy kết trách nhiệm nhà giáo khi chưa có kết luận.", "- Thông tư 03/2026/TT-BGDĐT: Điều 4 khoản 6 (không lợi dụng chức danh; không thờ ơ, né tránh, che giấu vi phạm); Điều 5 khoản 3, 4 (đánh giá đúng thực chất; không gian lận, làm sai lệch kết quả đánh giá); Điều 6 khoản 3 (không xúc phạm, chia rẽ đồng nghiệp); Điều 8 khoản 4 (không ép buộc, vụ lợi với cha mẹ học sinh).", "- Luật Viên chức 2025 Điều 8 khoản 2 (báo cáo người có thẩm quyền khi phát hiện vi phạm); Luật Giáo dục Điều 22 khoản 5 (cấm ép buộc học sinh học thêm để thu tiền).", "- Quy định chi tiết về dạy thêm, học thêm (Thông tư 29/2024/TT-BGDĐT được sửa đổi bởi Thông tư 19/2026/TT-BGDĐT) – đối chiếu văn bản gốc."]}]}, {"de": 18, "focus_luat": ["L9", "L2", "L4", "L6"], "focus_bai": ["B18", "B4", "B11"], "p1": [{"q": "Câu 1 (0,75đ). Theo Điều lệ trường tiểu học, THCS, THPT và trường phổ thông nhiều cấp học (Thông tư 15/2026/TT-BGDĐT): (a) cơ quan nào quản lí trường THCS công lập; (b) hội đồng trường có ở trường công lập không; (c) hồ sơ của giáo viên gồm những loại nào (Điều 21); (d) nguyên tắc đánh giá học sinh (Điều 22).", "a": ["**(a) 0,15đ:** trường tiểu học, THCS và trường nhiều cấp có cấp cao nhất là THCS do **UBND cấp xã** quản lí (Phòng Văn hóa – Xã hội tham mưu); trường THPT do Sở GDĐT quản lí (Điều 6).", "**(b) 0,15đ:** hội đồng trường **chỉ có ở trường tư thục** (Điều 8, 9); trường công lập không có hội đồng trường theo Điều lệ này.", "**(c) 0,2đ:** giáo viên có kế hoạch bài dạy (giáo án); giáo viên chủ nhiệm có sổ chủ nhiệm; Tổng phụ trách Đội có sổ công tác Đội; hồ sơ quản lí chủ yếu dưới dạng điện tử, có giá trị pháp lí tương đương hồ sơ giấy (Điều 21).", "**(d) 0,25đ:** đánh giá toàn diện, công bằng, trung thực, khách quan, vì sự tiến bộ; chú trọng đánh giá quá trình; **không so sánh** học sinh này với học sinh khác; bảo mật thông tin, kết quả học tập; không gây áp lực cho học sinh, giáo viên, cha mẹ (Điều 22)."]}, {"q": "Câu 2 (0,75đ). Theo Luật Giáo dục 43/2019/QH14 (sửa đổi bởi Luật 123/2025/QH15): (a) nguyên lí giáo dục (Điều 3 khoản 2); (b) yêu cầu về phương pháp giáo dục phổ thông (Điều 30 khoản 3); (c) quy định mới về ứng dụng trí tuệ nhân tạo trong giáo dục (Điều 19); (d) đối tượng được miễn học phí theo Điều 99 khoản 3 mới.", "a": ["**(a) 0,2đ:** học đi đôi với hành, lí luận gắn liền với thực tiễn, giáo dục nhà trường kết hợp với giáo dục gia đình và giáo dục xã hội.", "**(b) 0,2đ:** phát huy tính tích cực, tự giác, chủ động, sáng tạo của học sinh; bồi dưỡng năng lực tự học, hứng thú học tập, kĩ năng hợp tác, tư duy độc lập; tăng cường ứng dụng công nghệ thông tin và truyền thông.", "**(c) 0,15đ:** Điều 19 (viết lại): khuyến khích ứng dụng **trí tuệ nhân tạo có kiểm soát** trong cơ sở giáo dục (khoản 3); Nhà nước đầu tư chuyển đổi số toàn diện (khoản 4).", "**(d) 0,2đ:** trẻ em mầm non, học sinh phổ thông, người học chương trình giáo dục phổ thông trong cơ sở giáo dục **công lập** được miễn học phí; cơ sở dân lập, tư thục được hỗ trợ tiền đóng học phí, mức do HĐND cấp tỉnh quyết định."]}, {"q": "Câu 3 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) nêu cấu trúc vòng 1 thi tuyển nhà giáo (số câu, thời gian từng phần); (b) vòng 2 gồm các hình thức nào, thời gian, thang điểm; (c) thẩm quyền điều động nhà giáo trong trường THCS công lập và thời hạn giải quyết hồ sơ điều động.", "a": ["**(a) 0,25đ:** trắc nghiệm trên máy tính: Phần I kiến thức chung **60 câu/60 phút**; Phần II ngoại ngữ **30 câu/30 phút** (không yêu cầu ngoại ngữ trong bản mô tả công việc thì không thi); đúng từ 50% số câu từng phần được thi vòng 2 (Điều 7 khoản 1).", "**(b) 0,25đ:** vòng 2 đánh giá qua thực hành sư phạm; người đứng đầu chọn 1 trong 3 hình thức: vấn đáp (30 phút, chuẩn bị không quá 15 phút), thực hành giảng dạy, thi viết (180 phút không kể chép đề); thang **100 điểm** (Điều 7 khoản 2).", "**(c) 0,25đ:** Chủ tịch UBND cấp xã điều động trong phạm vi quản lí; Giám đốc Sở GDĐT điều động giữa hai đơn vị hành chính cấp xã khác nhau hoặc lên cấp tỉnh (Điều 11 khoản 1); cơ quan có thẩm quyền ra quyết định trong **30 ngày làm việc** kể từ ngày nhận đủ hồ sơ hợp lệ, không đồng ý phải trả lời bằng văn bản nêu lí do (Điều 11 khoản 4 điểm b)."]}, {"q": "Câu 4 (0,75đ). Theo Nghị quyết 248/2025/QH15: (a) nghị quyết có hiệu lực từ ngày nào; (b) ai có thẩm quyền tuyển dụng nhà giáo trường phổ thông công lập trên địa bàn tỉnh; (c) ai có thẩm quyền điều động, thuyên chuyển nhà giáo thuộc thẩm quyền quản lí; (d) mức phụ cấp ưu đãi nghề tối thiểu theo lộ trình.", "a": ["**(a) 0,1đ:** 01/01/2026 (Điều 9 khoản 1); Quốc hội thông qua 10/12/2025.", "**(b) 0,2đ:** **Giám đốc Sở GDĐT** tuyển dụng, tiếp nhận nhà giáo, cán bộ quản lí, nhân viên cơ sở giáo dục mầm non, phổ thông, thường xuyên... công lập trên địa bàn tỉnh (Điều 2 khoản 1 điểm a); nếu điều động, thuyên chuyển liên quan từ 02 đơn vị hành chính cấp xã trở lên cũng thuộc Giám đốc Sở.", "**(c) 0,2đ:** **Chủ tịch UBND cấp xã** có thẩm quyền điều động, thuyên chuyển, biệt phái, bổ nhiệm, miễn nhiệm, thay đổi vị trí việc làm đối với nhà giáo, cán bộ quản lí, nhân viên thuộc thẩm quyền quản lí (Điều 2 khoản 1 điểm b).", "**(d) 0,25đ:** theo lộ trình Chính phủ quy định: tối thiểu 70% giáo viên; tối thiểu 30% nhân viên; 100% giáo viên biên giới, hải đảo, vùng dân tộc thiểu số, miền núi, vùng đặc biệt khó khăn (Điều 2 khoản 2 điểm a)."]}], "p2": [{"q": "Câu 1 (1đ). [Tin 8 – Bài 14: Cấu trúc điều khiển] (a) Nêu 3 cấu trúc điều khiển cơ bản; phân biệt rẽ nhánh khuyết với rẽ nhánh đầy đủ; kể 3 dạng cấu trúc lặp. (b) Xác định cấu trúc điều khiển trong từng tình huống: (1) \"Nếu trời mưa thì mang ô\"; (2) \"Nếu số đoán lớn hơn số bí mật thì báo 'Lớn quá', nếu không thì báo 'Nhỏ quá'\"; (3) \"Hỏi số đoán lại cho đến khi đoán đúng\".", "a": ["**(a) 0,5đ:** 3 cấu trúc: **tuần tự** (các lệnh thực hiện lần lượt từ trên xuống), **rẽ nhánh**, **lặp**. Rẽ nhánh **khuyết**: chỉ có nhánh khi điều kiện đúng (nếu... thì...); rẽ nhánh **đầy đủ**: có cả nhánh đúng và nhánh sai (nếu... thì... nếu không thì...). 3 dạng lặp: lặp số lần định trước; lặp vô hạn; lặp đến khi điều kiện đúng. Khối lệnh Scratch tương ứng: \"nếu... thì\", \"nếu... thì... nếu không thì\", \"lặp lại... lần\", \"lặp lại mãi\", \"lặp lại cho đến khi\".", "**(b) 0,5đ:** (1) rẽ nhánh **khuyết**; (2) rẽ nhánh **đầy đủ**; (3) **lặp đến khi điều kiện đúng** (lặp có điều kiện kết thúc, không phải lặp vô hạn).", "Lưu ý lỗi HS hay gặp: nhầm rẽ nhánh khuyết với đầy đủ; nhầm lặp vô hạn với lặp có điều kiện kết thúc."]}, {"q": "Câu 2 (1,5đ). [Tin 7 – Bài 6: Làm quen với phần mềm bảng tính] Bảng khảo sát cây xanh lưu trong trang tính: dòng 1 là tiêu đề cột (A: STT, B: Loại cây, C: Số lượng, D: Khu vực); dữ liệu của 12 loại cây nằm ở các dòng từ 2 đến 13.\n(a) Viết địa chỉ vùng chứa toàn bộ dữ liệu (không kể tiêu đề) và vùng gồm cả tiêu đề; mỗi vùng có bao nhiêu ô?\n(b) Số lượng của loại cây thứ 5 nằm ở ô nào?\n(c) Vùng B3:E10 có bao nhiêu ô? Vùng C2:C20 có bao nhiêu ô?\n(d) Dữ liệu \"Bàng\", \"25\", \"15/10/2025\" thuộc kiểu nào và căn lề mặc định ra sao?", "a": ["**(a) 0,4đ:** dữ liệu: **A2:D13** gồm 4 cột × 12 dòng = **48 ô**; kể cả tiêu đề: **A1:D13** gồm 4 × 13 = **52 ô**. (Địa chỉ vùng = ô trên trái : ô dưới phải.)", "**(b) 0,3đ:** loại cây thứ 1 ở dòng 2 nên loại thứ 5 ở dòng 6 → số lượng ở ô **C6**. (Địa chỉ ô viết cột trước, hàng sau – không viết 6C.)", "**(c) 0,4đ:** B3:E10: cột B–E = 4 cột, dòng 3–10 = 8 dòng → 4 × 8 = **32 ô**; C2:C20: 20 − 2 + 1 = **19 ô**.", "**(d) 0,4đ:** \"Bàng\": văn bản, căn trái; \"25\": số, căn phải; \"15/10/2025\": ngày tháng (nhận dạng là dữ liệu ngày tháng, căn phải).", "Lưu ý: HS hay nhầm hàng ghi tên cột (chữ A, B, C) với cột ghi tên hàng (số 1, 2, 3)."]}, {"q": "Câu 3 (1,5đ). [Tin 8 – Bài 2: Thông tin trong môi trường số] Trình bày cách tổ chức hoạt động hình thành kiến thức mục \"Thông tin đáng tin cậy\" bằng **kĩ thuật mảnh ghép** (15 phút) cho lớp 40 học sinh: chia nhóm thế nào, nhiệm vụ từng vòng, sản phẩm; viết 4 bước chuyển giao – thực hiện – báo cáo – kết luận; nêu 2 ưu điểm và 1 hạn chế cần khắc phục của kĩ thuật.", "a": ["**Nội dung chuyên môn (0,3đ):** 4 cách xác định thông tin đáng tin cậy: xác định **nguồn** thông tin; phân biệt **ý kiến** với **sự kiện**; kiểm tra **chứng cứ**; đánh giá **tính thời sự**. (Ba dạng tin không đáng tin cậy: không trung thực/lừa dối; đồn thổi; kết luận thiếu căn cứ.)", "**Tổ chức nhóm (0,3đ):** 40 HS chia **10 nhóm × 4 người**; vòng 1 (chuyên gia, ~5 phút): các HS đánh số 1–4, cùng số tập hợp thành nhóm chuyên gia đọc SGK và nắm một trong 4 cách, ghi từ khoá; vòng 2 (mảnh ghép, ~7 phút): HS về nhóm 4 người gồm đủ 4 chuyên gia, lần lượt truyền đạt, hoàn thành phiếu học tập (điền ví dụ cho từng cách).", "**4 bước (0,6đ):** (1) **Chuyển giao:** GV nêu mục tiêu, phát tài liệu/phiếu, đánh số HS, giao nhiệm vụ vòng 1 và 2, nêu thời gian; (2) **Thực hiện:** vòng chuyên gia – vòng mảnh ghép, GV quan sát, hỗ trợ nhóm vướng; (3) **Báo cáo:** 2–3 nhóm trình bày, mời HS bất kì giải thích một cách, nhóm khác nhận xét; (4) **Kết luận:** GV chốt 4 cách, chơi nhanh trò \"Ý kiến hay sự kiện?\", ghi nhớ.", "**Ưu điểm (0,2đ):** mọi HS đều có trách nhiệm cá nhân; tăng hợp tác, giao tiếp (NLe, năng lực chung giao tiếp và hợp tác). **Hạn chế (0,1đ):** HS chuyên gia truyền đạt sai/thiếu → GV kiểm tra, cho đối chiếu SGK, chốt lại.", "Năng lực: NLc (nhận biết thông tin số, chia sẻ có trách nhiệm), NLd (khai thác thông tin số để học); phẩm chất trung thực, trách nhiệm."]}, {"q": "Câu 4 (1đ). [Tin 8 – Bài 2; năng lực AI] Chatbot trả lời học sinh: \"(1) Khi xoá ảnh trên máy thì thông tin biến mất hoàn toàn; (2) thông tin trên Internet đều tự do sử dụng, không có bản quyền; (3) thông tin số dễ nhân bản, lan truyền.\" Hãy chỉ ra nhận định sai và giải thích; nêu quy trình HS cần làm để kiểm chứng và khai báo khi dùng câu trả lời của AI.", "a": ["**Nhận định sai (0,5đ):** (1) **sai** – thông tin số khó xoá bỏ hoàn toàn (ảnh gốc còn trên máy chủ, thiết bị người khác đã tải/chia sẻ, bản sao lưu); (2) **sai** – hầu hết thông tin trên Internet có bản quyền, cần xin phép, ghi nguồn; (3) đúng.", "**Quy trình (0,5đ):** đối chiếu từng nhận định với SGK/nguồn chính thống (xác định nguồn, kiểm tra chứng cứ); chạy thử/hỏi thầy cô khi chưa chắc; chỉ dùng phần đã kiểm chứng; **khai báo** có dùng AI và phần nào; hiểu người dùng chịu trách nhiệm về nội dung (8.A1.2).", "Liên hệ: AI tạo sinh có thể sai chi tiết, thiếu nguồn nên không tin tuyệt đối."]}], "p3": [{"q": "Tình huống (2đ). Sáng thứ Hai, anh/chị là giáo viên Tin học và phát hiện phòng máy 30 máy chỉ còn 18 máy hoạt động tốt do mất điện đột ngột cuối tuần. Tiết 3 anh/chị phải tổ chức bài kiểm tra thực hành 45 phút cho lớp 9A có 36 học sinh. Nhà trường chưa có kinh phí sửa chữa ngay, một đồng nghiệp gợi ý \"cứ cho điểm theo bài lí thuyết cho nhanh\". Anh/chị xử lí thế nào? Nêu căn cứ.", "a": ["**Xử lí (1,2đ):**", "- Báo cáo ngay với tổ trưởng/ban giám hiệu và nhân viên thiết bị về số máy hỏng, đề xuất sửa chữa, thay thế; không tự ý xử lí ngoài thẩm quyền (0,3đ).", "- Phương án chuyên môn: 36 học sinh / 18 máy = **2 em/máy** – chia **2 ca** (mỗi ca 18 em/18 máy, mỗi ca 20–22 phút) hoặc làm theo cặp luân phiên; hoặc điều chỉnh lịch kiểm tra sang tiết khác; chuẩn bị đề thực hành phù hợp thời lượng; có phương án dự phòng (phiếu mô phỏng/vẽ sơ đồ khối) (0,5đ).", "- Bảo đảm công bằng: cùng một đề và tiêu chí chấm, thông báo trước cho học sinh và thống nhất với giáo viên chủ nhiệm; không dùng điểm lí thuyết thay thế điểm thực hành khi chưa đúng quy định (0,2đ).", "- Rút kinh nghiệm: kiểm tra, bảo trì thiết bị định kì, ghi sổ theo dõi sử dụng phòng máy (0,2đ).", "**Căn cứ (0,8đ):**", "- Điều lệ trường phổ thông (TT 15/2026): Điều 3 khoản 9 (quản lí cơ sở vật chất, thiết bị; xã hội hóa); Điều 3 khoản 3 (quyết định phương pháp, hình thức tổ chức hoạt động giáo dục); Điều 18 (thiết bị dạy học; giáo viên tự làm thiết bị); Điều 22 (đánh giá công bằng, trung thực, khách quan, không gây áp lực).", "- Luật Nhà giáo 73/2025/QH15 Điều 8 khoản 2 điểm a (chủ động sắp xếp nội dung, thời lượng theo chương trình); Điều 9 khoản 2 điểm a (thực hiện đầy đủ, có chất lượng chương trình).", "- Luật Viên chức 2025 Điều 8 khoản 1, 2 (thực hiện đúng nhiệm vụ, báo cáo người có thẩm quyền); Điều 10 khoản 1 (không trốn tránh, đùn đẩy nhiệm vụ).", "- Thông tư 03/2026/TT-BGDĐT Điều 4 khoản 2 (tận tụy, bảo đảm chất lượng chương trình), Điều 5 khoản 3 (đánh giá đúng thực chất).", "Kiểm chứng số liệu: 30 − 12 = 18 máy tốt; 36 : 18 = 2."]}]}, {"de": 19, "focus_luat": ["L1", "L3", "L5", "L7"], "focus_bai": ["B19", "B5", "B12"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Viên chức 129/2025/QH15: (a) viên chức là ai (Điều 1); (b) viên chức được ký hợp đồng làm việc với tối đa bao nhiêu đơn vị sự nghiệp công lập; (c) hợp đồng làm việc gồm những loại nào; (d) nêu 3 trường hợp hợp đồng làm việc chấm dứt theo Điều 22 khoản 4.", "a": ["**(a) 0,25đ:** công dân Việt Nam, được tuyển dụng theo vị trí việc làm, làm việc tại đơn vị sự nghiệp công lập theo chế độ hợp đồng làm việc, hưởng lương từ quỹ tiền lương của đơn vị sự nghiệp công lập và từ các nguồn thu hợp pháp khác.", "**(b) 0,1đ:** chỉ được ký hợp đồng làm việc với **01** đơn vị sự nghiệp công lập và chịu sự quản lí của đơn vị đó (Điều 8 khoản 5).", "**(c) 0,15đ:** hợp đồng làm việc **xác định thời hạn** và **không xác định thời hạn** (Điều 20 khoản 3).", "**(d) 0,25đ:** (1) viên chức bị kỉ luật buộc thôi việc; (2) bị xếp loại không hoàn thành nhiệm vụ vì lí do chuyên môn, nghiệp vụ hoặc không đáp ứng yêu cầu vị trí việc làm; (3) trường hợp khác theo pháp luật ngành, lĩnh vực hoặc theo thỏa thuận (Điều 22 khoản 4). Thời hạn báo trước khi đơn phương chấm dứt: dẫn chiếu pháp luật lao động (đối chiếu văn bản gốc)."]}, {"q": "Câu 2 (0,75đ). Theo Luật Nhà giáo 73/2025/QH15: (a) phương thức tuyển dụng nhà giáo (Điều 14 khoản 1 điểm b); (b) ai không được đăng kí tuyển dụng (Điều 14 khoản 4); (c) hai trường hợp không được thuyên chuyển (Điều 19 khoản 2); (d) chính sách tiền lương đối với nhà giáo công lập (Điều 23 khoản 1 điểm a).", "a": ["**(a) 0,15đ:** thi tuyển hoặc xét tuyển, trong đó **phải có thực hành sư phạm**.", "**(b) 0,25đ:** mất hoặc hạn chế năng lực hành vi dân sự, khó khăn trong nhận thức, làm chủ hành vi; đang bị truy cứu trách nhiệm hình sự, đang chấp hành bản án, quyết định hình sự, biện pháp đưa vào cơ sở cai nghiện bắt buộc, cơ sở giáo dục bắt buộc; đã có tiền án về tội xâm phạm an ninh quốc gia, tính mạng, sức khỏe, nhân phẩm, danh dự con người.", "**(c) 0,2đ:** đang bị xem xét kỉ luật, đang bị kiểm tra, xác minh, thanh tra, điều tra, truy tố, xét xử; chưa đủ **03 năm** công tác kể từ ngày được tuyển dụng (trừ trường hợp tự nguyện đến vùng dân tộc thiểu số, miền núi, biên giới, hải đảo, vùng đặc biệt khó khăn).", "**(d) 0,15đ:** lương của nhà giáo được xếp **cao nhất** trong hệ thống thang bậc lương hành chính sự nghiệp; ngoài ra có phụ cấp ưu đãi nghề và phụ cấp khác theo tính chất công việc, theo vùng."]}, {"q": "Câu 3 (0,75đ). Theo Nghị định 259/2026/NĐ-CP và Nghị định 93/2026/NĐ-CP: (a) nêu các mức điểm ưu tiên khi tuyển dụng viên chức, cộng vào vòng nào, thuộc nhiều diện thì sao; (b) người có từ đủ 03 năm giảng dạy phù hợp được cộng thêm bao nhiêu điểm; (c) viên chức tuyển dụng từ 01/7/2026 có phải tập sự không; xếp lương khởi điểm thế nào?", "a": ["**(a) 0,3đ:** 7,5 điểm (Anh hùng, thương binh...); 5 điểm (người dân tộc thiểu số, con liệt sĩ, quân nhân/công an phục viên, xuất ngũ...); 2,5 điểm (hoàn thành nghĩa vụ quân sự, nghĩa vụ công an nhân dân...); 1,5 điểm (cán bộ công đoàn trưởng thành từ cơ sở); cộng vào kết quả **vòng 2**; thuộc nhiều diện chỉ cộng mức **cao nhất** (NĐ 259 Điều 8).", "**(b) 0,15đ:** **05 điểm** vào vòng 2 (người có từ đủ 03 năm/36 tháng giảng dạy phù hợp, có đóng BHXH bắt buộc); thuộc nhiều diện chỉ cộng điểm cao nhất (NĐ 93 Điều 6 khoản 1, 4).", "**(c) 0,3đ:** không còn chế độ tập sự: người tuyển từ 01/7/2026 được bổ nhiệm, xếp lương theo vị trí việc làm tuyển dụng (cơ sở: Điều 43 khoản 4 Luật Viên chức; số điều chuyển tiếp trong NĐ 259 – đối chiếu văn bản gốc). Tuyển vào bậc nghề nghiệp nào thì xếp mức lương **khởi điểm** của bậc đó (NĐ 259 Điều 10 khoản 1); người có thời gian công tác phù hợp, có đóng BHXH thì người đứng đầu xem xét xếp bậc lương phù hợp (khoản 2)."]}, {"q": "Câu 4 (0,75đ). So sánh Thông tư 06/2019/TT-BGDĐT và Thông tư 03/2026/TT-BGDĐT về quy tắc ứng xử: (a) hiệu lực hiện nay của Điều 6 TT06; (b) 5 giá trị cốt lõi của TT06 (Điều 3); (c) quy định về hút thuốc, đồ uống có cồn của hai thông tư; (d) trách nhiệm báo cáo của thủ trưởng cơ sở giáo dục theo TT06 (Điều 13).", "a": ["**(a) 0,15đ:** Điều 6 TT06 (ứng xử của giáo viên) **hết hiệu lực từ 30/01/2026**, thay bằng TT03/2026; các điều còn lại của TT06 (ứng xử của cán bộ quản lí, nhân viên, người học, cha mẹ, khách) vẫn là văn bản gốc (mức độ còn hiệu lực từng điều sau các văn bản mới – đối chiếu văn bản gốc).", "**(b) 0,2đ:** **nhân ái, tôn trọng, trách nhiệm, hợp tác, trung thực** (Điều 3 khoản 2 TT06).", "**(c) 0,25đ:** TT06 Điều 4 khoản 6: không hút thuốc, dùng đồ uống có cồn, chất cấm **trong cơ sở giáo dục**; TT03 Điều 4 khoản 6: không hút thuốc lá, dùng đồ uống có cồn **khi thực hiện nhiệm vụ**; không dùng chất cấm, kích thích, không tham gia tệ nạn xã hội.", "**(d) 0,15đ:** thủ trưởng quy định cụ thể Bộ Quy tắc, công khai (website/niêm yết), tuyên truyền; tổ chức thực hiện, đánh giá, báo cáo cấp quản lí trực tiếp **định kì mỗi năm học**; khen thưởng, kỉ luật (Điều 13)."]}], "p2": [{"q": "Câu 1 (1đ). [Tin 8 – Bài 15: Gỡ lỗi] (a) Kiểm thử là gì? Phân biệt lỗi cú pháp và lỗi lôgic. (b) Nêu 2 cách phát hiện lỗi lôgic. (c) Chương trình \"chẵn/lẻ\" (nhập số n, nếu n chia 2 dư 0 thì báo \"lẻ\", ngược lại báo \"chẵn\") thuộc loại lỗi nào? Đề xuất 4 ca kiểm thử.", "a": ["**(a) 0,4đ:** kiểm thử = chạy thử chương trình để phát hiện lỗi; lỗi **cú pháp**: viết sai quy tắc, chương trình không chạy được/báo lỗi; lỗi **lôgic**: chương trình vẫn chạy nhưng kết quả không đúng kịch bản mong muốn.", "**(b) 0,2đ:** (1) phân tích lôgic các khối lệnh (đọc, đối chiếu với thuật toán); (2) theo dõi giá trị biến (hiện biến, dùng lệnh \"đợi ... giây\") và chạy thử từng bước.", "**(c) 0,4đ:** lỗi **lôgic** (điều kiện/nhãn bị đảo ngược). Sửa: nếu n mod 2 = 0 thì báo \"chẵn\". Ca kiểm thử: n = 4 (chẵn, mong đợi \"chẵn\"); n = 7 (lẻ, mong đợi \"lẻ\"); n = 0 (ca biên, \"chẵn\"); n = −3 hoặc nhập chữ (ca lỗi/ngoài miền, xem chương trình xử lí thế nào).", "Lưu ý: HS hay nhầm lỗi lôgic là chương trình ngừng chạy; sau khi sửa phải **chạy thử lại**."]}, {"q": "Câu 2 (1,5đ). [Tin 7 – Bài 7: Tính toán tự động trên bảng tính] Bảng thống kê rừng (đơn vị: nghìn ha) từ dòng 3 đến dòng 6:\nA3:A6 – Khu A, B, C, D\nB (rừng tự nhiên): 300; 180; 240; 90\nC (rừng trồng): 100; 120; 160; 10\nD = tổng diện tích rừng; E = tỉ lệ rừng trồng (%) = C/D × 100.\n(a) Viết công thức tại D3 và E3; sao chép xuống dòng 5 thì công thức tại D5 là gì? Cho biết giá trị D3:D6 và E3:E6.\n(b) Nếu sửa C4 từ 120 thành 170 thì D4, E4 thay đổi thế nào (làm tròn E4 hai chữ số thập phân)?\n(c) Nếu sao chép công thức ở D3 sang ô E3 thì E3 chứa công thức gì và giá trị bao nhiêu?\n(d) Chỉ ra lỗi: \"B3*C3\"; \"=B3 x C3\".", "a": ["**(a) 0,5đ:** D3 **=B3+C3**; E3 **=C3/D3*100**; sao chép xuống dòng 5: D5 **=B5+C5** (địa chỉ tương đối đổi theo dòng). D3:D6 = 400; 300; 400; 100. E3:E6 = 25; 40; 40; 10.", "**(b) 0,4đ:** bảng tính tự động cập nhật: D4 = 180 + 170 = **350**; E4 = 170/350*100 = 48,5714... ≈ **48,57**.", "**(c) 0,3đ:** sao chép sang phải 1 cột nên mỗi địa chỉ dịch 1 cột: E3 = **=C3+D3** (tại E3 cột C→D, cột B→C: công thức gốc =B3+C3 trở thành =C3+D3) = 100 + 400 = **500**.", "**(d) 0,3đ:** \"B3*C3\" thiếu dấu **=** đầu công thức nên bị hiểu là văn bản; \"=B3 x C3\" nhầm chữ x với dấu nhân **\\***, đúng là =B3*C3.", "Kiểm chứng: 300+100 = 400; 100/400*100 = 25; 180+120 = 300; 120/300*100 = 40; 240+160 = 400; 160/400*100 = 40; 90+10 = 100; 10/100*100 = 10."]}, {"q": "Câu 3 (1,5đ). [Tin 8 – Bài 4: Đạo đức và văn hoá trong sử dụng công nghệ kĩ thuật số] Thiết kế **phiếu/thang đánh giá (rubric)** sản phẩm \"khẩu hiệu hoặc áp phích nhắc bạn dùng công nghệ số đúng chuẩn mực\" (Hoạt động Vận dụng) với 3 mức, thang 10 điểm; nêu cách tổ chức đánh giá theo 4 bước, gồm cả tự đánh giá và đánh giá đồng đẳng.", "a": ["**Nội dung chuyên môn (0,3đ):** bốn yêu cầu của sản phẩm số: trung thực; tự tạo nội dung; có đạo đức, văn hoá; không vi phạm pháp luật. 3 điều lưu ý: tìm hiểu quy định; chỉ dùng khi được phép; hầu hết thông tin trên Internet có bản quyền.", "**Rubric (0,6đ):** 4 tiêu chí × 2 điểm + trình bày 2 điểm = 10 điểm. Mức tốt (2đ): thông điệp đúng chuẩn mực, nêu rõ ít nhất một hành động (xin phép, ghi nguồn, tôn trọng quyền riêng tư); mức đạt (1đ): đúng nhưng chung chung hoặc thiếu một yêu cầu; mức chưa đạt (0đ): sai hoặc vi phạm (dùng ảnh người khác không ghi nguồn, nội dung phản cảm). Tiêu chí: (1) trung thực, ghi nguồn; (2) tự tạo nội dung; (3) đạo đức, văn hoá; (4) đúng pháp luật, bản quyền; (5) trình bày (ngắn gọn, thẩm mĩ, có **dòng khai báo có/không dùng AI**).", "**4 bước (0,4đ):** (1) **Chuyển giao:** GV nêu nhiệm vụ, phát rubric cho HS đọc; (2) **Thực hiện:** HS phác thảo, tự đánh giá theo rubric, chỉnh sửa; (3) **Báo cáo:** 2–3 HS trình bày 1 phút, bạn nhận xét theo rubric (đánh giá đồng đẳng); (4) **Kết luận:** GV nhận xét, thống nhất điểm, tuyên dương, dặn hoàn thiện.", "**Năng lực/phẩm chất đánh giá (0,2đ):** NLb (ứng xử phù hợp), NLd (tạo sản phẩm số trung thực, ghi nguồn); phẩm chất trách nhiệm, trung thực. Nguyên tắc: đánh giá vì sự tiến bộ, tiêu chí công khai trước khi làm."]}, {"q": "Câu 4 (1đ). [Tin 7 – Bài 7; năng lực AI] Học sinh hỏi chatbot cách tính tổng số cây ở ô D3 (số HS ở B3, số cây mỗi HS ở C3). Chatbot trả lời: \"Gõ B3*C3 vào ô D3, rồi sao chép xuống D4, công thức vẫn giữ nguyên là B3*C3\". Hãy chỉ ra 2 chỗ sai và nêu cách để HS kiểm chứng và khai báo khi dùng AI.", "a": ["**Hai chỗ sai (0,6đ):** (1) công thức phải **bắt đầu bằng dấu =**: =B3*C3; (2) khi sao chép xuống D4, địa chỉ tương đối thay đổi theo dòng thành **=B4*C4**, không giữ nguyên.", "**Kiểm chứng (0,4đ):** đối chiếu SGK, thử trực tiếp trên bảng tính (nhập, sao chép, xem thanh công thức); hỏi thầy cô; khai báo có dùng AI và phần nào (7.A1.2, 7.A1.MR1, 7.B3.1). Nếu không kiểm chứng, số liệu sai sẽ dẫn đến kết quả tính toán sai (hậu quả khi không xác thực kết quả AI)."]}], "p3": [{"q": "Tình huống (2đ). Anh/chị phạt học sinh T (lớp 9B) trừ điểm kiểm tra 15 phút vì phát hiện em chép bài của bạn. Tối đó, phụ huynh T đăng lên nhóm Zalo phụ huynh của lớp, gắn tên anh/chị: \"Cô giáo thiên vị, dạy kém, ép trẻ con, ai cũng biết\" và kêu gọi mọi người cùng phản đối. Nhiều phụ huynh nhắn riêng hỏi anh/chị. Anh/chị xử lí thế nào? Nêu căn cứ.", "a": ["**Xử lí (1,2đ):**", "- Giữ bình tĩnh, **không đáp trả** hay đăng bài tranh luận trên nhóm; lưu bằng chứng (chụp màn hình, thời gian) (0,3đ).", "- Báo cáo hiệu trưởng/ban giám hiệu để cùng xử lí theo thẩm quyền; không tự ý nhờ phụ huynh khác can thiệp (0,3đ).", "- Mời phụ huynh T gặp trực tiếp (có đại diện nhà trường): trình bày trung thực sự việc, minh chứng (bài kiểm tra, quy chế đánh giá), lắng nghe, giải thích việc xử lí nhằm giáo dục chứ không trù dập; đề nghị gỡ bài viết (0,3đ).", "- Trao đổi với em T, tiếp tục đánh giá công bằng, không để ảnh hưởng quan hệ thầy trò; phối hợp ban đại diện cha mẹ học sinh/GVCN để thông tin chính xác cho nhóm phụ huynh theo kênh chính thống (0,3đ).", "**Căn cứ (0,8đ):**", "- Luật Nhà giáo 73/2025/QH15 Điều 11 khoản 3 điểm b (không đăng tải, phát tán thông tin quy kết trách nhiệm nhà giáo khi chưa có kết luận); Điều 8 khoản 2 điểm c (được tôn trọng, bảo vệ uy tín, danh dự, nhân phẩm); Điều 37 (xử lí hành vi xâm phạm uy tín, danh dự, nhân phẩm nhà giáo).", "- Thông tư 06/2019/TT-BGDĐT Điều 9 khoản 2 (cha mẹ người học không bịa đặt thông tin, không xúc phạm danh dự, nhân phẩm giáo viên – điều này còn hiệu lực).", "- Thông tư 03/2026/TT-BGDĐT: Điều 8 (ứng xử với cha mẹ: hợp tác, trao đổi thông tin trung thực; không xúc phạm, ép buộc); Điều 4 khoản 2 và Điều 9 khoản 3 (có trách nhiệm khi ứng xử trên không gian mạng, chống tin giả); Điều 5 khoản 3 (đánh giá đúng thực chất).", "- Luật Viên chức 2025 Điều 10 khoản 6 (viên chức không được xúc phạm danh dự, nhân phẩm người khác khi thực hiện hoạt động nghề nghiệp). Trách nhiệm của gia đình tôn trọng nhà giáo (Luật Giáo dục Điều 90) – đối chiếu văn bản gốc số khoản."]}]}, {"de": 20, "focus_luat": ["L2", "L4", "L6", "L8"], "focus_bai": ["B20", "B6", "B13"], "p1": [{"q": "Câu 1 (0,75đ). Theo Luật Giáo dục 43/2019/QH14: (a) nêu 6 hành vi bị nghiêm cấm trong cơ sở giáo dục (Điều 22); (b) phân biệt quy định về học thêm của Điều 22 Luật Giáo dục với Điều 11 khoản 2 Luật Nhà giáo; (c) Điều 20 Luật Giáo dục cấm điều gì?", "a": ["**(a) 0,4đ** (6 ý, mỗi ý khoảng 0,07đ): (1) xúc phạm nhân phẩm, danh dự, xâm phạm thân thể nhà giáo, cán bộ, người lao động và người học; (2) xuyên tạc nội dung giáo dục; (3) gian lận trong học tập, kiểm tra, thi, tuyển sinh; (4) hút thuốc; uống rượu, bia; gây rối an ninh, trật tự; (5) ép buộc học sinh học thêm để thu tiền; (6) lợi dụng việc tài trợ, ủng hộ giáo dục để ép buộc đóng góp tiền hoặc hiện vật.", "**(b) 0,25đ:** Luật Giáo dục Điều 22 khoản 5 chỉ cấm \"ép buộc học sinh học thêm **để thu tiền**\"; Luật Nhà giáo Điều 11 khoản 2 điểm c cấm nhà giáo \"ép buộc người học tham gia học thêm **dưới mọi hình thức**\" (rộng hơn).", "**(c) 0,1đ:** không truyền bá tôn giáo, tiến hành lễ nghi tôn giáo trong cơ sở giáo dục của hệ thống giáo dục quốc dân (Điều 20)."]}, {"q": "Câu 2 (0,75đ). Theo Nghị định 93/2026/NĐ-CP: (a) nguyên tắc thuyên chuyển nhà giáo và thành phần hồ sơ; (b) dạy liên trường, liên cấp: ai ra quyết định phân công, số tiết dạy tính thế nào, ai trả lương; (c) nội dung đánh giá nhà giáo theo chuẩn nghề nghiệp.", "a": ["**(a) 0,25đ:** thuyên chuyển theo **nguyện vọng** của nhà giáo; phải được sự đồng ý của cơ sở/cơ quan nơi đi và nơi đến, phù hợp vị trí việc làm (Điều 12 khoản 1). Hồ sơ gồm: đơn (Mẫu số 01), văn bản đồng ý cho liên hệ công tác của nơi đi, văn bản đồng ý tiếp nhận của nơi đến (khoản 3 điểm a). Thời hạn giải quyết thuyên chuyển – đối chiếu văn bản gốc.", "**(b) 0,3đ:** UBND cấp xã hoặc Sở GDĐT (theo cơ sở thuộc quản lí) ra **quyết định phân công**, xác định rõ thời gian, khối lượng giảng dạy, trách nhiệm phối hợp (Điều 13 khoản 2); số tiết theo chế độ làm việc = **tổng số tiết** ở các cơ sở được phân công (khoản 3 điểm a); lương và chế độ theo lương do **cơ sở quản lí nhà giáo** chi trả; đánh giá do người đứng đầu cơ sở quản lí nhà giáo thực hiện trên cơ sở nhận xét của cơ sở nơi đến dạy (điểm b, c).", "**(c) 0,2đ:** đạo đức nhà giáo và việc chấp hành quy tắc ứng xử; trình độ đào tạo, bồi dưỡng; năng lực chuyên môn, nghiệp vụ theo yêu cầu chức danh gắn với vị trí việc làm (Điều 14 khoản 1 điểm a); nhà giáo công lập còn đáp ứng tiêu chí đánh giá, xếp loại viên chức (4 mức theo Luật Viên chức)."]}, {"q": "Câu 3 (0,75đ). Theo Nghị quyết 248/2025/QH15: (a) bộ sách giáo khoa nào được sử dụng thống nhất toàn quốc, thực hiện từ năm học nào, đến năm nào hoàn thành miễn phí SGK; (b) khi hội đồng trường công lập chấm dứt hoạt động thì xử lí chuyển tiếp thế nào (Điều 7); (c) khi quy định của nghị quyết khác với luật khác thì áp dụng văn bản nào (Điều 9).", "a": ["**(a) 0,25đ:** Bộ trưởng Bộ GDĐT quyết định **một bộ** sách giáo khoa giáo dục phổ thông sử dụng thống nhất toàn quốc, thực hiện từ năm học **2026–2027**; đến năm **2030** hoàn thành cung cấp miễn phí SGK cho học sinh (Điều 3 khoản 1).", "**(b) 0,3đ:** trong **06 tháng** sau khi hội đồng trường chấm dứt, cơ quan quản lí trực tiếp quyết định công việc tổ chức, nhân sự do hội đồng trường đảm nhiệm và quyết định người đứng đầu theo tiêu chuẩn do Bộ trưởng quy định; cho phép số lượng cấp phó vượt quy định tối đa trong **05 năm**, lập kế hoạch giảm dần (Điều 7).", "**(c) 0,2đ:** áp dụng quy định của Nghị quyết 248; nếu văn bản của Quốc hội ban hành sau có chính sách ưu đãi hơn thì áp dụng văn bản đó (Điều 9 khoản 2, 3). Bổ sung: tối thiểu 20% tổng chi NSNN cho giáo dục và đào tạo (Điều 6 khoản 4)."]}, {"q": "Câu 4 (0,75đ). Theo Nghị quyết 71-NQ/TW: (a) ban hành ngày nào, cơ quan nào; (b) phương châm về thầy – trò và vị trí của người học, nhà trường, nhà giáo; (c) chủ trương về hội đồng trường và người đứng đầu cơ sở giáo dục công lập; (d) chủ trương về tiếng Anh, trí tuệ nhân tạo ở phổ thông và về dạy thêm, học thêm.", "a": ["**(a) 0,1đ:** 22/8/2025, Bộ Chính trị (Tổng Bí thư Tô Lâm ký); 06 quan điểm chỉ đạo, 08 nhóm nhiệm vụ, giải pháp.", "**(b) 0,2đ:** phương châm \"**thầy ra thầy, trò ra trò**\"; người học là trung tâm, chủ thể; nhà trường là nền tảng; nhà giáo là động lực, quyết định chất lượng giáo dục.", "**(c) 0,2đ:** **không tổ chức hội đồng trường** trong cơ sở giáo dục công lập (trừ trường có thỏa thuận quốc tế); bí thư cấp ủy kiêm người đứng đầu cơ sở giáo dục.", "**(d) 0,25đ:** từng bước đưa tiếng Anh thành ngôn ngữ thứ hai trong trường học, nâng chuẩn tiếng Anh cho giáo viên và học sinh; nghiên cứu đưa năng lực số, AI vào chương trình phổ thông, nâng chuẩn năng lực số và AI cho người học và nhà giáo; khắc phục dạy thêm, học thêm tràn lan."]}], "p2": [{"q": "Câu 1 (1đ). [Tin 8 – Bài 16: Tin học với nghề nghiệp] (a) Nêu 5 lợi ích của việc ứng dụng tin học trong công việc. (b) Phân loại 6 nghề sau thành \"nghề thuộc lĩnh vực tin học\" và \"nghề liên quan ứng dụng tin học\": lập trình viên; kế toán; quản trị mạng; streamer; thiết kế website; bán hàng trực tuyến. (c) Nêu 2 biểu hiện bình đẳng giới trong sử dụng máy tính và ứng dụng tin học.", "a": ["**(a) 0,4đ:** tin học (1) nâng cao hiệu quả công việc; (2) tăng tốc độ xử lí; (3) liên lạc, trao đổi dễ dàng; (4) làm việc nhóm, mở rộng phạm vi làm việc; (5) nâng cao tay nghề, hỗ trợ thông tin cho người lao động.", "**(b) 0,36đ** (mỗi nghề 0,06đ): thuộc lĩnh vực tin học: **lập trình viên, quản trị mạng, thiết kế website**; liên quan ứng dụng tin học: **kế toán, streamer, bán hàng trực tuyến** (HS hay nhầm streamer, bán hàng online là nghề tin học).", "**(c) 0,24đ:** mọi giới đều có cơ hội học, sử dụng máy tính và làm các nghề tin học như nhau; không định kiến \"nam giỏi công nghệ hơn nữ\" (ví dụ nhà toán học Ada Lovelace; các chương trình khuyến khích nữ học công nghệ như DigiGirlZ); khuyến khích việc làm thúc đẩy bình đẳng giới."]}, {"q": "Câu 2 (1,5đ). [Tin 7 – Bài 8: Công cụ hỗ trợ tính toán] Điểm môn Toán của 8 học sinh nhập tại C3:C10: 8; 6,5; 9; 7; (ô C7 để trống); 5,5; \"Vắng\" (văn bản); 10.\n(a) Viết cú pháp tổng quát của hàm và nêu chức năng của 5 hàm SUM, AVERAGE, MAX, MIN, COUNT.\n(b) Cho biết giá trị của =SUM(C3:C10), =AVERAGE(C3:C10), =MAX(C3:C10), =MIN(C3:C10), =COUNT(C3:C10).\n(c) Bạn Nam tính trung bình bằng =SUM(C3:C10)/8 ra kết quả khác. Hãy tính và giải thích.\n(d) Tại K4 có =SUM(D4:J4), sao chép xuống K5 thì công thức là gì?", "a": ["**(a) 0,4đ:** cú pháp **=<tên hàm>(<tham số>)**, tham số là số, ô hoặc vùng ô; SUM – tính tổng; AVERAGE – trung bình cộng; MAX – giá trị lớn nhất; MIN – giá trị nhỏ nhất; COUNT – đếm số ô chứa **số**.", "**(b) 0,6đ:** chỉ các ô chứa số được tính (bỏ qua ô trống và văn bản): các số là 8; 6,5; 9; 7; 5,5; 10 (6 số). SUM = **46**; AVERAGE = 46 : 6 ≈ **7,67**; MAX = **10**; MIN = **5,5**; COUNT = **6**.", "**(c) 0,3đ:** =SUM(C3:C10)/8 = 46 : 8 = **5,75** ≠ 7,67 vì chia cho 8 ô (kể cả ô trống và ô \"Vắng\"); hàm AVERAGE chỉ chia cho 6 ô chứa số. Nhầm lẫn thường gặp: COUNT chỉ đếm ô số, không đếm mọi ô.", "**(d) 0,2đ:** K5 = **=SUM(D5:J5)** (địa chỉ tương đối đổi theo dòng).", "Kiểm chứng: 8 + 6,5 + 9 + 7 + 5,5 + 10 = 46; 46/6 = 7,6667; 46/8 = 5,75."]}, {"q": "Câu 3 (1,5đ). [Tin 8 – Bài 5: Sử dụng bảng tính giải quyết bài toán thực tế] Thiết kế **hoạt động Khám phá** (15 phút) giúp học sinh phát hiện sự cần thiết của địa chỉ tuyệt đối: nêu tình huống số liệu cụ thể (bảng giá có tỉ lệ giảm ở ô cố định), dự kiến sai lầm của học sinh, 4 bước chuyển giao – thực hiện – báo cáo – kết luận, mục tiêu năng lực.", "a": ["**Tình huống (0,4đ):** bảng giá: C5 = 200 000; C6 = 150 000; C7 = 80 000 (đồng); ô D2 chứa tỉ lệ giảm 10%. Yêu cầu: tính giá sau giảm ở D5:D7 bằng công thức rồi kéo núm điền. Công thức đúng: D5 **=C5*(1-$D$2)** → 180 000; D6 → 135 000; D7 → 72 000. Nếu HS gõ =C5*(1-D2) rồi kéo, D6 thành =C6*(1-D3), D7 thành =C7*(1-D4) với D3, D4 trống (= 0) nên cho 150 000 và 80 000 (không giảm).", "**Sai lầm dự kiến (0,2đ):** quên ký hiệu $ ở ô cố định; gắn $ cho cả ô đổi theo dòng; gõ lại công thức từng dòng; không kiểm tra kết quả sau khi kéo.", "**4 bước (0,6đ):** (1) **Chuyển giao:** GV nêu bài toán, phát bảng dữ liệu, yêu cầu làm theo cặp, dự đoán kết quả trước khi kéo; (2) **Thực hiện:** HS nhập công thức =C5*(1-D2), kéo, quan sát kết quả sai, quan sát thanh công thức để tìm nguyên nhân; thử gõ $ hoặc nhấn **F4** để cố định D2; GV gợi ý \"ô nào phải giữ cố định khi kéo?\"; (3) **Báo cáo:** 2–3 cặp trình bày nguyên nhân và cách sửa, đối chiếu kết quả; (4) **Kết luận:** GV chốt địa chỉ tương đối thay đổi khi sao chép, địa chỉ tuyệt đối (\\$D\\$2) không đổi; cách tạo bằng $ hoặc F4.", "**Mục tiêu (0,3đ):** NLc – chọn và dùng bảng tính tính toán, kiểm tra kết quả; NLd – xử lí số liệu học tập; NLe – kiểm tra chéo công thức cùng bạn; năng lực chung tự chủ, hợp tác, giải quyết vấn đề; phẩm chất chăm chỉ, cẩn thận, trung thực.", "Kiểm chứng: 200 000 × 0,9 = 180 000; 150 000 × 0,9 = 135 000; 80 000 × 0,9 = 72 000."]}, {"q": "Câu 4 (1đ). [Tin 8 – Bài 16; năng lực AI] GV hỏi chatbot: \"Hãy mô tả một lập trình viên\". Chatbot trả lời: \"Lập trình viên thường là nam giới, giỏi toán; nữ giới ít phù hợp với nghề này\". Hãy: (a) chỉ ra vấn đề của câu trả lời; (b) nêu cách giáo viên hướng dẫn học sinh phản biện và kiểm chứng; (c) nêu 2 việc học sinh cần làm khi dùng AI để tìm hiểu nghề.", "a": ["**(a) 0,4đ:** câu trả lời mang **định kiến giới** (thuật toán/dữ liệu huấn luyện có thể thiên vị), trái nội dung bình đẳng giới trong tin học; nhận định \"nữ ít phù hợp\" không có căn cứ.", "**(b) 0,3đ:** cho HS đối chiếu SGK (nghề thuộc lĩnh vực tin học, bình đẳng giới), tìm ví dụ ngược lại (Ada Lovelace, nhiều lập trình viên nữ), thảo luận vì sao AI có thể thiên vị, yêu cầu viết lại mô tả trung lập, không nêu giới tính.", "**(c) 0,3đ:** (1) kiểm chứng thông tin bằng SGK và nguồn tin cậy trước khi dùng (8.A1.2/8.B1.1); (2) nhận diện, không chấp nhận nội dung thiên vị, khai báo khi dùng AI và tự chịu trách nhiệm."]}], "p3": [{"q": "Tình huống (2đ). Cuối học kì I, Hiệu trưởng họp tổ Tin – Công nghệ và yêu cầu: \"Điểm kiểm tra cuối kì của 5 em lớp 8C đang thiếu 0,5–1 điểm để đạt loại Khá, các thầy cô nâng điểm lên để tỉ lệ học sinh khá giỏi của trường đạt chỉ tiêu thi đua\". Anh/chị là giáo viên dạy lớp 8C. Anh/chị xử lí thế nào? Nêu căn cứ.", "a": ["**Xử lí (1,2đ):**", "- Bình tĩnh, không phản ứng gay gắt trước tập thể; thể hiện thiện chí tôn trọng cấp quản lí và mục tiêu nâng chất lượng (0,2đ).", "- **Không thực hiện** việc nâng điểm sai thực chất; giải thích rõ lí do pháp lí và chuyên môn; đề xuất giải pháp đúng: rà soát lại bài, chấm lại theo đáp án để loại trừ sai sót chấm (nếu có), ôn tập bổ trợ, kiểm tra lại theo quy định cho các em còn yếu (0,5đ).", "- Tham mưu trực tiếp với hiệu trưởng, tổ trưởng bằng ý kiến có căn cứ (có thể bằng văn bản); nếu bị yêu cầu thực hiện bằng văn bản/mệnh lệnh, từ chối phần trái pháp luật và báo cáo cấp có thẩm quyền; không chia sẻ trên mạng xã hội, không che giấu (0,3đ).", "- Giữ nguyên hồ sơ điểm, bảo mật thông tin kết quả của học sinh; thông báo công khai đúng quy định (0,2đ).", "**Căn cứ (0,8đ):**", "- Luật Nhà giáo 73/2025/QH15 Điều 11 khoản 2 điểm b (không được gian lận, cố ý làm sai lệch kết quả trong tuyển sinh, đánh giá người học); Điều 9 khoản 2 điểm b (liêm chính học thuật).", "- Thông tư 03/2026/TT-BGDĐT: Điều 4 khoản 3 (chống bệnh thành tích); Điều 5 khoản 3 (đánh giá đúng thực chất năng lực), khoản 4 (không gian lận, làm sai lệch kết quả đánh giá); Điều 7 khoản 1, 3 (chấp hành phân công trong phạm vi chức năng, nhiệm vụ; tham mưu, thể hiện rõ chính kiến) và khoản 4 (không thờ ơ, né tránh, che giấu sai phạm của cán bộ quản lí); Điều 4 khoản 6.", "- Luật Viên chức 2025: Điều 11 khoản 6 (quyền từ chối thực hiện công việc nếu cho rằng trái pháp luật); Điều 8 khoản 2 (báo cáo người có thẩm quyền khi phát hiện vi phạm pháp luật trong đơn vị).", "- Điều lệ trường phổ thông (TT 15/2026) Điều 22 (đánh giá công bằng, trung thực, khách quan, không so sánh, không gây áp lực); Luật Giáo dục Điều 22 khoản 3 (cấm gian lận trong học tập, kiểm tra, thi)."]}]}];